DG.put("giaan-prabodh/1",{"n":1,"title":"ਅਥ ਗਿਆਨ ਪ੍ਰਬੋਧ ਗ੍ਰੰਥ ਲਿਖ੍ਯਤੇ।","title_roman":"Ath giaan prabodh granth likhyate |","page":251,"blocks":[{"type":"heading","kind":"chhand","name":"ਭੁਜੰਗ ਪ੍ਰਯਾਤ ਛੰਦ","gurmukhi":"ਭੁਜੰਗ ਪ੍ਰਯਾਤ ਛੰਦ। ਤ੍ਵਪ੍ਰਸਾਦਿ","roman":"Bhujang prayaat chhand | tvaprasaadi","meaning_en":"Bhujang Prayat metre. By Your grace.","page":251,"invocation":"ਤ੍ਵਪ੍ਰਸਾਦਿ","meaning_status":"draft"},{"type":"verse","number":[1],"number_text":"੧।","page":251,"lines":[{"gurmukhi":"ਨਮੋ ਨਾਥ ਪੂਰੇ ਸਦਾ ਸਿਧ ਕਰਮੰ। ਅਛੇਦੀ ਅਭੇਦੀ ਸਦਾ ਏਕ ਧਰਮੰ।","roman":"Namo naath poore sadaa sidh karman | achhedee abhedee sadaa ek dharman |","meaning_en":"Salutation to the perfect Lord, whose works are ever accomplished; indestructible, beyond mystery, ever of one law;","page":251,"meaning_status":"draft","note":"ਧਰਮੰ: 'law/nature'; may also be read 'ever of one faith/duty'."},{"gurmukhi":"ਕਲੰਕੰ ਬਿਨਾ ਨਿਹਕਲੰਕੀ ਸਰੂਪੇ। ਅਛੇਦੰ ਅਭੇਦੰ ਅਖੇਦੰ ਅਨੂਪੇ। ੧।","roman":"Kalankan binaa nihaklankee saroope | achhedan abhedan akhedan anoope | 1 |","meaning_en":"without stain, of spotless form; unbreakable, unfathomable, free of sorrow, incomparable.","page":251,"meaning_status":"draft"}]},{"type":"verse","number":[2],"number_text":"੨।","page":251,"lines":[{"gurmukhi":"ਨਮੋ ਲੋਕ ਲੋਕੇਸ੍ਵਰੰ ਲੋਕ ਨਾਥੇ। ਸਦੈਵੰ ਸਦਾ ਸਰਬ ਸਾਥੰ ਅਨਾਥੇ।","roman":"Namo lok lokesvaran lok naathe | sadaivan sadaa sarab saathan anaathe |","meaning_en":"Salutation to the Lord of the worlds, the Master of the worlds; ever and always the companion of all, of the helpless;","page":251,"meaning_status":"draft","note":"ਸਰਬ ਸਾਥੰ ਅਨਾਥੇ: read as 'companion of all, (Himself) without master' or 'companion of the masterless'; uncertain."},{"gurmukhi":"ਨੋਮ ਏਕ ਰੂਪੰ ਅਨੇਕੰ ਸਰੂਪੇ। ਸਦਾ ਸਰਬ ਸਾਹੰ ਸਦਾ ਸਰਬ ਭੂਪੇ। ੨।","roman":"Nom ek roopan anekan saroope | sadaa sarab saahan sadaa sarab bhoope | 2 |","meaning_en":"Salutation to the One of single form and of many forms; ever the King of all, ever the Sovereign of all.","page":251,"meaning_status":"draft","note":"Printed ਨੋਮ; read as ਨਮੋ 'salutation'."}]},{"type":"verse","number":[3],"number_text":"੩।","page":251,"lines":[{"gurmukhi":"ਅਛੇਦੰ ਅਭੇਦੰ ਅਨਾਮੰ ਅਠਾਮੰ। ਸਦਾ ਸਰਬਦਾ ਸਿਧਦਾ ਬੁਧਿ ਧਾਮੰ।","roman":"Achhedan abhedan anaaman athaaman | sadaa sarabdaa sidhdaa budhi dhaaman |","meaning_en":"Unbreakable, beyond mystery, nameless, without fixed abode; ever and always the giver of success, the home of wisdom;","page":251,"meaning_status":"draft"},{"gurmukhi":"ਅਜੰਤ੍ਰੰ ਅਮੰਤ੍ਰੰ ਅਕੰਤ੍ਰੰ ਅਭਰੰਮੰ। ਅਖੇਦੰ ਅਭੇਦੰ ਅਛੇਦੰ ਅਕਰਮੰ। ੩।","roman":"Ajantran amantran akantran abhranman | akhedan abhedan achhedan akarman | 3 |","meaning_en":"beyond yantra, mantra and tantra, free of illusion; free of sorrow, beyond mystery, indestructible, beyond karma.","page":251,"meaning_status":"draft","note":"ਅਕੰਤ੍ਰੰ: read as 'beyond tantra'."}]},{"type":"verse","number":[4],"number_text":"੪।","page":251,"lines":[{"gurmukhi":"ਅਗਾਧੇ ਅਬਾਧੇ ਅਗੰਤੰ ਅਨੰਤੰ। ਅਲੇਖੰ ਅਭੇਖੰ ਅਭੂਤੰ ਅਗੰਤੰ।","roman":"Agaadhe abaadhe agantan anantan | alekhan abhekhan abhootan agantan |","meaning_en":"Unfathomable, unobstructed, beyond reach, endless; beyond writing, without guise, not born of the elements, unreachable.","page":251,"meaning_status":"draft","note":"ਅਗੰਤੰ repeated in the line; first read as 'beyond reach', second perhaps 'without end/going'."},{"gurmukhi":"ਨ ਰੰਗੰ ਨ ਰੂਪੰ ਨ ਜਾਤੰ ਨ ਪਾਤੰ। ਨ ਸਤ੍ਰੋ ਨ ਮਿਤ੍ਰੋ ਨ ਪੁਤ੍ਰੋ ਨ ਮਾਤੰ। ੪।","roman":"Na rangan na roopan na jaatan na paatan | na satro na mitro na putro na maatan | 4 |","meaning_en":"He has no colour, no form, no caste, no lineage; no enemy, no friend, no son, no mother.","page":251,"meaning_status":"draft"}]},{"type":"verse","number":[5],"number_text":"੫।","page":251,"lines":[{"gurmukhi":"ਅਭੂਤੰ ਅਭੰਗੰ ਅਭਿਖੰ ਭਵਾਨੰ। ਪਰੇਯੰ ਪੁਨੀਤੰ ਪਵਿਤ੍ਰੰ ਪ੍ਰਧਾਨੰ।","roman":"Abhootan abhangan abhikhan bhavaanan | pareyan puneetan pavitran pradhaanan |","meaning_en":"Not of the elements, unbreakable, without guise, the existing One; beyond all, holy, pure, supreme.","page":251,"meaning_status":"draft","note":"ਭਵਾਨੰ: read as 'the Being/existent'; uncertain."},{"gurmukhi":"ਅਗੰਜੇ ਅਭੰਜੇ ਅਕਾਮੰ ਅਕਰਮੰ। ਅਨੰਤੇ ਬਿਅੰਤੇ ਅਭੂਮੇ ਅਭਰਮੰ। ੫।","roman":"Aganje abhanje akaaman akarman | anante biante abhoome abharman | 5 |","meaning_en":"Unconquerable, unbreakable, desireless, beyond karma; endless, limitless, beyond place, free of illusion.","page":251,"meaning_status":"draft","note":"ਅਭੂਮੇ: 'without land/place'; uncertain."}]},{"type":"verse","number":[6],"number_text":"੬।","page":251,"lines":[{"gurmukhi":"ਨਹੀ ਜਾਨ ਜਾਈ ਕਛੂ ਰੂਪ ਰੇਖੰ। ਕਹਾ ਬਾਸੁ ਤਾ ਕੋ ਫਿਰੈ ਕਉਨ ਭੇਖੰ।","roman":"Nahee jaan jaaee kachhoo roop rekhan | kahaa baasu taa ko phirai kaun bhekhan |","meaning_en":"His form and outline cannot be known at all; where is His dwelling, in what guise does He move?","page":251,"meaning_status":"draft"},{"gurmukhi":"ਕਹਾ ਨਾਮ ਤਾ ਕੋ ਕਹਾ ਕੈ ਕਹਾਵੈ। ਕਹਾ ਮੈ ਬਖਾਨੋ ਕਹੈ ਮੈ ਨ ਆਵੈ। ੬।","roman":"Kahaa naam taa ko kahaa kai kahaavai | kahaa mai bakhaano kahai mai na aavai | 6 |","meaning_en":"What is His name, by what is He called? How can I describe Him? He is beyond my telling.","page":251,"meaning_status":"draft"}]},{"type":"verse","number":[7],"number_text":"੭।","page":252,"lines":[{"gurmukhi":"ਅਜੋਨੀ ਅਜੈ ਪਰਮ ਰੂਪੀ ਪ੍ਰਧਾਨੈ। ਅਛੇਦੀ ਅਭੇਦੀ ਅਰੂਪੀ ਮਹਾਨੈ।","roman":"Ajonee ajai param roopee pradhaanai | achhedee abhedee aroopee mahaanai |","meaning_en":"Unborn, unconquered, of supreme form, foremost; indestructible, beyond mystery, formless, great;","page":252,"meaning_status":"draft"},{"gurmukhi":"ਅਸਾਧੇ ਅਗਾਧੇ ਅਗੰਜੁਲ ਗਨੀਮੇ। ਅਰੰਜੁਲ ਅਰਾਧੇ ਰਹਾਕੁਲ ਰਹੀਮੇ। ੭।","roman":"Asaadhe agaadhe aganjul ganeeme | aranjul araadhe rahaakul raheeme | 7 |","meaning_en":"beyond effort, unfathomable, the Conqueror of foes; free of sorrow, adored, the Liberator, the Merciful.","page":252,"meaning_status":"draft","note":"Persian/Arabic: ਅਗੰਜੁਲ ਗਨੀਮੇ read as 'conqueror of enemies' (ganj-ul-ghanim? uncertain); ਅਰੰਜੁਲ 'without sorrow' (ranj); ਰਹਾਕੁਲ 'liberator' (rihai); ਰਹੀਮੇ 'merciful'. All uncertain."}]},{"type":"verse","number":[8],"number_text":"੮।","page":252,"lines":[{"gurmukhi":"ਸਦਾ ਸਰਬਦਾ ਸਿਧਦਾ ਬੁਧਿ ਦਾਤਾ। ਨਮੋ ਲੋਕ ਲੋਕੇਸ੍ਵਰੰ ਲੋਕ ਗ੍ਯਾਤਾ।","roman":"Sadaa sarabdaa sidhdaa budhi daataa | namo lok lokesvaran lok gyaataa |","meaning_en":"Ever and always the giver of success and of wisdom; salutation to the Lord of the worlds, the Knower of the worlds.","page":252,"meaning_status":"draft"},{"gurmukhi":"ਅਛੇਦੀ ਅਭੈ ਆਦਿ ਰੂਪੰ ਅਨੰਤੰ। ਅਛੇਦੀ ਅਛੈ ਆਦਿ ਅਦ੍ਵੈ ਦੁਰੰਤੰ। ੮।","roman":"Achhedee abhai aadi roopan anantan | achhedee achhai aadi advai durantan | 8 |","meaning_en":"Indestructible, fearless, the primal form, endless; indestructible, imperishable, primal, non-dual, unreachable.","page":252,"meaning_status":"draft","note":"ਦੁਰੰਤੰ: 'hard to reach the end of'; uncertain."}]},{"type":"heading","kind":"chhand","name":"ਨਰਾਜ ਛੰਦ","gurmukhi":"ਨਰਾਜ ਛੰਦ","roman":"Naraaj chhand","meaning_en":"Naraj metre.","page":252,"meaning_status":"draft"},{"type":"verse","number":[1,9],"number_text":"੧। ੯।","page":252,"lines":[{"gurmukhi":"ਅਨੰਤ ਆਦਿ ਦੇਵ ਹੈ। ਬਿਅੰਤ ਭਰਮ ਭੇਵ ਹੈ।","roman":"Anant aadi dev hai | biant bharam bhev hai |","meaning_en":"He is the endless primal God; His mystery is boundless.","page":252,"meaning_status":"draft","note":"ਭਰਮ ਭੇਵ: perhaps 'His mystery is beyond doubt/illusion'; uncertain."},{"gurmukhi":"ਅਗਾਧਿ ਬਿਆਧਿ ਨਾਸ ਹੈ। ਸਦੈਵ ਸਰਬ ਪਾਸ ਹੈ। ੧। ੯।","roman":"Agaadhi biaadhi naas hai | sadaiv sarab paas hai | 1 | 9 |","meaning_en":"He destroys unfathomable ailments; He is ever near to all.","page":252,"meaning_status":"draft"}]},{"type":"verse","number":[2,10],"number_text":"੨। ੧੦।","page":252,"lines":[{"gurmukhi":"ਬਚਿਤ੍ਰ ਚਿਤ੍ਰ ਚਾਪ ਹੈ। ਅਖੰਡ ਦੁਸਟ ਖਾਪ ਹੈ।","roman":"Bachitr chitr chaap hai | akhand dusat khaap hai |","meaning_en":"His bow is wondrous and colourful; He is the unbroken destroyer of the wicked.","page":252,"meaning_status":"draft","note":"ਚਿਤ੍ਰ ਚਾਪ: 'wondrous bow'; may also read 'wondrous picture'; uncertain."},{"gurmukhi":"ਅਭੇਦ ਆਦਿ ਕਾਲ ਹੈ। ਸਦੈਵ ਸਰਬ ਪਾਲ ਹੈ। ੨। ੧੦।","roman":"Abhed aadi kaal hai | sadaiv sarab paal hai | 2 | 10 |","meaning_en":"He is the mysterious primal Death (Kal); He is ever the sustainer of all.","page":252,"meaning_status":"draft"}]},{"type":"verse","number":[3,11],"number_text":"੩। ੧੧।","page":252,"lines":[{"gurmukhi":"ਅਖੰਡ ਚੰਡ ਰੂਪ ਹੈ। ਪ੍ਰਚੰਡ ਸਰਬ ਸ੍ਰੂਪ ਹੈ।","roman":"Akhand chand roop hai | prachand sarab sroop hai |","meaning_en":"His form is unbroken and fierce; He is mighty, the form of all.","page":252,"meaning_status":"draft"},{"gurmukhi":"ਕਾਲ ਹੂੰ ਕੇ ਕਾਲ ਹੈ। ਸਦੈਵ ਰਛਪਾਲ ਹੈ। ੩। ੧੧।","roman":"Kaal hoon ke kaal hai | sadaiv rachhpaal hai | 3 | 11 |","meaning_en":"He is the Death of death itself; He is ever the protector.","page":252,"meaning_status":"draft"}]},{"type":"verse","number":[4,12],"number_text":"੪। ੧੨।","page":252,"lines":[{"gurmukhi":"ਕ੍ਰਿਪਾਲ ਦਿਆਲ ਰੂਪ ਹੈ। ਸਦੈਵ ਸਰਬ ਭੂਪ ਹੈ।","roman":"Kripaal diaal roop hai | sadaiv sarab bhoop hai |","meaning_en":"His form is gracious and merciful; He is ever the King of all.","page":252,"meaning_status":"draft"},{"gurmukhi":"ਅਨੰਤ ਸਰਬ ਆਸ ਹੈ। ਪਰੇਵ ਪਰਮ ਪਾਸ ਹੈ। ੪। ੧੨।","roman":"Anant sarab aas hai | parev param paas hai | 4 | 12 |","meaning_en":"He is the endless hope of all; He is beyond the beyond, yet near.","page":252,"meaning_status":"draft","note":"ਪਰੇਵ ਪਰਮ ਪਾਸ: read as 'beyond, the supreme, and near'; uncertain."}]},{"type":"verse","number":[5,13],"number_text":"੫। ੧੩।","page":252,"lines":[{"gurmukhi":"ਅਦ੍ਰਿਸਟ ਅੰਤ੍ਰ ਧਿਆਨ ਹੈ। ਸਦੈਵ ਸਰਬ ਮਾਨ ਹੈ।","roman":"Adrisat antr dhiaan hai | sadaiv sarab maan hai |","meaning_en":"He is unseen, reached in inner meditation; He is ever honoured by all.","page":252,"meaning_status":"draft"},{"gurmukhi":"ਕ੍ਰਿਪਾਲ ਕਾਲ ਹੀਨ ਹੈ। ਸਦੈਵ ਸਾਧ ਅਧੀਨ ਹੈ। ੫। ੧੩।","roman":"Kripaal kaal heen hai | sadaiv saadh adheen hai | 5 | 13 |","meaning_en":"He is gracious and free from death; He is ever subject to His saints.","page":252,"meaning_status":"draft"}]},{"type":"verse","number":[6,14],"number_text":"੬। ੧੪।","page":252,"lines":[{"gurmukhi":"ਭਜਸ ਤੁਯੰ। ਭਜਸ ਤੁਯੰ। ਰਹਾਉ।","roman":"Bhajas tuyan | bhajas tuyan | rahaau |","meaning_en":"I worship You, I worship You. (Pause)","page":252,"meaning_status":"draft","note":"ਭਜਸ ਤੁਯੰ: 'I worship/meditate on You'."},{"gurmukhi":"ਅਗਾਧਿ ਬਿਆਧਿ ਨਾਸਨੰ। ਪਰੇਯੰ ਪਰਮ ਉਪਾਸਨੰ।","roman":"Agaadhi biaadhi naasnan | pareyan param upaasnan |","meaning_en":"Destroyer of unfathomable ailments, beyond all, worthy of supreme worship,","page":252,"meaning_status":"draft"},{"gurmukhi":"ਤ੍ਰਿਕਾਲ ਲੋਕ ਮਾਨ ਹੈ। ਸਦੈਵ ਪੁਰਖ ਪਰਧਾਨ ਹੈ। ੬। ੧੪।","roman":"Trikaal lok maan hai | sadaiv purakh pardhaan hai | 6 | 14 |","meaning_en":"honoured in the three times and the worlds; He is ever the foremost Being.","page":252,"meaning_status":"draft"}]},{"type":"verse","number":[7,15],"number_text":"੭। ੧੫।","page":252,"lines":[{"gurmukhi":"ਤਥਸ ਤੁਯੰ। ਤਥਸ ਤੁਯੰ। ਰਹਾਉ।","roman":"Tathas tuyan | tathas tuyan | rahaau |","meaning_en":"So are You, so are You. (Pause)","page":252,"meaning_status":"draft","note":"ਤਥਸ ਤੁਯੰ: read as 'thus/true are You'; uncertain."},{"gurmukhi":"ਕ੍ਰਿਪਾਲ ਦਿਆਲ ਕਰਮ ਹੈ। ਅਗੰਜ ਭੰਜ ਭਰਮ ਹੈ।","roman":"Kripaal diaal karam hai | aganj bhanj bharam hai |","meaning_en":"His deeds are gracious and merciful; He is unconquerable, the breaker of illusion.","page":252,"meaning_status":"draft"},{"gurmukhi":"ਤ੍ਰਿਕਾਲ ਲੋਕ ਪਾਲ ਹੈ। ਸਦੈਵ ਸਰਬ ਦਿਆਲ ਹੈ। ੭। ੧੫।","roman":"Trikaal lok paal hai | sadaiv sarab diaal hai | 7 | 15 |","meaning_en":"He sustains the worlds in the three times; He is ever merciful to all.","page":252,"meaning_status":"draft"}]},{"type":"verse","number":[8,16],"number_text":"੮। ੧੬।","page":252,"lines":[{"gurmukhi":"ਜਪਸ ਤੁਯੰ। ਜਪਸ ਤੁਯੰ। ਰਹਾਉ।","roman":"Japas tuyan | japas tuyan | rahaau |","meaning_en":"I repeat Your name, I repeat Your name. (Pause)","page":252,"meaning_status":"draft"},{"gurmukhi":"ਮਹਾਨ ਮੋਨ ਮਾਨ ਹੈ। ਪਰੇਵ ਪਰਮ ਪ੍ਰਧਾਨ ਹੈ।","roman":"Mahaan mon maan hai | parev param pradhaan hai |","meaning_en":"He is great, honoured by silent sages; He is beyond, supreme, foremost.","page":252,"meaning_status":"draft","note":"ਮਹਾਨ ਮੋਨ ਮਾਨ: perhaps 'great, silent, honoured'; uncertain."},{"gurmukhi":"ਪੁਰਾਨ ਪ੍ਰੇਤ ਨਾਸਨੰ। ਸਦੈਵ ਸਰਬ ਪਾਸਨੰ। ੮। ੧੬।","roman":"Puraan pret naasnan | sadaiv sarab paasnan | 8 | 16 |","meaning_en":"He is ancient, the destroyer of ghosts; ever He is near to all.","page":252,"meaning_status":"draft","note":"ਪੁਰਾਨ ਪ੍ਰੇਤ ਨਾਸਨੰ: 'ancient, destroyer of ghosts' or 'destroyer of old ghosts/evils'; uncertain."}]},{"type":"verse","number":[9,17],"number_text":"੯। ੧੭।","page":252,"lines":[{"gurmukhi":"ਪ੍ਰਚੰਡ ਅਖੰਡ ਮੰਡਲੀ। ਉਦੰਡ ਰਾਜ ਸੁ ਥਲੀ।","roman":"Prachand akhand mandlee | udand raaj su thalee |","meaning_en":"Mighty, of an unbroken realm, His kingdom is exalted and fair;","page":252,"meaning_status":"draft","note":"ਮੰਡਲੀ: 'realm/circle'; ਉਦੰਡ 'lofty, unrestrained'."},{"gurmukhi":"ਜਗੰਤ ਜੋਤਿ ਜੁਆਲਕਾ। ਜਲੰਤ ਦੀਪ ਮਾਲਕਾ। ੯। ੧੭।","roman":"Jagant joti juaalkaa | jalant deep maalkaa | 9 | 17 |","meaning_en":"His light blazes like a flame, like a burning row of lamps.","page":252,"meaning_status":"draft"}]},{"type":"verse","number":[10,18],"number_text":"੧੦। ੧੮।","page":253,"lines":[{"gurmukhi":"ਕ੍ਰਿਪਾਲ ਦਿਆਲ ਲੋਚਨੰ। ਮੰਚਕ ਬਾਣ ਮੋਚਨੰ।","roman":"Kripaal diaal lochnan | manchak baan mochnan |","meaning_en":"His eyes are gracious and merciful; He looses arrows from His bow.","page":253,"meaning_status":"draft","note":"ਮੰਚਕ: printed so; perhaps a bow or 'shower'; uncertain."},{"gurmukhi":"ਸਿਰੰ ਕਰੀਟ ਧਾਰੀਯੰ। ਦਿਨੇਸ ਕ੍ਰਿਤ ਹਾਰੀਯੰ। ੧੦। ੧੮।","roman":"Siran kareet dhaareeyan | dines krit haareeyan | 10 | 18 |","meaning_en":"He wears a crown upon His head; He puts the splendour of the sun to shame.","page":253,"meaning_status":"draft","note":"ਦਿਨੇਸ ਕ੍ਰਿਤ ਹਾਰੀਯੰ: read as 'defeats the glory of the sun'; uncertain."}]},{"type":"verse","number":[11,19],"number_text":"੧੧। ੧੯।","page":253,"lines":[{"gurmukhi":"ਬਿਸਾਲ ਲਾਲ ਲੋਚਨੰ। ਮਨੋਜ ਮਾਨ ਮੋਚਨੰ।","roman":"Bisaal laal lochnan | manoj maan mochnan |","meaning_en":"His eyes are large and red; He destroys the pride of the god of love.","page":253,"meaning_status":"draft"},{"gurmukhi":"ਸੁਭੰਤ ਸੀਸ ਸੁ ਪ੍ਰਭਾ। ਚਕ੍ਰਤ ਚਾਰੁ ਚੰਦ੍ਰਕਾ। ੧੧। ੧੯।","roman":"Subhant sees su prabhaa | chakrat chaaru chandrakaa | 11 | 19 |","meaning_en":"His head shines with fine splendour; the lovely moon is amazed.","page":253,"meaning_status":"draft","note":"ਚਕ੍ਰਤ ਚਾਰੁ ਚੰਦ੍ਰਕਾ: 'the lovely moon(light) is astonished' or 'a beautiful crescent ornament'; uncertain."}]},{"type":"verse","number":[12,20],"number_text":"੧੨। ੨੦।","page":253,"lines":[{"gurmukhi":"ਜਗੰਤ ਜੋਤ ਜੁਆਲਕਾ। ਛਕੰਤ ਰਾਜ ਸੁ ਪ੍ਰਭਾ।","roman":"Jagant jot juaalkaa | chhakant raaj su prabhaa |","meaning_en":"His light shines like a flame; He is resplendent with royal glory.","page":253,"meaning_status":"draft"},{"gurmukhi":"ਜਗੰਤ ਜੋਤਿ ਜੈਤਸੀ। ਬਦੰਤ ਕ੍ਰਿਤ ਈਸੁਰੀ। ੧੨। ੨੦।","roman":"Jagant joti jaitsee | badant krit eesuree | 12 | 20 |","meaning_en":"His light shines victorious; He is praised as the Lord.","page":253,"meaning_status":"draft","note":"ਬਦੰਤ ਕ੍ਰਿਤ ਈਸੁਰੀ: perhaps 'His glory as Lord is proclaimed'; uncertain."}]},{"type":"heading","kind":"chhand","name":"ਤ੍ਰਿਭੰਗੀ ਛੰਦ","gurmukhi":"ਤ੍ਰਿਭੰਗੀ ਛੰਦ। ਤ੍ਵਪ੍ਰਸਾਦਿ","roman":"Tribhangee chhand | tvaprasaadi","meaning_en":"Tribhangi metre. By Your grace.","page":253,"invocation":"ਤ੍ਵਪ੍ਰਸਾਦਿ","meaning_status":"draft"},{"type":"verse","number":[1,21],"number_text":"੧। ੨੧।","page":253,"lines":[{"gurmukhi":"ਅਨਕਾਦ ਸਰੂਪੰ ਅਮਿਤ ਬਿਭੂਤੰ ਅਚਲ ਸਰੂਪੰ ਬਿਸੁ ਕਰਣੰ।","roman":"Ankaad saroopan amit bibhootan achal saroopan bisu karnan |","meaning_en":"Of beginningless form, of boundless glory, of unmoving form, the cause of the universe;","page":253,"meaning_status":"draft","note":"ਅਨਕਾਦ: read as 'without beginning'; uncertain."},{"gurmukhi":"ਜਗ ਜੋਤਿ ਪ੍ਰਕਾਸੰ ਆਦਿ ਅਨਾਸੰ ਅਮਿਤ ਅਗਾਸੰ ਸਰਬ ਭਰਣੰ।","roman":"Jag joti prakaasan aadi anaasan amit agaasan sarab bharnan |","meaning_en":"the light that illumines the world, the primal, the imperishable, boundless as the sky, the sustainer of all;","page":253,"meaning_status":"draft","note":"ਅਮਿਤ ਅਗਾਸੰ: 'boundless sky' or 'boundless, pervading the sky'; uncertain."},{"gurmukhi":"ਅਨਗੰਜ ਅਕਾਲੰ ਬਿਸੁ ਪ੍ਰਤਿਪਾਲੰ ਦੀਨ ਦਿਆਲੰ ਸੁਭ ਕਰਣੰ।","roman":"Anganj akaalan bisu pratipaalan deen diaalan subh karnan |","meaning_en":"unconquerable, timeless, cherisher of the universe, merciful to the humble, doer of good;","page":253,"meaning_status":"draft"},{"gurmukhi":"ਆਨੰਦ ਸਰੂਪੰ ਅਨਹਦ ਰੂਪੰ ਅਮਿਤ ਬਿਭੂਤੰ ਤਵ ਸਰਣੰ। ੧। ੨੧।","roman":"Aanand saroopan anhad roopan amit bibhootan tav sarnan | 1 | 21 |","meaning_en":"of the form of bliss, of unstruck form, of boundless glory, I am in Your refuge.","page":253,"meaning_status":"draft","note":"ਅਨਹਦ: 'unstruck/unlimited'."}]},{"type":"verse","number":[2,22],"number_text":"੨। ੨੨।","page":253,"lines":[{"gurmukhi":"ਬਿਸ੍ਵੰਭਰ ਭਰਣੰ ਜਗਤ ਪ੍ਰਕਰਣੰ ਅਧਰਣ ਧਰਣੰ ਸਿਸਟ ਕਰੰ।","roman":"Bisvanbhar bharnan jagat prakarnan adhran dharnan sisat karan |","meaning_en":"Sustainer who upholds the universe, creator of the world, support of the unsupported, maker of creation;","page":253,"meaning_status":"draft"},{"gurmukhi":"ਆਨੰਦ ਸਰੂਪੀ ਅਨਹਦ ਰੂਪੀ ਅਮਿਤ ਬਿਭੂਤੀ ਤੇਜ ਬਰੰ।","roman":"Aanand saroopee anhad roopee amit bibhootee tej baran |","meaning_en":"of the form of bliss, of unstruck form, of boundless glory, excellent in radiance;","page":253,"meaning_status":"draft"},{"gurmukhi":"ਅਨਖੰਡ ਪ੍ਰਤਾਪੰ ਸਭ ਜਗ ਥਾਪੰ ਅਲਖ ਅਤਾਪੰ ਬਿਸੁ ਕਰੰ।","roman":"Ankhand prataapan sabh jag thaapan alakh ataapan bisu karan |","meaning_en":"of unbroken majesty, founder of the whole world, unseen, free of affliction, maker of the universe;","page":253,"meaning_status":"draft"},{"gurmukhi":"ਅਦ੍ਵੈ ਅਬਿਨਾਸੀ ਤੇਜ ਪ੍ਰਕਾਸੀ ਸਰਬ ਉਦਾਸੀ ਏਕ ਹਰੰ। ੨। ੨੨।","roman":"Advai abinaasee tej prakaasee sarab udaasee ek haran | 2 | 22 |","meaning_en":"non-dual, imperishable, radiant with light, detached from all, the one Lord.","page":253,"meaning_status":"draft"}]},{"type":"verse","number":[3,23],"number_text":"੩। ੨੩।","page":253,"lines":[{"gurmukhi":"ਅਨਖੰਡ ਅਮੰਡੰ ਤੇਜ ਪ੍ਰਚੰਡੰ ਜੋਤਿ ਉਦੰਡੰ ਅਮਿਤ ਮਤੰ।","roman":"Ankhand amandan tej prachandan joti udandan amit matan |","meaning_en":"Unbroken, not fashioned, of fierce radiance, of lofty light, of boundless wisdom;","page":253,"meaning_status":"draft","note":"ਅਮੰਡੰ: 'not established/made'; uncertain."},{"gurmukhi":"ਅਨਭੈ ਅਨਗਾਧੰ ਅਲਖ ਅਬਾਧੰ ਬਿਸੁ ਪ੍ਰਸਾਧੰ ਅਮਿਤ ਗਤੰ।","roman":"Anbhai angaadhan alakh abaadhan bisu prasaadhan amit gatan |","meaning_en":"fearless, unfathomable, unseen, unobstructed, the adorner of the universe, of boundless state;","page":253,"meaning_status":"draft","note":"ਪ੍ਰਸਾਧੰ: 'adorner/accomplisher'; uncertain."},{"gurmukhi":"ਆਨੰਦ ਸਰੂਪੀ ਅਨਹਦ ਰੂਪੀ ਅਚਲ ਬਿਭੂਤੀ ਭਵ ਤਰਣੰ।","roman":"Aanand saroopee anhad roopee achal bibhootee bhav tarnan |","meaning_en":"of the form of bliss, of unstruck form, of unmoving glory, who carries across the world-ocean;","page":253,"meaning_status":"draft"},{"gurmukhi":"ਅਨਗਾਧਿ ਅਬਾਧੰ ਜਗਤ ਪ੍ਰਸਾਧੰ ਸਰਬ ਅਰਾਧੰ ਤਵ ਸਰਣੰ। ੩। ੨੩।","roman":"Angaadhi abaadhan jagat prasaadhan sarab araadhan tav sarnan | 3 | 23 |","meaning_en":"unfathomable, unobstructed, adorner of the world, worshipped by all, I am in Your refuge.","page":253,"meaning_status":"draft"}]},{"type":"verse","number":[4,24],"number_text":"੪। ੨੪।","page":253,"lines":[{"gurmukhi":"ਅਕਲੰਕ ਅਬਾਧੰ ਬਿਸੁ ਪ੍ਰਸਾਧੰ ਜਗਤ ਅਰਾਧੰ ਭਵ ਨਾਸੰ।","roman":"Aklank abaadhan bisu prasaadhan jagat araadhan bhav naasan |","meaning_en":"Stainless, unobstructed, adorner of the universe, worshipped by the world, destroyer of the cycle of birth;","page":253,"meaning_status":"draft"},{"gurmukhi":"ਬਿਸ੍ਵੰਭਰ ਭਰਣੰ ਕਿਲਵਿਖ ਹਰਣੰ ਪਤਤ ਉਧਰਣੰ ਸਭ ਸਾਥੰ।","roman":"Bisvanbhar bharnan kilvikh harnan patat udharnan sabh saathan |","meaning_en":"sustainer of the universe, remover of sins, saviour of the fallen, companion of all;","page":253,"meaning_status":"draft"},{"gurmukhi":"ਅਨਾਥਨ ਨਾਥੇ ਅਕ੍ਰਿਤ ਅਗਾਥੇ ਅਮਿਤ ਅਨਾਥੇ ਦੁਖ ਹਰਣੰ।","roman":"Anaathan naathe akrit agaathe amit anaathe dukh harnan |","meaning_en":"Master of the masterless, uncreated, beyond telling, boundless, without master, remover of sorrow;","page":253,"meaning_status":"draft","note":"ਅਗਾਥੇ: read as 'beyond telling' (a-gatha); uncertain."},{"gurmukhi":"ਅਗੰਜ ਅਬਿਨਾਸੀ ਜੋਤਿ ਪ੍ਰਕਾਸੀ ਜਗਤ ਪ੍ਰਣਾਸੀ ਤੁਯ ਸਰਣੰ। ੪। ੨੪।","roman":"Aganj abinaasee joti prakaasee jagat pranaasee tuy sarnan | 4 | 24 |","meaning_en":"unconquerable, imperishable, radiant with light, destroyer of the world, I am in Your refuge.","page":253,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਕਲਸ","gurmukhi":"ਕਲਸ","roman":"Kalas","meaning_en":"Kalas.","page":254,"meaning_status":"draft","note":"Name of a metre."},{"type":"verse","number":[5,25],"number_text":"੫। ੨੫।","page":254,"lines":[{"gurmukhi":"ਅਮਿਤ ਤੇਜ ਜਗ ਜੋਤਿ ਪ੍ਰਕਾਸੀ। ਆਦਿ ਅਛੇਦ ਅਭੈ ਅਬਿਨਾਸੀ।","roman":"Amit tej jag joti prakaasee | aadi achhed abhai abinaasee |","meaning_en":"Of boundless radiance, illuminer of the world's light; primal, indestructible, fearless, imperishable;","page":254,"meaning_status":"draft"},{"gurmukhi":"ਪਰਮ ਤਤ ਪਰਮਾਰਥ ਪ੍ਰਕਾਸੀ। ਆਦਿ ਸਰੂਪ ਅਖੰਡ ਉਦਾਸੀ। ੫। ੨੫।","roman":"Param tat parmaarath prakaasee | aadi saroop akhand udaasee | 5 | 25 |","meaning_en":"revealer of the supreme essence and the supreme purpose; of primal form, unbroken, detached.","page":254,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਤ੍ਰਿਭੰਗੀ ਛੰਦ","gurmukhi":"ਤ੍ਰਿਭੰਗੀ ਛੰਦ","roman":"Tribhangee chhand","meaning_en":"Tribhangi metre.","page":254,"meaning_status":"draft"},{"type":"verse","number":[6,26],"number_text":"੬। ੨੬।","page":254,"lines":[{"gurmukhi":"ਅਖੰਡ ਉਦਾਸੀ ਪਰਮ ਪ੍ਰਕਾਸੀ ਆਦਿ ਅਨਾਸੀ ਬਿਸ੍ਵ ਕਰੰ।","roman":"Akhand udaasee param prakaasee aadi anaasee bisv karan |","meaning_en":"Unbroken, detached, supremely radiant, primal, imperishable, maker of the universe;","page":254,"meaning_status":"draft"},{"gurmukhi":"ਜਗਤਾਵਲ ਕਰਤਾ ਜਗਤ ਪ੍ਰਹਰਤਾ ਸਭ ਜਗ ਭਰਤਾ ਸਿਧ ਭਰੰ।","roman":"Jagtaaval kartaa jagat prahartaa sabh jag bhartaa sidh bharan |","meaning_en":"creator of the world's array, destroyer of the world, sustainer of the whole world, giver of fulfilment;","page":254,"meaning_status":"draft","note":"ਸਿਧ ਭਰੰ: 'filled with/giver of spiritual powers'; uncertain."},{"gurmukhi":"ਅਛੈ ਅਬਿਨਾਸੀ ਤੇਜ ਪ੍ਰਕਾਸੀ ਰੂਪ ਸੁ ਰਾਸੀ ਸਰਬ ਛਿਤੰ।","roman":"Achhai abinaasee tej prakaasee roop su raasee sarab chhitan |","meaning_en":"indestructible, imperishable, radiant with light, a treasury of beauty, (pervading) all the earth;","page":254,"meaning_status":"draft"},{"gurmukhi":"ਆਨੰਦ ਸਰੂਪੀ ਅਨਹਦ ਰੂਪੀ ਅਲਖ ਬਿਭੂਤੀ ਅਮਿਤ ਗਤੰ। ੬। ੨੬।","roman":"Aanand saroopee anhad roopee alakh bibhootee amit gatan | 6 | 26 |","meaning_en":"of the form of bliss, of unstruck form, of unseen glory, of boundless state.","page":254,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਕਲਸ","gurmukhi":"ਕਲਸ","roman":"Kalas","meaning_en":"Kalas.","page":254,"meaning_status":"draft"},{"type":"verse","number":[7,27],"number_text":"੭। ੨੭।","page":254,"lines":[{"gurmukhi":"ਆਦਿ ਅਭੈ ਅਨਗਾਧਿ ਸਰੂਪੰ। ਰਾਗ ਰੰਗਿ ਜਿਹ ਰੇਖ ਨ ਰੂਪੰ।","roman":"Aadi abhai angaadhi saroopan | raag rangi jih rekh na roopan |","meaning_en":"Primal, fearless, of unfathomable form; who has no attachment, colour, mark or form;","page":254,"meaning_status":"draft"},{"gurmukhi":"ਰੰਕ ਭਯੋ ਰਾਵਤ ਕਹੂੰ ਭੂਪੰ। ਕਹੂੰ ਸਮੁੰਦ੍ਰ ਸਰਤਾ ਕਹੂੰ ਕੂਪੰ। ੭। ੨੭।","roman":"Rank bhayo raavat kahoon bhoopan | kahoon samundr sartaa kahoon koopan | 7 | 27 |","meaning_en":"somewhere He has become a pauper, somewhere a chief or king; somewhere the ocean, a river, somewhere a well.","page":254,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਤ੍ਰਿਭੰਗੀ ਛੰਦ","gurmukhi":"ਤ੍ਰਿਭੰਗੀ ਛੰਦ","roman":"Tribhangee chhand","meaning_en":"Tribhangi metre.","page":254,"meaning_status":"draft"},{"type":"verse","number":[8,28],"number_text":"੮। ੨੮।","page":254,"lines":[{"gurmukhi":"ਸਰਤਾ ਕਹੂੰ ਕੂਪੰ ਸਮੁਦ ਸਰੂਪੰ ਅਲਖ ਬਿਭੂਤੰ ਅਮਿਤ ਗਤੰ।","roman":"Sartaa kahoon koopan samud saroopan alakh bibhootan amit gatan |","meaning_en":"Somewhere a river, somewhere a well, in the form of the ocean; of unseen glory, of boundless state;","page":254,"meaning_status":"draft"},{"gurmukhi":"ਅਦ੍ਵੈ ਅਬਿਨਾਸੀ ਪਰਮ ਪ੍ਰਕਾਸੀ ਤੇਜ ਸੁਰਾਸੀ ਅਕ੍ਰਿਤ ਕ੍ਰਿਤੰ।","roman":"Advai abinaasee param prakaasee tej suraasee akrit kritan |","meaning_en":"non-dual, imperishable, supremely radiant, a treasury of light, the uncreated Maker;","page":254,"meaning_status":"draft","note":"ਅਕ੍ਰਿਤ ਕ੍ਰਿਤੰ: 'the uncreated who creates' or 'doer of the not-done'; uncertain."},{"gurmukhi":"ਜਿਹ ਰੂਪ ਨ ਰੇਖੰ ਅਲਖ ਅਭੇਖੰ ਅਮਿਤ ਅਦ੍ਵੈਖੰ ਸਰਬ ਮਈ।","roman":"Jih roop na rekhan alakh abhekhan amit advaikhan sarab maee |","meaning_en":"who has no form or mark, unseen, without guise, boundless, without malice, pervading all;","page":254,"meaning_status":"draft","note":"ਅਦ੍ਵੈਖੰ: read as 'without enmity' (a-dvesh); uncertain."},{"gurmukhi":"ਸਭ ਕਿਲਵਿਖ ਹਰਣੰ ਪਤਿਤ ਉਧਰਣੰ ਅਸਰਣਿ ਸਰਣੰ ਏਕ ਦਈ। ੮। ੨੮।","roman":"Sabh kilvikh harnan patit udharnan asarni sarnan ek daee | 8 | 28 |","meaning_en":"remover of all sins, saviour of the fallen, refuge of the refugeless, the one Giver.","page":254,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਕਲਸ","gurmukhi":"ਕਲਸ","roman":"Kalas","meaning_en":"Kalas.","page":254,"meaning_status":"draft"},{"type":"verse","number":[9,29],"number_text":"੯। ੨੯।","page":254,"lines":[{"gurmukhi":"ਆਜਾਨੁ ਬਾਹੁ ਸਾਰੰਗ ਕਰ ਧਰਣੰ। ਅਮਿਤ ਜੋਤਿ ਜਗ ਜੋਤ ਪ੍ਰਕਰਣੰ।","roman":"Aajaanu baahu saarang kar dharnan | amit joti jag jot prakarnan |","meaning_en":"His arms reach to His knees, He holds the bow in His hand; His boundless light gives light to the world;","page":254,"meaning_status":"draft","note":"ਸਾਰੰਗ: the bow (Sarang)."},{"gurmukhi":"ਖੜਗ ਪਾਣ ਖਲ ਦਲ ਬਲ ਹਰਣੰ। ਮਹਾਬਾਹੁ ਬਿਸ੍ਵੰਭਰ ਭਰਣੰ। ੯। ੨੯।","roman":"Kharag paan khal dal bal harnan | mahaabaahu bisvanbhar bharnan | 9 | 29 |","meaning_en":"sword in hand, He destroys the strength of the hosts of the wicked; mighty-armed, He sustains the universe.","page":254,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਤ੍ਰਿਭੰਗੀ ਛੰਦ","gurmukhi":"ਤ੍ਰਿਭੰਗੀ ਛੰਦ","roman":"Tribhangee chhand","meaning_en":"Tribhangi metre.","page":254,"meaning_status":"draft"},{"type":"verse","number":[10,30],"number_text":"੧੦। ੩੦।","page":254,"lines":[{"gurmukhi":"ਖਲ ਦਲ ਬਲ ਹਰਣੰ ਦੁਸਟ ਬਿਦਰਣੰ ਅਸਰਣ ਸਰਣੰ ਅਮਿਤ ਗਤੰ।","roman":"Khal dal bal harnan dusat bidarnan asran sarnan amit gatan |","meaning_en":"Destroyer of the strength of the wicked hosts, tearer-down of evildoers, refuge of the refugeless, of boundless state;","page":254,"meaning_status":"draft"},{"gurmukhi":"ਚੰਚਲ ਚਖ ਚਾਰਣ ਮਛ ਬਿਡਾਰਣ ਪਾਪ ਪ੍ਰਹਾਰਣ ਅਮਿਤ ਮਤੰ।","roman":"Chanchal chakh chaaran machh bidaaran paap prahaaran amit matan |","meaning_en":"with restless, lovely eyes, slayer of (the demon) Machh, striker-down of sin, of boundless wisdom;","page":254,"meaning_status":"draft","note":"ਚੰਚਲ ਚਖ ਚਾਰਣ: read as 'beautiful restless eyes'; ਮਛ ਬਿਡਾਰਣ: perhaps 'who took the Fish form and slew (the demon)'; uncertain."},{"gurmukhi":"ਆਜਾਨ ਸੁ ਬਾਹੰ ਸਾਹਨ ਸਾਹੰ ਮਹਿਮਾ ਮਾਹੰ ਸਰਬ ਮਈ।","roman":"Aajaan su baahan saahan saahan mahimaa maahan sarab maee |","meaning_en":"His fine arms reach to His knees, King of kings, His glory great, pervading all;","page":255,"meaning_status":"draft"},{"gurmukhi":"ਜਲ ਥਲ ਬਨ ਰਹਿਤਾ ਬਨ ਤ੍ਰਿਨਿ ਕਹਿਤਾ ਖਲ ਦਲਿ ਦਹਿਤਾ ਸੁ ਨਰਿ ਸਹੀ। ੧੦। ੩੦।","roman":"Jal thal ban rahitaa ban trini kahitaa khal dali dahitaa su nari sahee | 10 | 30 |","meaning_en":"He dwells in water, land and forest; the forests and grasses speak of Him; He burns the hosts of the wicked, the true Being.","page":255,"meaning_status":"draft","note":"ਸੁ ਨਰਿ ਸਹੀ: read as 'truly the (supreme) Person'; ਰਹਿਤਾ may mean 'dwelling in' or 'apart from'; uncertain."}]},{"type":"heading","kind":"chhand","name":"ਕਲਸ","gurmukhi":"ਕਲਸ","roman":"Kalas","meaning_en":"Kalas.","page":255,"meaning_status":"draft"},{"type":"verse","number":[11,31],"number_text":"੧੧। ੩੧।","page":255,"lines":[{"gurmukhi":"ਅਤਿ ਬਲਿਸਟ ਦਲ ਦੁਸਟ ਨਿਕੰਦਨ। ਅਮਿਤ ਪ੍ਰਤਾਪ ਸਗਲ ਜਗ ਬੰਦਨ।","roman":"Ati balisat dal dusat nikandan | amit prataap sagal jag bandan |","meaning_en":"Exceedingly mighty, destroyer of the hosts of the wicked; of boundless majesty, bowed to by the whole world;","page":255,"meaning_status":"draft"},{"gurmukhi":"ਸੋਹਤ ਚਾਰੁ ਚਿਤ੍ਰ ਕਰ ਚੰਦਨ। ਪਾਪ ਪ੍ਰਹਾਰਣ ਦੁਸਟ ਦਲ ਦੰਡਨ। ੧੧। ੩੧।","roman":"Sohat chaaru chitr kar chandan | paap prahaaran dusat dal dandan | 11 | 31 |","meaning_en":"beautiful, adorned with sandal marks on His hands; striker-down of sin, punisher of the wicked hosts.","page":255,"meaning_status":"draft","note":"ਚਾਰੁ ਚਿਤ੍ਰ ਕਰ ਚੰਦਨ: perhaps 'lovely sandal designs on His hands/body'; uncertain."}]},{"type":"heading","kind":"chhand","name":"ਛਪੈ ਛੰਦ","gurmukhi":"ਛਪੈ ਛੰਦ","roman":"Chhapai chhand","meaning_en":"Chhappai metre.","page":255,"meaning_status":"draft"},{"type":"verse","number":[1,32],"number_text":"੧। ੩੨।","page":255,"lines":[{"gurmukhi":"ਬੇਦ ਭੇਦ ਨਹੀ ਲਖੈ ਬ੍ਰਹਮ ਬ੍ਰਹਮਾ ਨਹੀ ਬੁਝੈ।","roman":"Bed bhed nahee lakhai braham brahmaa nahee bujhai |","meaning_en":"The Vedas do not grasp His mystery, nor does Brahma understand the Supreme;","page":255,"meaning_status":"draft"},{"gurmukhi":"ਬਿਆਸ ਪਰਾਸੁਰ ਸੁਕ ਸਨਾਦਿ ਸਿਵ ਅੰਤੁ ਨ ਸੁਝੈ।","roman":"Biaas paraasur suk sanaadi siv antu na sujhai |","meaning_en":"Vyas, Parashar, Shuk, Sanak and others, and Shiva, cannot see His end;","page":255,"meaning_status":"draft"},{"gurmukhi":"ਸਨਤਿ ਕੁਆਰ ਸਨਕਾਦਿ ਸਰਬ ਜਉ ਸਮਾ ਨ ਪਾਵਹਿ।","roman":"Santi kuaar sankaadi sarab jau samaa na paavhi |","meaning_en":"Sanat Kumar, Sanak and all the others cannot find His measure;","page":255,"meaning_status":"draft","note":"ਜਉ ਸਮਾ ਨ ਪਾਵਹਿ: read as 'do not find His extent'; uncertain."},{"gurmukhi":"ਲਖ ਲਖਮੀ ਲਖ ਬਿਸਨ ਕਿਸਨ ਕਈ ਨੇਤ ਬਤਾਵਹਿ।","roman":"Lakh lakhmee lakh bisan kisan kaee net bataavhi |","meaning_en":"countless Lakshmis, countless Vishnus and Krishnas call Him 'Not this, not this'.","page":255,"meaning_status":"draft","note":"ਨੇਤ: neti, 'not thus'."},{"gurmukhi":"ਅਸੰਭ ਰੂਪ ਅਨਭੈ ਪ੍ਰਭਾ ਅਤਿ ਬਲਿਸਟ ਜਲਿ ਥਲਿ ਕਰਣ।","roman":"Asanbh roop anbhai prabhaa ati balisat jali thali karan |","meaning_en":"Of unborn form, fearless splendour, exceedingly mighty, maker of water and land,","page":255,"meaning_status":"draft"},{"gurmukhi":"ਅਚੁਤ ਅਨੰਤ ਅਦ੍ਵੈ ਅਮਿਤ ਨਾਥ ਨਿਰੰਜਨ ਤਵ ਸਰਣ। ੧। ੩੨।","roman":"Achut anant advai amit naath niranjan tav saran | 1 | 32 |","meaning_en":"imperishable, endless, non-dual, boundless, stainless Lord, I am in Your refuge.","page":255,"meaning_status":"draft"}]},{"type":"verse","number":[2,33],"number_text":"੨। ੩੩।","page":255,"lines":[{"gurmukhi":"ਅਚੁਤ ਅਭੈ ਅਭੇਦ ਅਮਿਤ ਆਖੰਡ ਅਤੁਲ ਬਲ।","roman":"Achut abhai abhed amit aakhand atul bal |","meaning_en":"Imperishable, fearless, beyond mystery, boundless, unbroken, of matchless strength;","page":255,"meaning_status":"draft"},{"gurmukhi":"ਅਟਲ ਅਨੰਤ ਅਨਾਦਿ ਅਖੈ ਅਖੰਡ ਪ੍ਰਬਲ ਦਲ।","roman":"Atal anant anaadi akhai akhand prabal dal |","meaning_en":"immovable, endless, beginningless, undecaying, unbroken, with mighty hosts;","page":255,"meaning_status":"draft"},{"gurmukhi":"ਅਮਿਤ ਅਮਿਤ ਅਨਤੋਲ ਅਭੂ ਅਨਭੇਦ ਅਭੰਜਨ।","roman":"Amit amit antol abhoo anbhed abhanjan |","meaning_en":"boundless, boundless, beyond weighing, unborn, beyond mystery, unbreakable;","page":255,"meaning_status":"draft"},{"gurmukhi":"ਅਨਬਿਕਾਰ ਆਤਮ ਸਰੂਪ ਸੁਰ ਨਰ ਮੁਨ ਰੰਜਨ।","roman":"Anbikaar aatam saroop sur nar mun ranjan |","meaning_en":"without defect, the form of the Self, delighter of gods, men and sages;","page":255,"meaning_status":"draft"},{"gurmukhi":"ਅਬਿਕਾਰ ਰੂਪ ਅਨਭੈ ਸਦਾ ਮੁਨ ਜਨ ਗਨ ਬੰਦਤ ਚਰਨ।","roman":"Abikaar roop anbhai sadaa mun jan gan bandat charan |","meaning_en":"of flawless form, ever fearless, whose feet the hosts of sages worship;","page":255,"meaning_status":"draft"},{"gurmukhi":"ਭਵ ਭਰਨ ਕਰਨ ਦੁਖ ਦੋਖ ਹਰਨ ਅਤਿ ਪ੍ਰਤਾਪ ਭ੍ਰਮ ਭੈ ਹਰਨ। ੨। ੩੩।","roman":"Bhav bharan karan dukh dokh haran ati prataap bhram bhai haran | 2 | 33 |","meaning_en":"sustainer and maker of the world, remover of pain and fault, of great majesty, remover of doubt and fear.","page":255,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਛਪੈ ਛੰਦ","gurmukhi":"ਛਪੈ ਛੰਦ। ਤ੍ਵਪ੍ਰਸਾਦਿ","roman":"Chhapai chhand | tvaprasaadi","meaning_en":"Chhappai metre. By Your grace.","page":255,"invocation":"ਤ੍ਵਪ੍ਰਸਾਦਿ","meaning_status":"draft"},{"type":"verse","number":[3,34],"number_text":"੩। ੩੪।","page":255,"lines":[{"gurmukhi":"ਮੁਖ ਮੰਡਲ ਪਰ ਲਸਤ ਜੋਤਿ ਉਦੋਤ ਅਮਿਤ ਗਤਿ।","roman":"Mukh mandal par lasat joti udot amit gati |","meaning_en":"On His face shines a light, radiant, of boundless state;","page":255,"meaning_status":"draft"},{"gurmukhi":"ਜਟਤ ਜੋਤ ਜਗਮਗਤ ਲਜਤ ਲਖ ਕੋਟਿ ਨਿਖਤਿ ਪਤਿ।","roman":"Jatat jot jagamgat lajat lakh koti nikhti pati |","meaning_en":"His light gleams so that countless millions of moons are put to shame;","page":255,"meaning_status":"draft","note":"ਨਿਖਤਿ ਪਤਿ: 'lord of stars', the moon."},{"gurmukhi":"ਚਕ੍ਰਵਰਤੀ ਚਕ੍ਰਵੈ ਚਕ੍ਰਤ ਚਉਚਕ੍ਰ ਕਰਿ ਧਰਿ।","roman":"Chakravartee chakravai chakrat chauchakr kari dhari |","meaning_en":"emperor, ruler of the circle (of the earth), holding the four quarters in His hand;","page":255,"meaning_status":"draft","note":"ਚਕ੍ਰਵੈ ਚਕ੍ਰਤ ਚਉਚਕ੍ਰ ਕਰਿ ਧਰਿ: uncertain; perhaps 'who holds the four directions under His sway'."},{"gurmukhi":"ਪਦਮ ਨਾਥ ਪਦਮਾਛ ਨਵਲ ਨਾਰਾਇਣ ਨਰਿਹਰਿ।","roman":"Padam naath padmaachh naval naaraain narihri |","meaning_en":"Lord of Lakshmi, lotus-eyed, ever new, Narayan, Narhari.","page":255,"meaning_status":"draft","note":"ਪਦਮ ਨਾਥ: 'lord of Padma (Lakshmi)' or 'lord of the lotus'."},{"gurmukhi":"ਕਾਲਖ ਬਿਹੰਡਣ ਕਿਲਵਿਖ ਹਰਣ ਸੁਰ ਨਰ ਮੁਨ ਬੰਦਤ ਚਰਣ।","roman":"Kaalakh bihandan kilvikh haran sur nar mun bandat charan |","meaning_en":"destroyer of blackness, remover of sins, whose feet gods, men and sages worship;","page":255,"meaning_status":"draft","note":"ਕਾਲਖ: 'blackness, stain (of sin)'."},{"gurmukhi":"ਖੰਡਣ ਅਖੰਡ ਮੰਡਣ ਅਭੈ ਨਮੋ ਨਾਥ ਭਉ ਭੈ ਹਰਣ। ੩। ੩੪।","roman":"Khandan akhand mandan abhai namo naath bhau bhai haran | 3 | 34 |","meaning_en":"breaker (of all), Himself unbroken, adorner, fearless; salutation, O Lord, remover of dread and fear.","page":255,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਛਪੈ ਛੰਦ","gurmukhi":"ਛਪੈ ਛੰਦ","roman":"Chhapai chhand","meaning_en":"Chhappai metre.","page":256,"meaning_status":"draft"},{"type":"verse","number":[4,35],"number_text":"੪। ੩੫।","page":256,"lines":[{"gurmukhi":"ਨਮੋ ਨਾਥ ਨ੍ਰਿਦਾਇਕ ਨਮੋ ਨਿਮ ਰੂਪ ਨਿਰੰਜਨ।","roman":"Namo naath nridaaik namo nim roop niranjan |","meaning_en":"Salutation to the Lord, giver to men; salutation to the humble-formed, stainless One;","page":256,"meaning_status":"draft","note":"ਨ੍ਰਿਦਾਇਕ: read as 'giver to men' or 'without dependence'; ਨਿਮ ਰੂਪ: 'humble form' or 'of no form'; both uncertain."},{"gurmukhi":"ਅਗੰਜਾਣ ਅਗੰਜਣ ਅਭੰਜ ਅਨਭੇਦ ਅਭੰਜਨ।","roman":"Aganjaan aganjan abhanj anbhed abhanjan |","meaning_en":"unconquerable, conqueror of the unconquerable, unbreakable, beyond mystery, unbreakable;","page":256,"meaning_status":"draft","note":"ਅਗੰਜਾਣ ਅਗੰਜਣ: read as 'unconquered, conqueror'; uncertain."},{"gurmukhi":"ਅਛੈ ਅਖੈ ਅਬਿਕਾਰ ਅਭੈ ਅਨਭਿਜ ਅਭੇਦਨ।","roman":"Achhai akhai abikaar abhai anbhij abhedan |","meaning_en":"indestructible, undecaying, without defect, fearless, unwetted, impenetrable;","page":256,"meaning_status":"draft","note":"ਅਨਭਿਜ: 'not wetted/untouched (by anything)'."},{"gurmukhi":"ਅਖੈਦਾਨ ਖੇਦਨ ਅਖਿਜ ਅਨਛਿਦ੍ਰ ਅਛੇਦਨ।","roman":"Akhaidaan khedan akhij anchhidr achhedan |","meaning_en":"giver of the imperishable gift, remover of sorrow, untiring, without flaw, uncuttable;","page":256,"meaning_status":"draft","note":"ਅਖੈਦਾਨ ਖੇਦਨ: perhaps 'giver of undying gifts, remover of grief'; uncertain."},{"gurmukhi":"ਆਜਾਨ ਬਾਹੁ ਸਾਰੰਗਧਰ ਖੜਗ ਪਾਣ ਦੁਰਜਨ ਦਲਣ।","roman":"Aajaan baahu saarangdhar kharag paan durjan dalan |","meaning_en":"with arms reaching to the knees, bearer of the bow, sword in hand, crusher of the wicked;","page":256,"meaning_status":"draft"},{"gurmukhi":"ਨਰ ਵਰ ਨਰੇਸ ਨਾਇਕ ਨ੍ਰਿਪਣਿ ਨਮੋ ਨਵਲ ਜਲ ਥਲ ਰਵਣਿ। ੪। ੩੫।","roman":"Nar var nares naaik nripni namo naval jal thal ravni | 4 | 35 |","meaning_en":"best of men, lord of men, leader of kings; salutation to the ever-new One who pervades water and land.","page":256,"meaning_status":"draft"}]},{"type":"verse","number":[5,36],"number_text":"੫। ੩੬।","page":256,"lines":[{"gurmukhi":"ਦੀਨ ਦਯਾਲ ਦੁਖ ਹਰਣ ਦੁਰਮਤ ਹੰਤਾ ਦੁਖ ਖੰਡਣ।","roman":"Deen dayaal dukh haran durmat hantaa dukh khandan |","meaning_en":"Merciful to the humble, remover of pain, slayer of evil-mindedness, breaker of sorrow;","page":256,"meaning_status":"draft"},{"gurmukhi":"ਮਹਾ ਮੋਨ ਮਨ ਹਰਨ ਮਦਨ ਮੂਰਤ ਮਹਿ ਮੰਡਨ।","roman":"Mahaa mon man haran madan moorat mahi mandan |","meaning_en":"great silent One, enticer of minds, image of beauty like the god of love, adorner of the earth;","page":256,"meaning_status":"draft","note":"ਮਹਿ ਮੰਡਨ: 'adorner of the earth'; uncertain."},{"gurmukhi":"ਅਮਿਤ ਤੇਜ ਅਬਿਕਾਰ ਅਖੈ ਆਭੰਜ ਅਮਿਤ ਬਲ।","roman":"Amit tej abikaar akhai aabhanj amit bal |","meaning_en":"of boundless radiance, without defect, undecaying, unbreakable, of boundless strength;","page":256,"meaning_status":"draft"},{"gurmukhi":"ਨਿਰਭੰਜ ਨਿਰਭਉ ਨਿਰਵੈਰ ਨਿਰਜੁਰ ਨ੍ਰਿਪ ਜਲ ਥਲ।","roman":"Nirbhanj nirbhau nirvair nirjur nrip jal thal |","meaning_en":"unbreakable, fearless, without enmity, free of age, King of water and land;","page":256,"meaning_status":"draft","note":"ਨਿਰਜੁਰ: 'free of age/fever'."},{"gurmukhi":"ਅਛੈ ਸਰੂਪ ਅਛੂ ਅਛਿਤ ਅਛੈ ਅਛਾਨ ਅਛਰ।","roman":"Achhai saroop achhoo achhit achhai achhaan achhar |","meaning_en":"of indestructible form, untouched, imperishable, indestructible, unhidden, imperishable;","page":256,"meaning_status":"draft","note":"ਅਛੂ, ਅਛਿਤ, ਅਛਾਨ, ਅਛਰ: a series of near-synonyms ('untouched', 'undiminished', 'unhidden/unconcealed', 'imperishable'); exact senses uncertain."},{"gurmukhi":"ਅਦ੍ਵੈ ਸਰੂਪ ਅਦ੍ਵਿਯ ਅਮਰ ਅਭਿਬੰਦਤ ਸੁਰ ਨਰ ਅਸੁਰ। ੫। ੩੬।","roman":"Advai saroop adviy amar abhibandat sur nar asur | 5 | 36 |","meaning_en":"of non-dual form, without a second, immortal, worshipped by gods, men and demons.","page":256,"meaning_status":"draft"}]},{"type":"verse","number":[6,37],"number_text":"੬। ੩੭।","page":256,"lines":[{"gurmukhi":"ਕੁਲ ਕਲੰਕ ਕਰਿ ਹੀਨ ਕ੍ਰਿਪਾ ਸਾਗਰ ਕਰੁਣਾ ਕਰ।","roman":"Kul kalank kari heen kripaa saagar karunaa kar |","meaning_en":"Free of the stain of lineage, ocean of grace, merciful;","page":256,"meaning_status":"draft"},{"gurmukhi":"ਕਰਣ ਕਾਰਣ ਸਮਰਥ ਕ੍ਰਿਪਾ ਕੀ ਸੂਰਤ ਕ੍ਰਿਤ ਧਰ।","roman":"Karan kaaran samrath kripaa kee soorat krit dhar |","meaning_en":"powerful cause of causes, the image of grace, upholder of creation;","page":256,"meaning_status":"draft"},{"gurmukhi":"ਕਾਲ ਕਰਮ ਕਰ ਹੀਨ ਕ੍ਰਿਆ ਜਿਹ ਕੋਇ ਨ ਬੁਝੈ।","roman":"Kaal karam kar heen kriaa jih koi na bujhai |","meaning_en":"beyond death and karma, whose workings no one understands;","page":256,"meaning_status":"draft"},{"gurmukhi":"ਕਹਾ ਕਹੈ ਕਹਿ ਕਰੈ ਕਹਾ ਕਾਲਨ ਕੈ ਸੁਝੈ।","roman":"Kahaa kahai kahi karai kahaa kaalan kai sujhai |","meaning_en":"what does He say, what does He do? How can it occur to the beings of time?","page":256,"meaning_status":"draft","note":"ਕਾਲਨ ਕੈ ਸੁਝੈ: read as 'how could mortals perceive it'; uncertain."},{"gurmukhi":"ਕੰਜਲਕ ਨੈਨ ਕੰਬੂ ਗ੍ਰੀਵਹਿ ਕਟਿ ਕੇਹਰ ਕੁੰਜਰ ਗਵਨ।","roman":"Kanjlak nain kanboo greevhi kati kehar kunjar gavan |","meaning_en":"Lotus-eyed, with a neck like a conch, a waist like a lion's, a gait like an elephant's;","page":256,"meaning_status":"draft"},{"gurmukhi":"ਕਦਲੀ ਕੁਰੰਕ ਕਰਪੂਰ ਗਤ ਬਿਨ ਅਕਾਲ ਦੁਜੋ ਕਵਨ। ੬। ੩੭।","roman":"Kadlee kurank karpoor gat bin akaal dujo kavan | 6 | 37 |","meaning_en":"like the plantain, the deer and camphor in grace; besides the Timeless, who else is there?","page":256,"meaning_status":"draft","note":"ਕਦਲੀ ਕੁਰੰਕ ਕਰਪੂਰ ਗਤ: uncertain; perhaps 'with thighs like plantain, eyes of the deer, fragrance of camphor'."}]},{"type":"verse","number":[7,38],"number_text":"੭। ੩੮।","page":256,"lines":[{"gurmukhi":"ਅਲਖ ਰੂਪ ਅਲੇਖ ਅਬੈ ਅਨਭੂਤ ਅਭੰਜਨ।","roman":"Alakh roop alekh abai anbhoot abhanjan |","meaning_en":"Of unseen form, beyond writing, imperishable, not of the elements, unbreakable;","page":256,"meaning_status":"draft","note":"ਅਬੈ: read as 'ageless/imperishable'; uncertain."},{"gurmukhi":"ਆਦਿ ਪੁਰਖ ਅਬਿਕਾਰ ਅਜੈ ਅਨਗਾਧ ਅਗੰਜਨ।","roman":"Aadi purakh abikaar ajai angaadh aganjan |","meaning_en":"primal Being, without defect, unconquered, unfathomable, unconquerable;","page":256,"meaning_status":"draft"},{"gurmukhi":"ਨਿਰਬਿਕਾਰ ਨਿਰਜੁਰ ਸਰੂਪ ਨਿਰ ਦ੍ਵੈਖ ਨਿਰੰਜਨ।","roman":"Nirbikaar nirjur saroop nir dvaikh niranjan |","meaning_en":"without defect, of ageless form, without malice, stainless;","page":256,"meaning_status":"draft"},{"gurmukhi":"ਅਭੰਜਾਨ ਭੰਜਨ ਅਨਭੇਦ ਅਨਭੂਤ ਅਭੰਜਨ।","roman":"Abhanjaan bhanjan anbhed anbhoot abhanjan |","meaning_en":"unbreakable, breaker (of all), beyond mystery, not of the elements, unbreakable;","page":256,"meaning_status":"draft"},{"gurmukhi":"ਸਾਹਾਨ ਸਾਹ ਸੁੰਦਰ ਸੁਮਤ ਬਡ ਸਰੂਪ ਬਡਵੈ ਬਖਤ।","roman":"Saahaan saah sundar sumat bad saroop badvai bakhat |","meaning_en":"King of kings, beautiful, wise, of great form, of great fortune;","page":256,"meaning_status":"draft","note":"ਬਖਤ: Persian bakht, 'fortune'."},{"gurmukhi":"ਕੋਟਕਿ ਪ੍ਰਤਾਪ ਭੂਅ ਭਾਨ ਜਿਮ ਤਪਤ ਤੇਜ ਇਸਥਿਤ ਤਖਤ। ੭। ੩੮।","roman":"Kotki prataap bhooa bhaan jim tapat tej isthit takhat | 7 | 38 |","meaning_en":"His majesty is as of millions of suns on the earth; His radiance blazes as He sits firm on the throne.","page":256,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਛਪੈ ਛੰਦ","gurmukhi":"ਛਪੈ ਛੰਦ। ਤ੍ਵਪ੍ਰਸਾਦਿ","roman":"Chhapai chhand | tvaprasaadi","meaning_en":"Chhappai metre. By Your grace.","page":257,"invocation":"ਤ੍ਵਪ੍ਰਸਾਦਿ","meaning_status":"draft"},{"type":"verse","number":[8,39],"number_text":"੮। ੩੯।","page":257,"lines":[{"gurmukhi":"ਚਕ੍ਰਤ ਚਾਰ ਚਕ੍ਰਵੈ ਚਕ੍ਰਤ ਚਉਕੁੰਟ ਚਵਗਨ।","roman":"Chakrat chaar chakravai chakrat chaukunt chavgan |","meaning_en":"The four quarters are amazed; the four corners of the circle of the world are amazed;","page":257,"meaning_status":"draft","note":"Line obscure; read as 'all directions are astonished at Him'; uncertain."},{"gurmukhi":"ਕੋਟ ਸੂਰ ਸਮ ਤੇਜ ਤੇਜ ਨਹੀ ਦੂਨ ਚਵਗਨ।","roman":"Kot soor sam tej tej nahee doon chavgan |","meaning_en":"His radiance equals millions of suns, nay, is twice and four times greater;","page":257,"meaning_status":"draft","note":"ਤੇਜ ਨਹੀ ਦੂਨ ਚਵਗਨ: may also read 'not even twice or four times (could match)'; uncertain."},{"gurmukhi":"ਕੋਟ ਚੰਦ ਚਕ ਪਰੈ ਤੁਲ ਨਹੀ ਤੇਜ ਬਿਚਾਰਤ।","roman":"Kot chand chak parai tul nahee tej bichaarat |","meaning_en":"millions of moons are astonished; considering His radiance, none is equal to it;","page":257,"meaning_status":"draft"},{"gurmukhi":"ਬਿਆਸ ਪਰਾਸਰ ਬ੍ਰਹਮ ਭੇਦ ਨਹਿ ਬੇਦ ਉਚਾਰਤ।","roman":"Biaas paraasar braham bhed nahi bed uchaarat |","meaning_en":"Vyas, Parashar and Brahma cannot tell His mystery, nor do the Vedas declare it.","page":257,"meaning_status":"draft"},{"gurmukhi":"ਸਾਹਾਨ ਸਾਹ ਸਾਹਿਬ ਸੁਘਰਿ ਅਤਿ ਪ੍ਰਤਾਪ ਸੁੰਦਰ ਸਬਲ।","roman":"Saahaan saah saahib sughri ati prataap sundar sabal |","meaning_en":"King of kings, the Master, wise, of great majesty, beautiful and mighty;","page":257,"meaning_status":"draft"},{"gurmukhi":"ਰਾਜਾਨ ਰਾਜ ਸਾਹਿਬ ਸਬਲ ਅਮਿਤ ਤੇਜ ਅਛੈ ਅਛਲ। ੮। ੩੯।","roman":"Raajaan raaj saahib sabal amit tej achhai achhal | 8 | 39 |","meaning_en":"King of kings, the mighty Master, of boundless radiance, indestructible, undeceivable.","page":257,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਕਬਿਤੁ","gurmukhi":"ਕਬਿਤੁ। ਤ੍ਵਪ੍ਰਸਾਦਿ","roman":"Kabitu | tvaprasaadi","meaning_en":"Kabitt. By Your grace.","page":257,"invocation":"ਤ੍ਵਪ੍ਰਸਾਦਿ","meaning_status":"draft"},{"type":"verse","number":[1,40],"number_text":"੧। ੪੦।","page":257,"lines":[{"gurmukhi":"ਗਹਿਓ ਜੋਨ ਜਾਇ ਸੋ ਅਗਾਹ ਕੈ ਕੈ ਗਾਈਅਤੁ","roman":"Gahio jon jaai so agaah kai kai gaaeeatu","meaning_en":"He who cannot be grasped is sung of as the Ungraspable;","page":257,"meaning_status":"draft"},{"gurmukhi":"ਛੇਦਿਓ ਜੋ ਨ ਜਾਇ ਸੋ ਅਛੇਦ ਕੈ ਪਛਾਨੀਐ।","roman":"Chhedio jo na jaai so achhed kai pachhaaneeai |","meaning_en":"He who cannot be pierced is recognised as the Unpierceable.","page":257,"meaning_status":"draft"},{"gurmukhi":"ਗੰਜਿਓ ਜੋ ਨ ਜਾਇ ਸੋ ਅਗੰਜ ਕੈ ਕੈ ਜਾਨੀਅਤੁ","roman":"Ganjio jo na jaai so aganj kai kai jaaneeatu","meaning_en":"He who cannot be conquered is known as the Unconquerable;","page":257,"meaning_status":"draft"},{"gurmukhi":"ਭੰਜਿਓ ਜੋ ਨ ਜਾਇ ਸੋ ਅਭੰਜ ਕੈ ਕੈ ਮਾਨੀਐ।","roman":"Bhanjio jo na jaai so abhanj kai kai maaneeai |","meaning_en":"He who cannot be broken is accepted as the Unbreakable.","page":257,"meaning_status":"draft"},{"gurmukhi":"ਸਾਧਿਓ ਜੋ ਨ ਜਾਇ ਸੋ ਅਸਾਧਿ ਕੈ ਕੈ ਸਾਧ ਕਰ","roman":"Saadhio jo na jaai so asaadhi kai kai saadh kar","meaning_en":"He who cannot be mastered, know Him as the Unmasterable;","page":257,"meaning_status":"draft","note":"ਅਸਾਧਿ ਕੈ ਕੈ ਸਾਧ ਕਰ: uncertain; perhaps 'call Him the One beyond accomplishment'."},{"gurmukhi":"ਛਲਿਓ ਜੋ ਨ ਜਾਇ ਸੋ ਅਛਲ ਕੈ ਪ੍ਰਮਾਨੀਐ।","roman":"Chhalio jo na jaai so achhal kai pramaaneeai |","meaning_en":"He who cannot be deceived is held to be the Undeceivable.","page":257,"meaning_status":"draft"},{"gurmukhi":"ਮੰਤ੍ਰ ਮੈ ਨ ਆਵੈ ਸੋ ਅਮੰਤ੍ਰ ਕੈ ਕੈ ਮਾਨੁ ਮਨ","roman":"Mantr mai na aavai so amantr kai kai maanu man","meaning_en":"He who does not come within a mantra, accept in your mind as beyond mantra;","page":257,"meaning_status":"draft"},{"gurmukhi":"ਜੰਤ੍ਰ ਮੈ ਨ ਆਵੈ ਸੋ ਅਜੰਤ੍ਰ ਕੈ ਕੈ ਜਾਨੀਐ। ੧। ੪੦।","roman":"Jantr mai na aavai so ajantr kai kai jaaneeai | 1 | 40 |","meaning_en":"He who does not come within a yantra is known as beyond yantra.","page":257,"meaning_status":"draft"}]},{"type":"verse","number":[2,41],"number_text":"੨। ੪੧।","page":257,"lines":[{"gurmukhi":"ਜਾਤ ਮੈ ਨ ਆਵੈ ਸੋ ਅਜਾਤ ਕੈ ਕੈ ਜਾਨ ਜੀਅ","roman":"Jaat mai na aavai so ajaat kai kai jaan jeea","meaning_en":"He who does not come within caste, know in your heart as casteless;","page":257,"meaning_status":"draft"},{"gurmukhi":"ਪਾਤ ਮੈ ਨ ਆਵੈ ਸੋ ਅਪਾਤ ਕੈ ਬੁਲਾਈਐ।","roman":"Paat mai na aavai so apaat kai bulaaeeai |","meaning_en":"He who does not come within lineage is called the One without lineage.","page":257,"meaning_status":"draft"},{"gurmukhi":"ਭੇਦ ਮੈ ਨ ਆਵੈ ਸੋ ਅਭੇਦ ਕੈ ਕੈ ਭਾਖੀਅਤੁ","roman":"Bhed mai na aavai so abhed kai kai bhaakheeatu","meaning_en":"He who does not come within distinction is spoken of as the Undistinguished;","page":257,"meaning_status":"draft"},{"gurmukhi":"ਛੇਦ੍ਯੋ ਜੋ ਨ ਜਾਇ ਸੋ ਅਛੇਦ ਕੈ ਸੁਨਾਈਐ।","roman":"Chhedyo jo na jaai so achhed kai sunaaeeai |","meaning_en":"He who cannot be pierced is proclaimed the Unpierceable.","page":257,"meaning_status":"draft"},{"gurmukhi":"ਖੰਡਿਓ ਜੋ ਨ ਜਾਇ ਸੋ ਅਖੰਡ ਜੂ ਕੋ ਖਿਆਲੁ ਕੀਜੈ","roman":"Khandio jo na jaai so akhand joo ko khiaalu keejai","meaning_en":"He who cannot be broken, think on Him as the Unbroken Lord;","page":257,"meaning_status":"draft"},{"gurmukhi":"ਖਿਆਲ ਮੈ ਨ ਆਵੈ ਗਮੁ ਤਾਕੋ ਸਦਾ ਖਾਈਐ।","roman":"Khiaal mai na aavai gamu taako sadaa khaaeeai |","meaning_en":"He does not come within thought; ever bear the longing for Him.","page":257,"meaning_status":"draft","note":"ਗਮੁ ਤਾਕੋ ਸਦਾ ਖਾਈਐ: lit. 'ever eat the grief (longing) for Him'; uncertain."},{"gurmukhi":"ਜੰਤ੍ਰ ਮੈ ਨ ਆਵੈ ਅਜੰਤ੍ਰ ਕੈ ਕੈ ਜਾਪੀਅਤੁ","roman":"Jantr mai na aavai ajantr kai kai jaapeeatu","meaning_en":"He does not come within a yantra; He is repeated as the One beyond yantra;","page":257,"meaning_status":"draft"},{"gurmukhi":"ਧਿਆਨ ਮੈ ਨ ਆਵੈ ਤਾਕੋ ਧਿਆਨੁ ਕੀਜੈ ਧਿਆਈਐ। ੨। ੪੧।","roman":"Dhiaan mai na aavai taako dhiaanu keejai dhiaaeeai | 2 | 41 |","meaning_en":"He does not come within meditation; meditate on Him, contemplate Him.","page":257,"meaning_status":"draft"}]},{"type":"verse","number":[3,42],"number_text":"੩। ੪੨।","page":257,"lines":[{"gurmukhi":"ਛਤ੍ਰਧਾਰੀ ਛਤ੍ਰੀਪਤਿ ਛੈਲ ਰੂਪ ਛਿਤਨਾਥ","roman":"Chhatradhaaree chhatreepti chhail roop chhitnaath","meaning_en":"Bearer of the canopy, lord of kshatriyas, of graceful form, Lord of the earth,","page":257,"meaning_status":"draft","note":"ਛਤ੍ਰ: royal canopy."},{"gurmukhi":"ਛੌਣੀ ਕਰ ਛਾਇਆ ਬਰ ਛਤ੍ਰੀਪਤ ਗਾਈਐ।","roman":"Chhaunee kar chhaaiaa bar chhatreepat gaaeeai |","meaning_en":"who casts His shade over the earth, the excellent lord of kshatriyas, He is to be sung.","page":257,"meaning_status":"draft"},{"gurmukhi":"ਬਿਸ੍ਵ ਨਾਥ ਬਿਸ੍ਵੰਭਰ ਬੇਦਨਾਥ ਬਾਲਾਕਰ","roman":"Bisv naath bisvanbhar bednaath baalaakar","meaning_en":"Lord of the universe, sustainer of the universe, Lord of the Vedas, a youthful form,","page":257,"meaning_status":"draft","note":"ਬਾਲਾਕਰ: read as 'of youthful form'; uncertain."},{"gurmukhi":"ਬਾਜੀਗਰਿ ਬਾਨ ਧਾਰੀ ਬੰਧ ਨ ਬਤਾਈਐ।","roman":"Baajeegri baan dhaaree bandh na bataaeeai |","meaning_en":"the great Showman, bearer of arrows; no bond of His can be told.","page":257,"meaning_status":"draft","note":"ਬਾਜੀਗਰਿ: 'juggler/showman (of the world-play)'; ਬੰਧ ਨ ਬਤਾਈਐ: 'no bond can be named for Him'; uncertain."},{"gurmukhi":"ਨਿਉਲੀ ਕਰਮ ਦੂਧਾਧਾਰੀ ਬਿਦਿਆਧਰ ਬ੍ਰਹਮਚਾਰੀ","roman":"Niulee karam doodhaadhaaree bidiaadhar brahamchaaree","meaning_en":"Those who practise neoli, who live on milk alone, the learned, the celibates,","page":257,"meaning_status":"draft","note":"ਨਿਉਲੀ ਕਰਮ: a yogic abdominal cleansing practice."},{"gurmukhi":"ਧਿਆਨ ਕੋ ਲਗਾਵੈ ਨੈਕ ਧਿਆਨ ਹੂੰ ਨ ਪਾਈਐ।","roman":"Dhiaan ko lagaavai naik dhiaan hoon na paaeeai |","meaning_en":"though they fix their meditation, cannot attain Him even a little in meditation.","page":257,"meaning_status":"draft"},{"gurmukhi":"ਰਾਜਨ ਕੇ ਰਾਜਾ ਮਹਾਰਾਜਨ ਕੇ ਮਹਾਰਾਜ","roman":"Raajan ke raajaa mahaaraajan ke mahaaraaj","meaning_en":"King of kings, Emperor of emperors;","page":257,"meaning_status":"draft"},{"gurmukhi":"ਐਸੋ ਰਾਜ ਛੋਡਿ ਅਉਰ ਦੂਜਾ ਕਉਨ ਧਿਆਈਐ। ੩। ੪੨।","roman":"Aiso raaj chhodi aur doojaa kaun dhiaaeeai | 3 | 42 |","meaning_en":"leaving such a King, what other should one meditate on?","page":257,"meaning_status":"draft"}]},{"type":"verse","number":[4,43],"number_text":"੪।੪੩।","page":258,"lines":[{"gurmukhi":"ਜੁਧ ਕੇ ਜਿਤਈਆ ਰੰਗ ਭੂਮ ਕੇ ਭਵਈਆ","roman":"Judh ke jitaeeaa rang bhoom ke bhavaeeaa","meaning_en":"Winner of battles, mover of the stage of the world,","page":258,"meaning_status":"draft","note":"ਰੰਗ ਭੂਮ ਕੇ ਭਵਈਆ: 'who turns the arena/stage'; uncertain."},{"gurmukhi":"ਭਾਰਭੂਮ ਕੇ ਮਿਟਈਆ ਨਾਥ ਤੀਨ ਲੋਕ ਗਾਈਐ।","roman":"Bhaarbhoom ke mitaeeaa naath teen lok gaaeeai |","meaning_en":"remover of the earth's burden, the Lord of the three worlds is to be sung.","page":258,"meaning_status":"draft"},{"gurmukhi":"ਕਾਹੂ ਕੇ ਤਨਈਆ ਹੈ ਨ ਮਈਆ ਜਾਕੇ ਭਈਆ ਕੋਊ","roman":"Kaahoo ke tanaeeaa hai na maeeaa jaake bhaeeaa ko'oo","meaning_en":"He is no one's son; He has no mother and no brother;","page":258,"meaning_status":"draft"},{"gurmukhi":"ਛਉਨੀ ਹੂ ਕੇ ਛਈਆ ਛੋਡ ਕਾ ਸਿਉ ਪ੍ਰੀਤ ਲਾਈਐ।","roman":"Chhaunee hoo ke chhaeeaa chhod kaa siu preet laaeeai |","meaning_en":"leaving Him who spreads over the earth, with whom should one fall in love?","page":258,"meaning_status":"draft","note":"ਛਉਨੀ ਹੂ ਕੇ ਛਈਆ: 'who covers/pervades the earth'; uncertain."},{"gurmukhi":"ਸਾਧਨਾ ਸਧਈਆ ਧੂਲ ਧਾਨੀ ਕੇ ਧੁਜਈਆ","roman":"Saadhnaa sadhaeeaa dhool dhaanee ke dhujaeeaa","meaning_en":"Accomplisher of all spiritual practice, who raises the banner over the dusty earth,","page":258,"meaning_status":"draft","note":"ਧੂਲ ਧਾਨੀ ਕੇ ਧੁਜਈਆ: uncertain; perhaps 'who sets the flag over the dusty world' or 'whose standard rises in the dust of battle'."},{"gurmukhi":"ਧੋਮਧਾਰ ਕੇ ਧਰਈਆ ਧਿਆਨ ਤਾਕੋ ਸਦਾ ਲਾਈਐ।","roman":"Dhomdhaar ke dharaeeaa dhiaan taako sadaa laaeeai |","meaning_en":"upholder of the smoky (worlds): ever fix your meditation on Him.","page":258,"meaning_status":"draft","note":"ਧੋਮਧਾਰ ਕੇ ਧਰਈਆ: obscure; perhaps 'supporter of the sky/clouds' or 'holder of the smoke-banner'; uncertain."},{"gurmukhi":"ਆਉ ਕੇ ਬਢਈਆ ਏਕ ਨਾਮ ਕੇ ਜਪਈਆ","roman":"Aau ke badhaeeaa ek naam ke japaeeaa","meaning_en":"He increases life; He makes us repeat the one Name;","page":258,"meaning_status":"draft"},{"gurmukhi":"ਅਉਰ ਕਾਮ ਕੇ ਕਰਈਆ ਛੋਡ ਅਉਰ ਕਉਨ ਧਿਆਈਐ। ੪।੪੩।","roman":"Aur kaam ke karaeeaa chhod aur kaun dhiaaeeai | 4 | 43 |","meaning_en":"and He does all other work; leaving Him, whom else should one meditate on?","page":258,"meaning_status":"draft"}]},{"type":"verse","number":[5,44],"number_text":"੫।੪੪।","page":258,"lines":[{"gurmukhi":"ਕਾਮ ਕੋ ਕੁਨਿੰਦਾ ਖੈਰ ਖੂਬੀ ਕੋ ਦਿਹੰਦਾ","roman":"Kaam ko kunindaa khair khoobee ko dihandaa","meaning_en":"Doer of works, giver of welfare and goodness,","page":258,"meaning_status":"draft","note":"Persian: kunindah 'doer', khair-khubi 'welfare and goodness', dihindah 'giver'."},{"gurmukhi":"ਗਜ ਗਾਜੀ ਕੋ ਗਜਿੰਦਾ ਸੋ ਕੁਨਿੰਦਾ ਕੈ ਬਤਾਈਐ।","roman":"Gaj gaajee ko gajindaa so kunindaa kai bataaeeai |","meaning_en":"thunderer over elephants and warriors: He is to be told of as the Doer.","page":258,"meaning_status":"draft","note":"ਗਜ ਗਾਜੀ ਕੋ ਗਜਿੰਦਾ: uncertain; perhaps 'crusher of elephant-riding champions'."},{"gurmukhi":"ਚਾਮ ਕੇ ਚਲਿੰਦਾ ਘਾਉ ਘਾਮ ਤੇ ਬਚਿੰਦਾ","roman":"Chaam ke chalindaa ghaau ghaam te bachindaa","meaning_en":"Mover of the body of skin, protector from wounds and from heat,","page":258,"meaning_status":"draft","note":"ਚਾਮ ਕੇ ਚਲਿੰਦਾ: uncertain; perhaps 'who makes the bodies of skin move'."},{"gurmukhi":"ਛਤ੍ਰ ਛੈਨੀ ਕੇ ਛਲਿੰਦਾ ਸੋ ਦਿਹੰਦਾ ਕੈ ਮਨਾਈਐ।","roman":"Chhatr chhainee ke chhalindaa so dihandaa kai manaaeeai |","meaning_en":"deceiver of the canopied kings: He is to be honoured as the Giver.","page":258,"meaning_status":"draft","note":"ਛਤ੍ਰ ਛੈਨੀ: uncertain; read as 'canopied rulers'."},{"gurmukhi":"ਜਰ ਕੇ ਦਿਹੰਦਾ ਜਾਨ ਮਾਨ ਕੋ ਜਨਿੰਦਾ","roman":"Jar ke dihandaa jaan maan ko janindaa","meaning_en":"Giver of gold, knower of life and honour,","page":258,"meaning_status":"draft","note":"ਜਰ: Persian zar 'gold'."},{"gurmukhi":"ਜੋਤ ਜੇਬ ਕੋ ਗਜਿੰਦਾ ਜਾਨ ਮਾਨ ਜਾਨ ਗਾਈਐ।","roman":"Jot jeb ko gajindaa jaan maan jaan gaaeeai |","meaning_en":"who makes light and beauty roar forth: sing of Him, knowing Him as life and honour.","page":258,"meaning_status":"draft","note":"ਜੋਤ ਜੇਬ: 'light and adornment' (zeb); ਗਜਿੰਦਾ uncertain."},{"gurmukhi":"ਦੋਖ ਕੇ ਦਲਿੰਦਾ ਦੀਨ ਦਾਨਸ ਦਿਹੰਦਾ","roman":"Dokh ke dalindaa deen daanas dihandaa","meaning_en":"Crusher of faults, giver of faith and wisdom,","page":258,"meaning_status":"draft","note":"ਦੀਨ ਦਾਨਸ: Persian din 'faith' and danish 'wisdom'."},{"gurmukhi":"ਦੋਖ ਦੁਰਜਨ ਦਲਿੰਦਾ ਧਿਆਇ ਦੂਜੋ ਕਉਨ ਧਿਆਈਐ। ੫।੪੪।","roman":"Dokh durjan dalindaa dhiaai doojo kaun dhiaaeeai | 5 | 44 |","meaning_en":"crusher of the faults of the wicked: meditating on Him, whom else should one meditate on?","page":258,"meaning_status":"draft"}]},{"type":"verse","number":[6,45],"number_text":"੬। ੪੫।","page":258,"lines":[{"gurmukhi":"ਸਾਲਿਸ ਸਹਿੰਦਾ ਸਿਧਤਾਈ ਕੋ ਸਧਿੰਦਾ","roman":"Saalis sahindaa sidhtaaee ko sadhindaa","meaning_en":"Bearer of the arbitration, accomplisher of perfection,","page":258,"meaning_status":"draft","note":"ਸਾਲਿਸ ਸਹਿੰਦਾ: Persian salis 'arbiter/mediator'; uncertain."},{"gurmukhi":"ਅੰਗ ਅੰਗ ਮੈ ਅਵਿੰਦਾ ਏਕੁ ਏਕੋ ਨਾਥ ਜਾਨੀਐ।","roman":"Ang ang mai avindaa eku eko naath jaaneeai |","meaning_en":"present in every limb: know the one Lord as the only One.","page":258,"meaning_status":"draft"},{"gurmukhi":"ਕਾਲਖ ਕਟਿੰਦਾ ਖੁਰਾਸਾਨ ਕੋ ਖੁਨਿੰਦਾ","roman":"Kaalakh katindaa khuraasaan ko khunindaa","meaning_en":"Cutter of blackness, destroyer of Khurasan,","page":258,"meaning_status":"draft","note":"ਖੁਨਿੰਦਾ: read as 'destroyer/conqueror'; uncertain."},{"gurmukhi":"ਗ੍ਰਬ ਗਾਫਲ ਗਿਲਿੰਦਾ ਗੋਲ ਗੰਜਖ ਬਖਾਨੀਐ।","roman":"Grab gaaphal gilindaa gol ganjakh bakhaaneeai |","meaning_en":"who swallows the pride of the heedless: tell of Him as the treasury of the world.","page":258,"meaning_status":"draft","note":"ਗੋਲ ਗੰਜਖ: uncertain; perhaps 'treasure of the round world'."},{"gurmukhi":"ਗਾਲਬ ਗਰੰਦਾ ਜੀਤ ਤੇਜ ਕੇ ਦਿਹੰਦਾ","roman":"Gaalab garandaa jeet tej ke dihandaa","meaning_en":"Overpowering, giver of victory and radiance,","page":258,"meaning_status":"draft","note":"ਗਾਲਬ ਗਰੰਦਾ: Persian ghalib 'overpowering'; ਗਰੰਦਾ uncertain ('seizer')."},{"gurmukhi":"ਚਿਤ੍ਰ ਚਾਪ ਕੇ ਚਲਿੰਦਾ ਛੋਡ ਅਉਰ ਕਉਨ ਆਨੀਐ।","roman":"Chitr chaap ke chalindaa chhod aur kaun aaneeai |","meaning_en":"who looses the wondrous bow: leaving Him, whom else should one bring to mind?","page":258,"meaning_status":"draft"},{"gurmukhi":"ਸਤਤਾ ਦਿਹੰਦਾ ਸਤਤਾਈ ਕੋ ਸੁਖਿੰਦਾ","roman":"Sattaa dihandaa sattaaee ko sukhindaa","meaning_en":"Giver of truth, who gives joy to the truthful,","page":258,"meaning_status":"draft","note":"ਸਤਤਾ / ਸਤਤਾਈ: read as 'truth/goodness'; uncertain."},{"gurmukhi":"ਕਰਮ ਕਾਮ ਕੋ ਕੁਨਿੰਦਾ ਛੋਡ ਦੂਜਾ ਕਉਨ ਮਾਨੀਐ। ੬। ੪੫।","roman":"Karam kaam ko kunindaa chhod doojaa kaun maaneeai | 6 | 45 |","meaning_en":"Doer of deeds and works: leaving Him, what other should one accept?","page":258,"meaning_status":"draft"}]},{"type":"verse","number":[7,46],"number_text":"੭। ੪੬।","page":258,"lines":[{"gurmukhi":"ਜੋਤ ਕੋ ਜਗਿੰਦਾ ਜੰਗੇ ਜਾਫਰੀ ਦਿਹੰਦਾ","roman":"Jot ko jagindaa jange jaaphree dihandaa","meaning_en":"Kindler of light, giver of victory in war,","page":258,"meaning_status":"draft","note":"ਜੰਗੇ ਜਾਫਰੀ: Persian, 'victory in battle'."},{"gurmukhi":"ਮਿਤ੍ਰ ਮਾਰੀ ਕੇ ਮਲਿੰਦਾ ਪੈ ਕੁਨਿੰਦਾ ਕੈ ਬਖਾਨੀਐ।","roman":"Mitr maaree ke malindaa pai kunindaa kai bakhaaneeai |","meaning_en":"crusher of the slayers of friends: He is told of as the Doer.","page":258,"meaning_status":"draft","note":"ਮਿਤ੍ਰ ਮਾਰੀ ਕੇ ਮਲਿੰਦਾ: uncertain."},{"gurmukhi":"ਪਾਲਕ ਪੁਨਿੰਦਾ ਪਰਮ ਪਾਰਸੀ ਪ੍ਰਗਿੰਦਾ","roman":"Paalak punindaa param paarsee pragindaa","meaning_en":"Sustainer, purifier, the supreme Lord made manifest,","page":258,"meaning_status":"draft","note":"ਪਾਰਸੀ: uncertain; perhaps 'one who knows/the touchstone'; ਪ੍ਰਗਿੰਦਾ 'revealer'; uncertain."},{"gurmukhi":"ਰੰਗ ਰਾਗ ਕੇ ਸੁਨਿੰਦਾ ਪੈ ਅਨੰਦਾ ਤੇਜ ਮਾਨੀਐ।","roman":"Rang raag ke sunindaa pai anandaa tej maaneeai |","meaning_en":"listener to music and its colours: accept Him as bliss and radiance.","page":258,"meaning_status":"draft"},{"gurmukhi":"ਜਾਪ ਕੇ ਜਪਿੰਦਾ ਖੈਰ ਖੂਬੀ ਕੇ ਦਹਿੰਦਾ","roman":"Jaap ke japindaa khair khoobee ke dahindaa","meaning_en":"Repeater of prayer, giver of welfare and goodness,","page":258,"meaning_status":"draft"},{"gurmukhi":"ਖੂਨ ਮਾਫ ਕੋ ਕੁਨਿੰਦਾ ਹੈ ਅਭਿਜ ਰੂਪ ਠਾਨੀਐ।","roman":"Khoon maaph ko kunindaa hai abhij roop thaaneeai |","meaning_en":"who pardons even bloodshed: hold Him as of untouched form.","page":258,"meaning_status":"draft","note":"ਖੂਨ ਮਾਫ ਕੋ ਕੁਨਿੰਦਾ: 'who forgives (even) murder'."},{"gurmukhi":"ਆਰਜਾ ਦਹਿੰਦਾ ਰੰਗ ਰਾਗ ਕੋ ਬਿਢੰਦਾ","roman":"Aarjaa dahindaa rang raag ko bidhandaa","meaning_en":"Giver of long life, increaser of joy and music,","page":258,"meaning_status":"draft","note":"ਆਰਜਾ: Arabic 'umr / Persian arza, 'lifespan'."},{"gurmukhi":"ਦੁਸਟ ਦ੍ਰੋਹ ਕੇ ਦਲਿੰਦਾ ਛੋਡ ਦੂਜੋ ਕੌਨ ਮਾਨੀਐ। ੭। ੪੬।","roman":"Dusat droh ke dalindaa chhod doojo kaun maaneeai | 7 | 46 |","meaning_en":"crusher of the wicked and the treacherous: leaving Him, what other should one accept?","page":258,"flags":[{"code":"0x71","reason":"subjoined letter typed after the vowel/nasal sign; put in Unicode order (same printed shape)"}],"meaning_status":"draft"}]},{"type":"verse","number":[8,47],"number_text":"੮। ੪੭।","page":259,"lines":[{"gurmukhi":"ਆਤਮਾ ਪ੍ਰਧਾਨ ਜਾਹ ਸਿਧਤਾ ਸਰੂਪ ਤਾਹ","roman":"Aatmaa pradhaan jaah sidhtaa saroop taah","meaning_en":"He whose Self is supreme, whose form is perfection,","page":259,"meaning_status":"draft"},{"gurmukhi":"ਬੁਧਤਾ ਬਿਭੂਤ ਜਾਹ ਸਿਧਤਾ ਸੁਭਾਉ ਹੈ।","roman":"Budhtaa bibhoot jaah sidhtaa subhaau hai |","meaning_en":"whose glory is wisdom, whose nature is perfection;","page":259,"meaning_status":"draft"},{"gurmukhi":"ਰਾਗ ਭੀ ਨ ਰੰਗ ਤਾਹਿ ਰੂਪ ਭੀ ਨ ਰੇਖ ਜਾਹਿ","roman":"Raag bhee na rang taahi roop bhee na rekh jaahi","meaning_en":"He has no attachment, no colour, no form, no mark;","page":259,"meaning_status":"draft"},{"gurmukhi":"ਅੰਗ ਭੀ ਸੁਰੰਗ ਤਾਹ ਰੰਗ ਕੇ ਸੁਭਾਉ ਹੈ।","roman":"Ang bhee surang taah rang ke subhaau hai |","meaning_en":"yet every limb of His is beautifully coloured, by the nature of colour itself.","page":259,"meaning_status":"draft","note":"Line obscure; uncertain."},{"gurmukhi":"ਚਿਤ੍ਰ ਸੋ ਬਚਿਤ੍ਰ ਹੈ ਪਰਮਤਾ ਪਵਿਤ੍ਰ ਹੈ","roman":"Chitr so bachitr hai paramtaa pavitr hai","meaning_en":"He is more wondrous than a picture; His supremacy is pure;","page":259,"meaning_status":"draft"},{"gurmukhi":"ਸੁ ਮਿਤ੍ਰ ਹੂੰ ਕੇ ਮਿਤ੍ਰ ਹੈ ਬਿਭੂਤ ਕੋ ਉਪਾਉ ਹੈ।","roman":"Su mitr hoon ke mitr hai bibhoot ko upaau hai |","meaning_en":"He is the friend of friends, the source of glory;","page":259,"meaning_status":"draft"},{"gurmukhi":"ਦੇਵਨ ਕੇ ਦੇਵ ਹੈ ਕਿ ਸਾਹਨ ਕੇ ਸਾਹ ਹੈ","roman":"Devan ke dev hai ki saahan ke saah hai","meaning_en":"He is the God of gods, the King of kings,","page":259,"meaning_status":"draft"},{"gurmukhi":"ਕਿ ਰਾਜਨ ਕੋ ਰਾਜੁ ਹੈ ਕਿ ਰਾਵਨ ਕੋ ਰਾਉ ਹੈ। ੮। ੪੭।","roman":"Ki raajan ko raaju hai ki raavan ko raau hai | 8 | 47 |","meaning_en":"the Ruler of rulers, the Chief of chiefs.","page":259,"meaning_status":"draft","note":"ਰਾਵਨ ਕੋ ਰਾਉ: read as 'chief of chiefs' (raav)."}]},{"type":"heading","kind":"chhand","name":"ਬਹਿਰ ਤਵੀਲ ਛੰਦ। ਪਸਚਮੀ","gurmukhi":"ਬਹਿਰ ਤਵੀਲ ਛੰਦ। ਪਸਚਮੀ। ਤ੍ਵਪ੍ਰਸਾਦਿ","roman":"Bahir taveel chhand | pasachmee | tvaprasaadi","meaning_en":"Bahir Tavil metre, Western (style). By Your grace.","page":259,"invocation":"ਤ੍ਵਪ੍ਰਸਾਦਿ","meaning_status":"draft","note":"ਪਸਚਮੀ: 'western', i.e. in the Persian manner; uncertain."},{"type":"verse","number":[1,48],"number_text":"੧। ੪੮।","page":259,"lines":[{"gurmukhi":"ਕਿ ਅਗੰਜਸ। ਕਿ ਅਭੰਜਸ। ਕਿ ਅਰੂਪਸ। ਕਿ ਅਰੰਜਸ। ੧। ੪੮।","roman":"Ki aganjas | ki abhanjas | ki aroopas | ki aranjas | 1 | 48 |","meaning_en":"You are unconquerable, unbreakable, formless, without sorrow.","page":259,"meaning_status":"draft","note":"ਕਿ: introductory 'that/You are'."}]},{"type":"verse","number":[2,49],"number_text":"੨। ੪੯।","page":259,"lines":[{"gurmukhi":"ਕਿ ਅਛੇਦਸ। ਕਿ ਅਭੇਦਸ। ਕਿ ਅਨਾਮਸ। ਕਿ ਅਕਾਮਸ। ੨। ੪੯।","roman":"Ki achhedas | ki abhedas | ki anaamas | ki akaamas | 2 | 49 |","meaning_en":"You are unpierceable, beyond mystery, nameless, desireless.","page":259,"meaning_status":"draft"}]},{"type":"verse","number":[3,50],"number_text":"੩। ੫੦।","page":259,"lines":[{"gurmukhi":"ਕਿ ਅਭੇਖਸ। ਕਿ ਅਲੇਖਸ। ਕਿ ਅਨਾਦਸ। ਕਿ ਅਗਾਧਸ। ੩। ੫੦।","roman":"Ki abhekhas | ki alekhas | ki anaadas | ki agaadhas | 3 | 50 |","meaning_en":"You are without guise, beyond writing, beginningless, unfathomable.","page":259,"meaning_status":"draft"}]},{"type":"verse","number":[4,51],"number_text":"੪। ੫੧।","page":259,"lines":[{"gurmukhi":"ਕਿ ਅਰੂਪਸ। ਕਿ ਅਭੂਤਸ। ਕਿ ਅਦਾਗਸ। ਕਿ ਅਰਾਗਸ। ੪। ੫੧।","roman":"Ki aroopas | ki abhootas | ki adaagas | ki araagas | 4 | 51 |","meaning_en":"You are formless, not of the elements, stainless, without attachment.","page":259,"meaning_status":"draft"}]},{"type":"verse","number":[5,52],"number_text":"੫। ੫੨।","page":259,"lines":[{"gurmukhi":"ਕਿ ਅਭੇਦਸ। ਕਿ ਅਛੇਦਸ। ਕਿ ਅਛਾਦਸ। ਕਿ ਅਗਾਧਸ। ੫। ੫੨।","roman":"Ki abhedas | ki achhedas | ki achhaadas | ki agaadhas | 5 | 52 |","meaning_en":"You are beyond mystery, unpierceable, uncovered, unfathomable.","page":259,"meaning_status":"draft","note":"ਅਛਾਦਸ: read as 'uncovered/unconcealed'; uncertain."}]},{"type":"verse","number":[6,53],"number_text":"੬। ੫੩।","page":259,"lines":[{"gurmukhi":"ਕਿ ਅਗੰਜਸ। ਕਿ ਅਭੰਜਸ। ਕਿ ਅਭੇਦਸ। ਕਿ ਅਛੇਦਸ। ੬। ੫੩।","roman":"Ki aganjas | ki abhanjas | ki abhedas | ki achhedas | 6 | 53 |","meaning_en":"You are unconquerable, unbreakable, beyond mystery, unpierceable.","page":259,"meaning_status":"draft"}]},{"type":"verse","number":[7,54],"number_text":"੭। ੫੪।","page":259,"lines":[{"gurmukhi":"ਕਿ ਅਸੇਅਸ। ਕਿ ਅਧੇਅਸ। ਕਿ ਅਗੰਜਸ। ਕਿ ਇਕੰਜਸ। ੭। ੫੪।","roman":"Ki aseas | ki adheas | ki aganjas | ki ikanjas | 7 | 54 |","meaning_en":"You are beyond service, beyond meditation, unconquerable, the One.","page":259,"meaning_status":"draft","note":"ਅਸੇਅਸ, ਅਧੇਅਸ: uncertain; perhaps 'not to be served (as others are)' and 'not an object of meditation'; ਇਕੰਜਸ 'single'."}]},{"type":"verse","number":[8,55],"number_text":"੮। ੫੫।","page":259,"lines":[{"gurmukhi":"ਕਿ ਉਕਾਰਸ। ਕਿ ਨਿਕਾਰਸ। ਕਿ ਅਖੰਜਸ। ਕਿ ਅਭੰਜਸ। ੮। ੫੫।","roman":"Ki ukaaras | ki nikaaras | ki akhanjas | ki abhanjas | 8 | 55 |","meaning_en":"You are the One (Onkar), formless, unbreakable, unbreakable.","page":259,"meaning_status":"draft","note":"ਉਕਾਰਸ: Onkar; ਨਿਕਾਰਸ: 'formless' or 'expelling'; ਅਖੰਜਸ uncertain."}]},{"type":"verse","number":[9,56],"number_text":"੯। ੫੬।","page":259,"lines":[{"gurmukhi":"ਕਿ ਅਘਾਤਸ। ਕਿ ਅਕਿਆਤਸ। ਕਿ ਅਚਲਸ। ਕਿ ਅਛਲਸ। ੯। ੫੬।","roman":"Ki aghaatas | ki akiaatas | ki achlas | ki achhlas | 9 | 56 |","meaning_en":"You are unslayable, beyond describing, unmoving, undeceivable.","page":259,"meaning_status":"draft","note":"ਅਕਿਆਤਸ: read as 'indescribable' or 'not known by fame'; uncertain."}]},{"type":"verse","number":[10,57],"number_text":"੧੦। ੫੭।","page":259,"lines":[{"gurmukhi":"ਕਿ ਅਜਾਤਸ। ਕਿ ਅਝਾਤਸ। ਕਿ ਅਛਲਸ। ਕਿ ਅਟਲਸ। ੧੦। ੫੭।","roman":"Ki ajaatas | ki ajhaatas | ki achhlas | ki atlas | 10 | 57 |","meaning_en":"You are unborn, unseen, undeceivable, immovable.","page":259,"meaning_status":"draft","note":"ਅਝਾਤਸ: read as 'unglimpsed'; uncertain."}]},{"type":"verse","number":[11,58],"number_text":"੧੧। ੫੮।","page":259,"lines":[{"gurmukhi":"ਅਟਾਟਸਚ। ਅਡਾਟਸਚ। ਅਡੰਗਸਚ। ਅਣੰਗਸਚ। ੧੧। ੫੮।","roman":"Ataatsach | adaatsach | adangsach | anangsach | 11 | 58 |","meaning_en":"You are immovable, unshaken, without limb, bodiless.","page":259,"meaning_status":"draft","note":"Alphabetic sequence (ਟ ਡ ਡ ਣ); word senses largely uncertain: ਅਟਾਟਸ 'unmoving', ਅਡਾਟਸ 'unscolded/unshaken', ਅਡੰਗਸ, ਅਣੰਗਸ 'limbless'."}]},{"type":"verse","number":[12,59],"number_text":"੧੨। ੫੯।","page":259,"lines":[{"gurmukhi":"ਅਤਾਨਸਚ। ਅਥਾਨਸਚ। ਅਦੰਗਸਚ। ਅਨੰਗਸਚ। ੧੨। ੫੯।","roman":"Ataansach | athaansach | adangsach | anangsach | 12 | 59 |","meaning_en":"You are without stretch, without place, without fixed form, bodiless.","page":259,"meaning_status":"draft","note":"Alphabetic sequence (ਤ ਥ ਦ ਨ); ਅਤਾਨਸ, ਅਥਾਨਸ 'without place', ਅਦੰਗਸ, ਅਨੰਗਸ 'bodiless'; mostly uncertain."}]},{"type":"verse","number":[13,60],"number_text":"੧੩। ੬੦।","page":259,"lines":[{"gurmukhi":"ਅਪਾਰਸਚ। ਅਠਾਰਸਚ। ਅਬੇਅਸਤੁ। ਅਭੇਅਸਤ। ੧੩। ੬੦।","roman":"Apaarsach | athaarsach | abeastu | abheasat | 13 | 60 |","meaning_en":"You are boundless, without place, without dwelling, without fear.","page":259,"meaning_status":"draft","note":"ਅਠਾਰਸ: read as 'without place' (thaur); ਅਬੇਅਸ, ਅਭੇਅਸ uncertain (perhaps 'without a body', 'without fear')."}]},{"type":"verse","number":[14,61],"number_text":"੧੪। ੬੧।","page":259,"lines":[{"gurmukhi":"ਅਮਾਨਸਚ। ਅਹਾਨਸਚ। ਅੜੰਗਸਚ। ਅਤ੍ਰੰਗਸਚ। ੧੪। ੬੧।","roman":"Amaansach | ahaansach | arangsach | atrangsach | 14 | 61 |","meaning_en":"You are beyond measure, imperishable, unobstructed, without waves.","page":259,"meaning_status":"draft","note":"ਅਮਾਨਸ, ਅਹਾਨਸ 'without loss', ਅੜੰਗਸ 'without obstacle', ਅਤ੍ਰੰਗਸ 'without waves/limbs'; uncertain."}]},{"type":"verse","number":[15,62],"number_text":"੧੫। ੬੨।","page":259,"lines":[{"gurmukhi":"ਅਰਾਮਸਚ। ਅਲਾਮਸਚ। ਅਜੋਧਸਚ। ਅਵੋਜਸਚ। ੧੫। ੬੨।","roman":"Araamsach | alaamsach | ajodhsach | avojsach | 15 | 62 |","meaning_en":"You are without rest (needing none), without sign, unfightable, without vigour (as men have).","page":259,"meaning_status":"draft","note":"Alphabetic sequence; ਅਰਾਮਸ, ਅਲਾਮਸ (alamat 'sign'?), ਅਜੋਧਸ 'unfightable', ਅਵੋਜਸ all uncertain."}]},{"type":"verse","number":[16,63],"number_text":"੧੬। ੬੩।","page":259,"lines":[{"gurmukhi":"ਅਸੇਅਸਤੁ। ਅਭੇਅਸਤੁ। ਆਅੰਗਸਤੁ। ਇਅੰਗਸਤੁ। ੧੬। ੬੩।","roman":"Aseastu | abheastu | aa'angastu | iangastu | 16 | 63 |","meaning_en":"You are beyond service, without fear, without body, the One.","page":259,"meaning_status":"draft","note":"ਆਅੰਗਸ, ਇਅੰਗਸ: uncertain; perhaps 'bodiless', 'single-limbed (the One)'."}]},{"type":"verse","number":[17,64],"number_text":"੧੭। ੬੪।","page":259,"lines":[{"gurmukhi":"ਉਕਾਰਸਤੁ। ਅਕਾਰਸਤੁ। ਅਖੰਡਸਤੁ। ਅਡੰਗਸਤੁ। ੧੭। ੬੪।","roman":"Ukaarastu | akaarastu | akhandastu | adangastu | 17 | 64 |","meaning_en":"You are Onkar, the formless shape, unbroken, without limb.","page":259,"meaning_status":"draft","note":"ਅਕਾਰਸ: 'formless' or 'form'; ਅਡੰਗਸ uncertain."}]},{"type":"verse","number":[18,65],"number_text":"੧੮। ੬੫।","page":259,"lines":[{"gurmukhi":"ਕਿ ਅਤਾਪਹਿ। ਕਿ ਅਥਾਪਹਿ। ਕਿ ਅੰਦਗਹਿ। ਕਿ ਅਨੰਗਹਿ। ੧੮। ੬੫।","roman":"Ki ataaphi | ki athaaphi | ki andaghi | ki ananghi | 18 | 65 |","meaning_en":"You are without affliction, not established, without fixed form, bodiless.","page":259,"meaning_status":"draft","note":"ਅੰਦਗਹਿ: printed so; perhaps 'without bonds' or 'without a burning'; uncertain."}]},{"type":"verse","number":[19,66],"number_text":"੧੯। ੬੬।","page":259,"lines":[{"gurmukhi":"ਕਿ ਅਤਾਪਹਿ। ਕਿ ਅਥਾਪਹਿ। ਕਿ ਅਨੀਲਹਿ। ਕਿ ਸੁਨੀਲਹਿ। ੧੯। ੬੬।","roman":"Ki ataaphi | ki athaaphi | ki aneelhi | ki suneelhi | 19 | 66 |","meaning_en":"You are without affliction, not established, not blue, and beautifully blue.","page":259,"meaning_status":"draft","note":"ਅਨੀਲਹਿ ਸੁਨੀਲਹਿ: 'not dark / fair dark' or 'without stain'; uncertain."}]},{"type":"heading","kind":"chhand","name":"ਅਰਧ ਨਰਾਜਛੰਦ। ਤ੍ਵਪ੍ਰਸਾਦ","gurmukhi":"ਅਰਧ ਨਰਾਜਛੰਦ। ਤ੍ਵਪ੍ਰਸਾਦ","roman":"Aradh naraajchhand | tvaprasaad","meaning_en":"Ardh Naraj metre. By Your grace.","page":260,"meaning_status":"draft"},{"type":"verse","number":[1,67],"number_text":"੧। ੬੭।","page":260,"lines":[{"gurmukhi":"ਸਜਸ ਤੁਯੰ। ਧਜਸ ਤੁਯੰ। ਅਲਸ ਤੁਯੰ। ਇਕਸ ਤੁਯੰ। ੧। ੬੭।","roman":"Sajas tuyan | dhajas tuyan | alas tuyan | ikas tuyan | 1 | 67 |","meaning_en":"You are the adorned, You are the banner, You are the unseen, You are the One.","page":260,"meaning_status":"draft","note":"ਸਜਸ, ਧਜਸ, ਅਲਸ: uncertain senses."}]},{"type":"verse","number":[2,68],"number_text":"੨। ੬੮।","page":260,"lines":[{"gurmukhi":"ਜਲਸ ਤੁਯੰ। ਥਲਸ ਤੁਯੰ। ਪੁਰਸ ਤੁਯੰ। ਬਨਸ ਤੁਯੰ। ੨। ੬੮।","roman":"Jalas tuyan | thalas tuyan | puras tuyan | banas tuyan | 2 | 68 |","meaning_en":"You are in water, You are on land, You are in the town, You are in the forest.","page":260,"meaning_status":"draft"}]},{"type":"verse","number":[3,69],"number_text":"੩। ੬੯।","page":260,"lines":[{"gurmukhi":"ਗੁਰਸ ਤੁਯੰ। ਗੁਫਸ ਤੁਯੰ। ਨਿਰਸ ਤੁਯੰ। ਨਿਦਸ ਤੁਯੰ। ੩। ੬੯।","roman":"Guras tuyan | guphas tuyan | niras tuyan | nidas tuyan | 3 | 69 |","meaning_en":"You are the Guru, You are the hidden, You are the lowly, You are the reviled.","page":260,"meaning_status":"draft","note":"ਗੁਫਸ: 'hidden (in caves)'; ਨਿਰਸ: 'without taste' or 'humble'; ਨਿਦਸ: 'the reviled' or 'without fault'; uncertain."}]},{"type":"verse","number":[4,70],"number_text":"੪। ੭੦।","page":260,"lines":[{"gurmukhi":"ਰਵਸ ਤੁਯੰ। ਸਸਸ ਤੁਯੰ। ਰਜਸ ਤੁਯੰ। ਤਮਸ ਤੁਯੰ। ੪। ੭੦।","roman":"Ravas tuyan | sasas tuyan | rajas tuyan | tamas tuyan | 4 | 70 |","meaning_en":"You are the sun, You are the moon, You are rajas, You are tamas.","page":260,"meaning_status":"draft","note":"ਰਜਸ ਤਮਸ: the qualities of activity and darkness."}]},{"type":"verse","number":[5,71],"number_text":"੫। ੭੧।","page":260,"lines":[{"gurmukhi":"ਧਨਸ ਤੁਯੰ। ਮਨਸ ਤੁਯੰ। ਬ੍ਰਿਛਸ ਤੁਯੰ। ਬਨਸ ਤੁਯੰ। ੫। ੭੧।","roman":"Dhanas tuyan | manas tuyan | brichhas tuyan | banas tuyan | 5 | 71 |","meaning_en":"You are wealth, You are the mind, You are the tree, You are the forest.","page":260,"meaning_status":"draft"}]},{"type":"verse","number":[6,72],"number_text":"੬। ੭੨।","page":260,"lines":[{"gurmukhi":"ਮਤਸ ਤੁਯੰ। ਗਤਸ ਤੁਯੰ। ਬ੍ਰਤਸ ਤੁਯੰ। ਚਿਤਸ ਤੁਯੰ। ੬। ੭੨।","roman":"Matas tuyan | gatas tuyan | bratas tuyan | chitas tuyan | 6 | 72 |","meaning_en":"You are the intellect, You are the state of release, You are the vow, You are the consciousness.","page":260,"meaning_status":"draft"}]},{"type":"verse","number":[7,73],"number_text":"੭। ੭੩।","page":260,"lines":[{"gurmukhi":"ਪਿਤਸ ਤੁਯੰ। ਸੁਤਸ ਤੁਯੰ। ਮਤਸ ਤੁਯੰ। ਗਤਸ ਤੁਯੰ। ੭। ੭੩।","roman":"Pitas tuyan | sutas tuyan | matas tuyan | gatas tuyan | 7 | 73 |","meaning_en":"You are the father, You are the son, You are the mother, You are the end (refuge).","page":260,"meaning_status":"draft","note":"ਮਤਸ: read as 'mother' (mata); ਗਤਸ 'state/refuge'; uncertain."}]},{"type":"verse","number":[8,74],"number_text":"੮। ੭੪।","page":260,"lines":[{"gurmukhi":"ਨਰਸ ਤੁਯੰ। ਤ੍ਰਿਯਸ ਤੁਯੰ। ਪਿਤਸ ਤੁਯੰ। ਬ੍ਰਿਦਸ ਤੁਯੰ। ੮। ੭੪।","roman":"Naras tuyan | triyas tuyan | pitas tuyan | bridas tuyan | 8 | 74 |","meaning_en":"You are man, You are woman, You are father, You are the old one.","page":260,"meaning_status":"draft","note":"ਬ੍ਰਿਦਸ: 'old' (vriddh) or 'great'; uncertain."}]},{"type":"verse","number":[9,75],"number_text":"੯। ੭੫।","page":260,"lines":[{"gurmukhi":"ਹਰਸ ਤੁਯੰ। ਕਰਸ ਤੁਯੰ। ਛਲਸ ਤੁਯੰ। ਬਲਸ ਤੁਯੰ। ੯। ੭੫।","roman":"Haras tuyan | karas tuyan | chhalas tuyan | balas tuyan | 9 | 75 |","meaning_en":"You are the destroyer, You are the doer, You are deceit, You are strength.","page":260,"meaning_status":"draft"}]},{"type":"verse","number":[10,76],"number_text":"੧੦। ੭੬।","page":260,"lines":[{"gurmukhi":"ਉਡਸ ਤੁਯੰ। ਪੁਡਸ ਤੁਯੰ। ਗਡਸ ਤੁਯੰ। ਦਧਸ ਤੁਯੰ। ੧੦। ੭੬।","roman":"Udas tuyan | pudas tuyan | gadas tuyan | dadhas tuyan | 10 | 76 |","meaning_en":"You are the star, You are the earth, You are the fort, You are the ocean.","page":260,"meaning_status":"draft","note":"ਉਡਸ 'star' (udu); ਪੁਡਸ, ਗਡਸ uncertain ('earth', 'fort'); ਦਧਸ 'ocean' (udadhi)."}]},{"type":"verse","number":[11,77],"number_text":"੧੧। ੭੭।","page":260,"lines":[{"gurmukhi":"ਰਵਸ ਤੁਯੰ। ਛਪਸ ਤੁਯੰ। ਗਰਬਸ ਤੁਯੰ। ਦਿਰਬਸ ਤੁਯੰ। ੧੧। ੭੭।","roman":"Ravas tuyan | chhapas tuyan | garbas tuyan | dirbas tuyan | 11 | 77 |","meaning_en":"You are the sun, You are the hidden, You are pride, You are wealth.","page":260,"meaning_status":"draft","note":"ਛਪਸ: 'hidden' or 'night'; ਦਿਰਬਸ: 'wealth' (dravya); uncertain."}]},{"type":"verse","number":[12,78],"number_text":"੧੨। ੭੮।","page":260,"lines":[{"gurmukhi":"ਜੈਅਸ ਤੁਯੰ। ਖੈਅਸ ਤੁਯੰ। ਪੈਅਸ ਤੁਯੰ। ਤ੍ਰੈਅਸ ਤੁਯੰ। ੧੨। ੭੮।","roman":"Jaias tuyan | khaias tuyan | paias tuyan | traias tuyan | 12 | 78 |","meaning_en":"You are victory, You are destruction, You are nourishment (milk), You are the three (worlds).","page":260,"meaning_status":"draft","note":"ਪੈਅਸ: 'milk/water' (payas); ਤ੍ਰੈਅਸ: 'the three'; uncertain."}]},{"type":"heading","kind":"chhand","name":"ਨਿਰਾਜ ਛੰਦ","gurmukhi":"ਨਿਰਾਜ ਛੰਦ। ਤ੍ਵਪ੍ਰਸਾਦਿ","roman":"Niraaj chhand | tvaprasaadi","meaning_en":"Niraj metre. By Your grace.","page":260,"invocation":"ਤ੍ਵਪ੍ਰਸਾਦਿ","meaning_status":"draft","note":"Printed ਨਿਰਾਜ; same metre as Naraj."},{"type":"verse","number":[1,79],"number_text":"੧। ੭੯।","page":260,"lines":[{"gurmukhi":"ਚਕੰਤ ਚਾਰ ਚੰਦ੍ਰਕਾ। ਸੁਭੰਤ ਰਾਜ ਸੁ ਪ੍ਰਭਾ।","roman":"Chakant chaar chandrakaa | subhant raaj su prabhaa |","meaning_en":"His lovely moon-like light dazzles; royal splendour shines on Him;","page":260,"meaning_status":"draft"},{"gurmukhi":"ਦਵੰਤ ਦੁਸਟ ਮੰਡਲੀ। ਸੁਭੰਤ ਰਾਜ ਸੁ ਥਲੀ। ੧। ੭੯।","roman":"Davant dusat mandlee | subhant raaj su thalee | 1 | 79 |","meaning_en":"He burns the hosts of the wicked; His royal seat shines.","page":260,"meaning_status":"draft"}]},{"type":"verse","number":[2,80],"number_text":"੨। ੮੦।","page":260,"lines":[{"gurmukhi":"ਚਲੰਤ ਚੰਡ ਮੰਡਕਾ। ਅਖੰਡ ਖੰਡ ਦੁਪਲਾ।","roman":"Chalant chand mandkaa | akhand khand duplaa |","meaning_en":"The fierce (army of His) arrays moves; He breaks the unbroken two-fold (armies);","page":260,"meaning_status":"draft","note":"ਚੰਡ ਮੰਡਕਾ, ਅਖੰਡ ਖੰਡ ਦੁਪਲਾ: very uncertain."},{"gurmukhi":"ਖਿਵੰਤ ਬਿਜੁ ਜ੍ਵਾਲਕਾ। ਅਨੰਤ ਗਦਿ ਬਿਦਸਾ। ੨। ੮੦।","roman":"Khivant biju jvaalkaa | anant gadi bidsaa | 2 | 80 |","meaning_en":"it flashes like flames of lightning, with endless cries (in all directions).","page":260,"meaning_status":"draft","note":"ਅਨੰਤ ਗਦਿ ਬਿਦਸਾ: uncertain; perhaps 'endless maces in every direction'."}]},{"type":"verse","number":[3,81],"number_text":"੩। ੮੧।","page":260,"lines":[{"gurmukhi":"ਲਸੰਤ ਭਾਵ ਉਜਲੰ। ਦਲੰਤ ਦੁਖ ਦੁ ਦਲੰ।","roman":"Lasant bhaav ujlan | dalant dukh du dalan |","meaning_en":"His bright aspect shines; He crushes sorrow and the hosts of evil.","page":260,"meaning_status":"draft","note":"ਦੁਖ ਦੁ ਦਲੰ: 'sorrow and the hosts of the wicked'; uncertain."},{"gurmukhi":"ਪਵੰਗ ਪਾਤ ਸੋਹੀਯੰ। ਸਮੁੰਦ੍ਰ ਬਾਜ ਲੋਹੀਯੰ। ੩। ੮੧।","roman":"Pavang paat soheeyan | samundr baaj loheeyan | 3 | 81 |","meaning_en":"Rows of steeds look splendid; ocean-born horses clad in steel.","page":260,"meaning_status":"draft","note":"ਸਮੁੰਦ੍ਰ ਬਾਜ: perhaps 'horses of the sea (Uchaishrava-like)'; ਲੋਹੀਯੰ 'armoured' or 'red'; uncertain."}]},{"type":"verse","number":[4,82],"number_text":"੪। ੮੨।","page":260,"lines":[{"gurmukhi":"ਨਿਨੰਦ ਗੇਦ ਬ੍ਰਿਦਯੰ। ਅਖੇਦ ਨਾਦ ਦੁਧਰੰ।","roman":"Ninand ged bridyan | akhed naad dudhran |","meaning_en":"Great drums resound; untiring sounds ring out on both sides.","page":260,"meaning_status":"draft","note":"Line obscure; ਗੇਦ ਬ੍ਰਿਦਯੰ, ਦੁਧਰੰ uncertain."},{"gurmukhi":"ਅਠਟ ਬਟ ਬਟਕੰ। ਅਘਟ ਅਨਟ ਸੁਖਲੰ। ੪। ੮੨।","roman":"Athat bat batkan | aghat anat sukhlan | 4 | 82 |","meaning_en":"Not to be shaken, beyond paths and byways; undiminishing, unending in joy.","page":260,"meaning_status":"draft","note":"Line obscure; uncertain."}]},{"type":"verse","number":[5,83],"number_text":"੫। ੮੩।","page":260,"lines":[{"gurmukhi":"ਅਖੁਟ ਤੁਟ ਦ੍ਰਿਬਕੰ। ਅਜੁਟ ਛੁਟ ਸੁਛਕੰ।","roman":"Akhut tut dribkan | ajut chhut suchhkan |","meaning_en":"His wealth is inexhaustible, never failing; unbound, free and pure;","page":260,"meaning_status":"draft","note":"Line obscure; uncertain."},{"gurmukhi":"ਅਘੁਟ ਤੁਟ ਆਸਨੰ। ਅਲੇਖ ਅਭੇਖ ਅਨਾਸਨੰ। ੫। ੮੩।","roman":"Aghut tut aasnan | alekh abhekh anaasnan | 5 | 83 |","meaning_en":"His seat never lessens or breaks; beyond writing, without guise, imperishable.","page":260,"meaning_status":"draft"}]},{"type":"verse","number":[6,84],"number_text":"੬। ੮੪।","page":261,"lines":[{"gurmukhi":"ਸੁਭੰਤ ਦੰਤ ਪਦੁਕੰ। ਜਲੰਤ ਸਾਮ ਸੁ ਘਟੰ।","roman":"Subhant dant padukan | jalant saam su ghatan |","meaning_en":"(Elephants) with shining tusks; dark (elephants) like clouds blaze;","page":261,"meaning_status":"draft","note":"ਦੰਤ ਪਦੁਕੰ, ਸਾਮ ਸੁ ਘਟੰ: read as 'tusked' and 'dark as clouds'; uncertain."},{"gurmukhi":"ਸੁਭੰਤ ਛੁਦ੍ਰ ਘੰਟਕਾ। ਜਲੰਤ ਭਾਰ ਕਛਟਾ। ੬। ੮੪।","roman":"Subhant chhudr ghantkaa | jalant bhaar kachhtaa | 6 | 84 |","meaning_en":"small bells shine (on them); their heavy trappings gleam.","page":261,"meaning_status":"draft","note":"ਕਛਟਾ: uncertain."}]},{"type":"verse","number":[7,85],"number_text":"੭। ੮੫।","page":261,"lines":[{"gurmukhi":"ਸਿਰੀਸੁ ਸੀਸ ਸੁਭੀਯੰ। ਘਟਾਕ ਬਾਨ ਉਭੀਯੰ।","roman":"Sireesu sees subheeyan | ghataak baan ubheeyan |","meaning_en":"Plumes adorn their heads; arrows rise like clouds;","page":261,"meaning_status":"draft","note":"ਸਿਰੀਸੁ: 'ornament for the head'; uncertain."},{"gurmukhi":"ਸੁਭੰਤ ਸੀਸ ਸਿਧਰੰ। ਜਲੰਤ ਸਿਧਰੀ ਨਰੰ। ੭। ੮੫।","roman":"Subhant sees sidhran | jalant sidhree naran | 7 | 85 |","meaning_en":"vermilion shines on their foreheads; the vermilion-marked men gleam.","page":261,"meaning_status":"draft","note":"ਸਿਧਰੰ, ਸਿਧਰੀ: read as sindur 'vermilion'; uncertain."}]},{"type":"verse","number":[8,86],"number_text":"੮। ੮੬।","page":261,"lines":[{"gurmukhi":"ਚਲੰਤ ਦੰਤ ਪਤਕੰ। ਭਜੰਤ ਦੇਖਿ ਦੁਦਲੰ।","roman":"Chalant dant patkan | bhajant dekhi dudlan |","meaning_en":"The rows of tusked elephants move; seeing them, the enemy hosts flee;","page":261,"meaning_status":"draft"},{"gurmukhi":"ਤਜੰਤ ਸਸਤ੍ਰ ਅਸਤ੍ਰਕੰ। ਚਲੰਤ ਚਕ੍ਰ ਚਉਦਿਸੰ। ੮। ੮੬।","roman":"Tajant sasatr astrakan | chalant chakr chaudisan | 8 | 86 |","meaning_en":"they abandon their weapons and arms; His discus moves in the four directions.","page":261,"meaning_status":"draft"}]},{"type":"verse","number":[9,87],"number_text":"੯। ੮੭।","page":261,"lines":[{"gurmukhi":"ਅਗੰਮ ਤੇਜ ਸੋਭੀਯੰ। ਰਿਖੀਸ ਈਸ ਲੋਭੀਯੰ।","roman":"Aganm tej sobheeyan | rikhees ees lobheeyan |","meaning_en":"His inaccessible radiance shines; the great sages and gods long for Him;","page":261,"meaning_status":"draft"},{"gurmukhi":"ਅਨੇਕ ਬਾਰ ਧਿਆਵਹੀ। ਨ ਤਤ੍ਰ ਪਾਰ ਪਾਵਹੀ। ੯। ੮੭।","roman":"Anek baar dhiaavhee | na tatr paar paavhee | 9 | 87 |","meaning_en":"they meditate on Him many times, yet do not find His limit.","page":261,"meaning_status":"draft"}]},{"type":"verse","number":[10,88],"number_text":"੧੦। ੮੮।","page":261,"lines":[{"gurmukhi":"ਅਧੋ ਸੁ ਧੂਮ ਧੂਮਹੀ। ਅਘੂਰ ਨੇਤ੍ਰ ਘੂਮਹੀ।","roman":"Adho su dhoom dhoomhee | aghoor netr ghoomhee |","meaning_en":"Some, head downward, breathe in smoke; some roll their eyes in trance;","page":261,"meaning_status":"draft","note":"ਅਘੂਰ: printed so; read as 'roll (the eyes)'."},{"gurmukhi":"ਸੁ ਪੰਚ ਅਗਨ ਸਾਧੀਯੰ। ਨ ਤਾਮ ਪਾਰ ਲਾਧੀਯੰ। ੧੦। ੮੮।","roman":"Su panch agan saadheeyan | na taam paar laadheeyan | 10 | 88 |","meaning_en":"some practise the five fires; yet they do not find His limit.","page":261,"meaning_status":"draft"}]},{"type":"verse","number":[11,89],"number_text":"੧੧। ੮੯।","page":261,"lines":[{"gurmukhi":"ਨਿਵਲ ਆਦਿ ਕਰਮਣੰ। ਅਨੰਤ ਦਾਨ ਧਰਮਣੰ।","roman":"Nival aadi karamnan | anant daan dharamnan |","meaning_en":"Neoli and other practices, endless charity and religious acts,","page":261,"meaning_status":"draft"},{"gurmukhi":"ਅਨੰਤ ਤੀਰਥ ਬਾਸਨੰ। ਨ ਏਕ ਨਾਮ ਕੇ ਸਮੰ। ੧੧। ੮੯।","roman":"Anant teerath baasnan | na ek naam ke saman | 11 | 89 |","meaning_en":"dwelling at endless places of pilgrimage: none equals the one Name.","page":261,"meaning_status":"draft"}]},{"type":"verse","number":[12,90],"number_text":"੧੨। ੯੦।","page":261,"lines":[{"gurmukhi":"ਅਨੰਤ ਜਗ੍ਯ ਕਰਮਣੰ। ਗਜਾਦਿ ਆਦਿ ਧਰਮਣੰ।","roman":"Anant jagy karamnan | gajaadi aadi dharamnan |","meaning_en":"Endless sacrifices, the gift of elephants and other acts of merit,","page":261,"meaning_status":"draft"},{"gurmukhi":"ਅਨੇਕ ਦੇਸ ਭਰਮਣੰ। ਨ ਏਕ ਨਾਮ ਕੇ ਸਮੰ। ੧੨। ੯੦।","roman":"Anek des bharamnan | na ek naam ke saman | 12 | 90 |","meaning_en":"wandering in many lands: none equals the one Name.","page":261,"meaning_status":"draft"}]},{"type":"verse","number":[13,91],"number_text":"੧੩। ੯੧।","page":261,"lines":[{"gurmukhi":"ਇਕੰਤ ਕੁੰਟ ਬਾਸਨੰ। ਭ੍ਰਮੰਤ ਕੋਟਕੰ ਬਨੰ।","roman":"Ikant kunt baasnan | bhramant kotkan banan |","meaning_en":"Living in a solitary corner, wandering through millions of forests,","page":261,"meaning_status":"draft"},{"gurmukhi":"ਉਚਾਟਨਾਦ ਕਰਮਣੰ। ਅਨੇਕ ਉਦਾਸ ਭਰਮਣੰ। ੧੩। ੯੧।","roman":"Uchaatnaad karamnan | anek udaas bharamnan | 13 | 91 |","meaning_en":"spells to drive others away and like acts, many wanderings in renunciation;","page":261,"meaning_status":"draft","note":"ਉਚਾਟਨ: a spell to cause aversion/distraction."}]},{"type":"verse","number":[14,92],"number_text":"੧੪। ੯੨।","page":261,"lines":[{"gurmukhi":"ਅਨੇਕ ਭੇਖ ਆਸਨੰ। ਕਰੋਰ ਕੋਟਕੰ ਬ੍ਰਤੰ।","roman":"Anek bhekh aasnan | karor kotkan bratan |","meaning_en":"many guises and postures, millions upon millions of fasts,","page":261,"meaning_status":"draft"},{"gurmukhi":"ਦਿਸਾ ਦਿਸਾ ਭ੍ਰਮੇਸਨੰ। ਅਨੇਕ ਭੇਖ ਪੇਖਨੰ। ੧੪। ੯੨।","roman":"Disaa disaa bhramesnan | anek bhekh pekhnan | 14 | 92 |","meaning_en":"wandering from direction to direction, seeing many guises;","page":261,"meaning_status":"draft"}]},{"type":"verse","number":[15,93],"number_text":"੧੫। ੯੩।","page":261,"lines":[{"gurmukhi":"ਕਰੋਰ ਕੋਟ ਦਾਨਕੰ। ਅਨੇਕ ਜਗ੍ਯ ਕ੍ਰਤਬਿਯੰ।","roman":"Karor kot daankan | anek jagy kratbiyan |","meaning_en":"millions upon millions of gifts, many sacrifices performed,","page":261,"meaning_status":"draft"},{"gurmukhi":"ਸਨ੍ਯਾਸ ਆਦਿ ਧਰਮਣੰ। ਉਦਾਸ ਨਾਮ ਕਰਮਣੰ। ੧੫। ੯੩।","roman":"Sanyaas aadi dharamnan | udaas naam karamnan | 15 | 93 |","meaning_en":"sannyas and other paths, deeds done in the name of detachment;","page":261,"meaning_status":"draft"}]},{"type":"verse","number":[16,94],"number_text":"੧੬। ੯੪।","page":261,"lines":[{"gurmukhi":"ਅਨੇਕ ਪਾਠ ਪਾਠਨੰ। ਅਨੰਤ ਠਾਟ ਠਾਟਨੰ।","roman":"Anek paath paathnan | anant thaat thaatnan |","meaning_en":"many recitations of scripture, endless displays of show:","page":261,"meaning_status":"draft"},{"gurmukhi":"ਨ ਏਕ ਨਾਮ ਕੇ ਸਮੰ। ਸਮਸਤ ਸ੍ਰਿਸਟ ਕੇ ਭ੍ਰਮੰ। ੧੬। ੯੪।","roman":"Na ek naam ke saman | samsat srisat ke bhraman | 16 | 94 |","meaning_en":"none equals the one Name; all these are the illusions of the whole world.","page":261,"meaning_status":"draft"}]},{"type":"verse","number":[17,95],"number_text":"੧੭। ੯੫।","page":261,"lines":[{"gurmukhi":"ਜਗਾਦਿ ਆਦਿ ਧਰਮਣੰ। ਬੈਰਾਗ ਆਦਿ ਕਰਮਣੰ।","roman":"Jagaadi aadi dharamnan | bairaag aadi karamnan |","meaning_en":"Sacrifice and other religious acts, renunciation and other deeds,","page":261,"meaning_status":"draft","note":"ਜਗਾਦਿ: read as 'yajna (sacrifice) and the like'."},{"gurmukhi":"ਦਯਾਦਿ ਆਦਿ ਕਾਮਣੰ। ਅਨਾਦ ਸੰਜਮੰ ਬ੍ਰਿਦੰ। ੧੭। ੯੫।","roman":"Dayaadi aadi kaamnan | anaad sanjman bridan | 17 | 95 |","meaning_en":"compassion and other virtuous acts, countless disciplines of the ancients;","page":261,"meaning_status":"draft","note":"ਅਨਾਦ ਸੰਜਮੰ ਬ੍ਰਿਦੰ: read as 'many disciplines from of old'; uncertain."}]},{"type":"verse","number":[18,96],"number_text":"੧੮। ੯੬।","page":262,"lines":[{"gurmukhi":"ਅਨੇਕ ਦੇਸ ਭਰਮਣੰ। ਕਰੋਰ ਦਾਨ ਸੰਜਮੰ।","roman":"Anek des bharamnan | karor daan sanjman |","meaning_en":"wandering in many lands, millions of gifts and disciplines,","page":262,"meaning_status":"draft"},{"gurmukhi":"ਅਨੇਕ ਗੀਤ ਗਿਆਨਨੰ। ਅਨੰਤ ਗਿਆਨ ਧਿਆਨਨੰ। ੧੮। ੯੬।","roman":"Anek geet giaannan | anant giaan dhiaannan | 18 | 96 |","meaning_en":"many songs of knowledge, endless knowledge and meditation;","page":262,"meaning_status":"draft"}]},{"type":"verse","number":[19,97],"number_text":"੧੯। ੯੭।","page":262,"lines":[{"gurmukhi":"ਅਨੰਤ ਗਿਆਨ ਸੁਤਮੰ। ਅਨੇਕ ਕ੍ਰਿਤ ਸੁ ਬ੍ਰਿਤੰ।","roman":"Anant giaan sutman | anek krit su britan |","meaning_en":"endless knowledge of the finest, many deeds and fine observances:","page":262,"meaning_status":"draft","note":"ਸੁਤਮੰ: read as 'excellent'; uncertain."},{"gurmukhi":"ਬਿਆਸ ਨਾਰਦ ਆਦਕੰ। ਸੁ ਬ੍ਰਹਮੁ ਮਰਮ ਨਹਿ ਲਹੰ। ੧੯। ੯੭।","roman":"Biaas naarad aadkan | su brahmu maram nahi lahan | 19 | 97 |","meaning_en":"Vyas, Narad and others did not grasp the secret of the Supreme.","page":262,"meaning_status":"draft"}]},{"type":"verse","number":[20,98],"number_text":"੨੦। ੯੮।","page":262,"lines":[{"gurmukhi":"ਕਰੋਰ ਜੰਤ੍ਰ ਮੰਤ੍ਰਣੰ। ਅਨੰਤ ਤੰਤ੍ਰਣੰ ਬਣੰ।","roman":"Karor jantr mantranan | anant tantranan banan |","meaning_en":"Millions of yantras and mantras, endless tantras devised,","page":262,"meaning_status":"draft"},{"gurmukhi":"ਬਸੇਖ ਬ੍ਯਾਸ ਨਾਸਨੰ। ਅਨੰਤ ਨ੍ਯਾਸ ਪ੍ਰਾਸਨੰ। ੨੦। ੯੮।","roman":"Basekh byaas naasnan | anant nyaas praasnan | 20 | 98 |","meaning_en":"special remedies to destroy ailments, endless nyasas (ritual touchings) and offerings.","page":262,"meaning_status":"draft","note":"ਬਸੇਖ ਬ੍ਯਾਸ ਨਾਸਨੰ: read as 'special (means) to destroy disease'; ਪ੍ਰਾਸਨੰ: 'eating/offerings' or 'feeding'; uncertain."}]},{"type":"verse","number":[21,99],"number_text":"੨੧। ੯੯।","page":262,"lines":[{"gurmukhi":"ਜਪੰਤ ਦੇਵ ਦੈਤਨੰ। ਥਪੰਤ ਜਛ ਗੰਧ੍ਰਬੰ।","roman":"Japant dev daitnan | thapant jachh gandhraban |","meaning_en":"Gods and demons repeat His name; Yakshas and Gandharvas establish (His praise);","page":262,"meaning_status":"draft","note":"ਥਪੰਤ: 'establish/install'; uncertain."},{"gurmukhi":"ਬਦੰਤ ਬਿਦਣੋਧਰੰ। ਗਣੰਤ ਸੇਸ ਉਰਗਣੰ। ੨੧। ੯੯।","roman":"Badant bidnodhran | ganant ses uragnan | 21 | 99 |","meaning_en":"the Vidyadhars speak of Him; Shesh and the serpents count (His names).","page":262,"meaning_status":"draft"}]},{"type":"verse","number":[22,100],"number_text":"੨੨। ੧੦੦।","page":262,"lines":[{"gurmukhi":"ਜਪੰਤ ਪਾਰਵਾਰਯੰ। ਸਮੁੰਦ੍ਰ ਸਪਤ ਧਾਰਯੰ।","roman":"Japant paarvaaryan | samundr sapat dhaaryan |","meaning_en":"The ocean, the seven seas repeat His name;","page":262,"meaning_status":"draft","note":"ਪਾਰਵਾਰਯੰ: 'ocean'."},{"gurmukhi":"ਜਣੰਤ ਚਾਰ ਚਕ੍ਰਣੰ। ਧ੍ਰਮੰਤ ਚਕ੍ਰ ਬਕ੍ਰਣੰ। ੨੨। ੧੦੦।","roman":"Janant chaar chakranan | dhramant chakr bakranan | 22 | 100 |","meaning_en":"beings of the four quarters are born (of Him); the crooked wheel (of time) revolves.","page":262,"meaning_status":"draft","note":"ਜਣੰਤ ਚਾਰ ਚਕ੍ਰਣੰ: perhaps 'the four directions know Him'; ਧ੍ਰਮੰਤ ਚਕ੍ਰ ਬਕ੍ਰਣੰ: uncertain."}]},{"type":"verse","number":[23,101],"number_text":"੨੩। ੧੦੧।","page":262,"lines":[{"gurmukhi":"ਜਪੰਤ ਪੰਨਗੰ ਨਕੰ। ਬਰੰ ਨਰੰ ਬਨਸਪਤੰ।","roman":"Japant panngan nakan | baran naran bansaptan |","meaning_en":"Serpents and dwellers of heaven repeat His name, the best of men, the vegetation,","page":262,"meaning_status":"draft","note":"ਨਕੰ: read as 'heaven' (nak); uncertain."},{"gurmukhi":"ਅਕਾਸ ਉਰਬੀਅੰ ਜਲੰ। ਜਪੰਤ ਜੀਵ ਜਲ ਥਲੰ। ੨੩। ੧੦੧।","roman":"Akaas urbeean jalan | japant jeev jal thalan | 23 | 101 |","meaning_en":"sky, earth and water; the beings of water and land repeat His name.","page":262,"meaning_status":"draft"}]},{"type":"verse","number":[24,102],"number_text":"੨੪। ੧੦੨।","page":262,"lines":[{"gurmukhi":"ਸੋ ਕੋਟ ਚਕ੍ਰ ਬਕਤ੍ਰਣੰ। ਬਦੰਤ ਬੇਦ ਚਤ੍ਰਕੰ।","roman":"So kot chakr baktranan | badant bed chatrakan |","meaning_en":"Millions of mouths in every quarter, and the four Vedas speak of Him;","page":262,"meaning_status":"draft","note":"ਕੋਟ ਚਕ੍ਰ ਬਕਤ੍ਰਣੰ: uncertain."},{"gurmukhi":"ਅਸੰਭ ਅਸੰਭ ਮਾਨੀਐ। ਕਰੋਰ ਬਿਸਨ ਠਾਨੀਐ। ੨੪। ੧੦੨।","roman":"Asanbh asanbh maaneeai | karor bisan thaaneeai | 24 | 102 |","meaning_en":"accept Him as the Unborn, the Unborn; He fashioned millions of Vishnus.","page":262,"meaning_status":"draft"}]},{"type":"verse","number":[25,103],"number_text":"੨੫। ੧੦੩।","page":262,"lines":[{"gurmukhi":"ਅਨੰਤ ਸੁਰਸੁਤੀ ਸਤੀ। ਬਦੰਤ ਕ੍ਰਿਤ ਈਸੁਰੀ।","roman":"Anant sursutee satee | badant krit eesuree |","meaning_en":"Endless Saraswatis and Satis tell of His glory as Lord;","page":262,"meaning_status":"draft"},{"gurmukhi":"ਅਨੰਤ ਅਨੰਤ ਭਾਖੀਐ। ਅਨੰਤ ਅੰਤ ਲਾਖੀਐ। ੨੫। ੧੦੩।","roman":"Anant anant bhaakheeai | anant ant laakheeai | 25 | 103 |","meaning_en":"He is called Endless, Endless; His end is to be seen as endless.","page":262,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਬ੍ਰਿਧ ਨਰਾਜ ਛੰਦ","gurmukhi":"ਬ੍ਰਿਧ ਨਰਾਜ ਛੰਦ","roman":"Bridh naraaj chhand","meaning_en":"Bridh Naraj metre.","page":262,"meaning_status":"draft"},{"type":"verse","number":[1,104],"number_text":"੧। ੧੦੪।","page":262,"lines":[{"gurmukhi":"ਅਨਾਦਿ ਅਗਾਧਿ ਬਿਆਧਿ ਆਦਿ ਅਨਾਦਿ ਕੋ ਮਨਾਈਐ।","roman":"Anaadi agaadhi biaadhi aadi anaadi ko manaaeeai |","meaning_en":"Worship the Beginningless, Unfathomable, remover of ailments, primal, beginningless One;","page":262,"meaning_status":"draft"},{"gurmukhi":"ਅਗੰਜ ਅਭੰਜ ਅਰੰਜ ਅਗੰਜ ਗੰਜ ਕਉ ਧਿਆਈਐ।","roman":"Aganj abhanj aranj aganj ganj kau dhiaaeeai |","meaning_en":"meditate on the unconquerable, unbreakable, sorrowless One, conqueror of the unconquered;","page":262,"meaning_status":"draft"},{"gurmukhi":"ਅਲੇਖ ਅਭੇਖ ਅਦ੍ਵੈਖ ਅਰੇਖ ਅਸੇਖ ਕੋ ਪਛਾਨੀਐ।","roman":"Alekh abhekh advaikh arekh asekh ko pachhaaneeai |","meaning_en":"recognise the One beyond writing, without guise, without malice, without mark, the whole;","page":262,"meaning_status":"draft","note":"ਅਸੇਖ: 'entire, without remainder'."},{"gurmukhi":"ਨ ਭੂਲ ਜੰਤ੍ਰ ਤੰਤ੍ਰ ਮੰਤ੍ਰ ਭਰਮ ਭੇਖ ਠਾਨੀਐ। ੧। ੧੦੪।","roman":"Na bhool jantr tantr mantr bharam bhekh thaaneeai | 1 | 104 |","meaning_en":"do not, in error, take up yantra, tantra, mantra, illusion and guises.","page":262,"meaning_status":"draft"}]},{"type":"verse","number":[2,105],"number_text":"੨। ੧੦੫।","page":262,"lines":[{"gurmukhi":"ਕ੍ਰਿਪਾਲ ਲਾਲ ਅਕਾਲ ਅਪਾਲ ਦਇਆਲ ਕੋ ਉਚਾਰੀਐ।","roman":"Kripaal laal akaal apaal daiaal ko uchaareeai |","meaning_en":"Utter the name of the gracious Beloved, the Timeless, the Sustainer of the unprotected, the Merciful;","page":262,"meaning_status":"draft","note":"ਅਪਾਲ: perhaps 'protector of the unprotected' or 'needing no protector'; uncertain."},{"gurmukhi":"ਅਧਰਮ ਕਰਮ ਧਰਮ ਭਰਮ ਕਰਮ ਮੈ ਬਿਚਾਰੀਐ।","roman":"Adhram karam dharam bharam karam mai bichaareeai |","meaning_en":"reflect on unrighteous deeds, righteous deeds, and deeds of illusion;","page":262,"meaning_status":"draft"},{"gurmukhi":"ਅਨੰਤ ਦਾਨ ਧਿਆਨ ਗਿਆਨ ਧਿਆਨਵਾਨ ਪੇਖੀਐ।","roman":"Anant daan dhiaan giaan dhiaanvaan pekheeai |","meaning_en":"see the endless gifts, meditation, knowledge and the men of meditation:","page":262,"meaning_status":"draft"},{"gurmukhi":"ਅਧਰਮ ਕਰਮ ਕੇ ਬਿਨਾ ਸੁ ਧਰਮ ਕਰਮ ਲੇਖੀਐ। ੨। ੧੦੫।","roman":"Adhram karam ke binaa su dharam karam lekheeai | 2 | 105 |","meaning_en":"count only that as righteous action which is free of unrighteous action.","page":262,"meaning_status":"draft"}]},{"type":"verse","number":[3,106],"number_text":"੩। ੧੦੬।","page":263,"lines":[{"gurmukhi":"ਬ੍ਰਤਾਦਿ ਦਾਨ ਸੰਜਮਾਦਿ ਤੀਰਥ ਦੇਵ ਕਰਮਣੰ।","roman":"Brataadi daan sanjmaadi teerath dev karamnan |","meaning_en":"Fasts and charity, disciplines, pilgrimages, worship of gods,","page":263,"meaning_status":"draft"},{"gurmukhi":"ਹੈ ਆਦਿ ਕੁੰਜਮੇਦ ਰਾਜਸੂ ਬਿਨਾ ਨ ਭਰਮਣੰ।","roman":"Hai aadi kunjmed raajsoo binaa na bharamnan |","meaning_en":"the horse and elephant sacrifices, the Rajsu: without (the Lord) these are but illusion.","page":263,"meaning_status":"draft","note":"ਹੈ ਆਦਿ ਕੁੰਜਮੇਦ: 'horse (sacrifice) and elephant sacrifice'; ਬਿਨਾ ਨ ਭਰਮਣੰ: read as 'without Him, they are only illusion'; uncertain."},{"gurmukhi":"ਨਿਵਲ ਆਦਿ ਕਰਮ ਭੇਖ ਅਨੇਕ ਭੇਖ ਮਾਨੀਐ।","roman":"Nival aadi karam bhekh anek bhekh maaneeai |","meaning_en":"Neoli and other practices, guises, many guises are honoured,","page":263,"meaning_status":"draft"},{"gurmukhi":"ਅਦੇਖ ਭੇਖ ਕੇ ਬਿਨਾ ਸੁ ਕਰਮ ਭਰਮ ਜਾਨੀਐ। ੩। ੧੦੬।","roman":"Adekh bhekh ke binaa su karam bharam jaaneeai | 3 | 106 |","meaning_en":"yet without the unseen Lord, know such deeds to be illusion.","page":263,"meaning_status":"draft","note":"ਅਦੇਖ ਭੇਖ: read as 'the unseen, guise-less Lord'; uncertain."}]},{"type":"verse","number":[4,107],"number_text":"੪। ੧੦੭।","page":263,"lines":[{"gurmukhi":"ਅਜਾਤ ਪਾਤ ਅਮਾਤ ਤਾਤ ਅਜਾਤ ਸਿਧ ਹੈ ਸਦਾ।","roman":"Ajaat paat amaat taat ajaat sidh hai sadaa |","meaning_en":"Without caste or lineage, without mother or father, unborn, He is ever perfect;","page":263,"meaning_status":"draft"},{"gurmukhi":"ਅਸਤ੍ਰ ਮਿਤ੍ਰ ਪੁਤ੍ਰ ਪਉਤ੍ਰ ਜਤ੍ਰ ਤਤ੍ਰ ਸਰਬਦਾ।","roman":"Asatr mitr putr pautr jatr tatr sarabdaa |","meaning_en":"without enemy, friend, son or grandson, He is here, there, everywhere;","page":263,"meaning_status":"draft","note":"ਅਸਤ੍ਰ: read as 'without enemy' (a-shatru); the negative may apply to the whole list."},{"gurmukhi":"ਅਖੰਡ ਮੰਡ ਚੰਡ ਉਦੰਡ ਅਖੰਡ ਖੰਡ ਭਾਖੀਐ।","roman":"Akhand mand chand udand akhand khand bhaakheeai |","meaning_en":"He is spoken of as unbroken, adorner, fierce, exalted, the breaker of the unbroken;","page":263,"meaning_status":"draft"},{"gurmukhi":"ਨ ਰੂਪ ਰੰਗ ਰੇਖ ਅਲੇਖ ਭੇਖ ਮੈ ਨ ਰਾਖੀਐ। ੪। ੧੦੭।","roman":"Na roop rang rekh alekh bhekh mai na raakheeai | 4 | 107 |","meaning_en":"He has no form, colour or mark; He is beyond writing and keeps no guise.","page":263,"meaning_status":"draft"}]},{"type":"verse","number":[5,108],"number_text":"੫। ੧੦੮।","page":263,"lines":[{"gurmukhi":"ਅਨੰਤ ਤੀਰਥ ਆਦਿ ਆਸਨਾਦਿ ਨਾਰਦ ਆਸਨੰ।","roman":"Anant teerath aadi aasnaadi naarad aasnan |","meaning_en":"Endless pilgrimages, yogic postures, the seats of Narad,","page":263,"meaning_status":"draft","note":"ਨਾਰਦ ਆਸਨੰ: uncertain."},{"gurmukhi":"ਬੈਰਾਗ ਅਉ ਸੰਨਿਆਸ ਅਉ ਅਨਾਦਿ ਜੋਗ ਪ੍ਰਾਸਨੰ।","roman":"Bairaag au sanniaas au anaadi jog praasnan |","meaning_en":"renunciation, sannyas, and ancient yoga practices,","page":263,"meaning_status":"draft","note":"ਪ੍ਰਾਸਨੰ: uncertain."},{"gurmukhi":"ਅਨਾਦਿ ਤੀਰਥ ਸੰਜਮਾਦਿ ਬਰਤ ਨੇਮ ਪੇਖੀਐ।","roman":"Anaadi teerath sanjmaadi barat nem pekheeai |","meaning_en":"ancient pilgrimages, disciplines, fasts and observances are seen;","page":263,"meaning_status":"draft"},{"gurmukhi":"ਅਨਾਦਿ ਅਗਾਧਿ ਕੇ ਬਿਨਾ ਸਮਸਤ ਭਰਮ ਲੇਖੀਐ। ੫। ੧੦੮।","roman":"Anaadi agaadhi ke binaa samsat bharam lekheeai | 5 | 108 |","meaning_en":"without the Beginningless, Unfathomable One, count them all as illusion.","page":263,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਰਸਾਵਲ ਛੰਦ","gurmukhi":"ਰਸਾਵਲ ਛੰਦ","roman":"Rasaaval chhand","meaning_en":"Rasaval metre.","page":263,"meaning_status":"draft"},{"type":"verse","number":[1,109],"number_text":"੧। ੧੦੯।","page":263,"lines":[{"gurmukhi":"ਦਇਆਦਿ ਆਦਿ ਧਰਮੰ। ਸੰਨਿਆਸ ਆਦਿ ਕਰਮੰ।","roman":"Daiaadi aadi dharman | sanniaas aadi karman |","meaning_en":"Compassion and other righteous acts, sannyas and other deeds,","page":263,"meaning_status":"draft"},{"gurmukhi":"ਗਜਾਦਿ ਆਦਿ ਦਾਨੰ। ਹਯਾਦਿ ਆਦਿ ਥਾਨੰ। ੧। ੧੦੯।","roman":"Gajaadi aadi daanan | hayaadi aadi thaanan | 1 | 109 |","meaning_en":"gifts of elephants and the like, gifts of horses and the like,","page":263,"meaning_status":"draft","note":"ਥਾਨੰ: printed so; read as 'gifts'; uncertain."}]},{"type":"verse","number":[2,110],"number_text":"੨। ੧੧੦।","page":263,"lines":[{"gurmukhi":"ਸੁਵਰਨ ਆਦਿ ਦਾਨੰ। ਸਮੁੰਦ੍ਰ ਆਦਿ ਇਸਨਾਨੰ।","roman":"Suvran aadi daanan | samundr aadi isnaanan |","meaning_en":"gifts of gold and the like, bathing in the ocean and the like,","page":263,"meaning_status":"draft"},{"gurmukhi":"ਬਿਸੁਵਾਦਿ ਆਦਿ ਭਰਮੰ। ਬਿਰਕਤਾਦਿ ਆਦਿ ਕਰਮੰ। ੨। ੧੧੦।","roman":"Bisuvaadi aadi bharman | biraktaadi aadi karman | 2 | 110 |","meaning_en":"wandering through the world and the like, deeds of detachment and the like,","page":263,"meaning_status":"draft","note":"ਬਿਸੁਵਾਦਿ ਆਦਿ ਭਰਮੰ: uncertain; perhaps 'wandering the universe'."}]},{"type":"verse","number":[3,111],"number_text":"੩। ੧੧੧।","page":263,"lines":[{"gurmukhi":"ਨਿਵਲ ਆਦਿ ਕਰਣੰ। ਸੁ ਨੀਲ ਆਦਿ ਬਰਣੰ।","roman":"Nival aadi karnan | su neel aadi barnan |","meaning_en":"neoli and other practices, wearing blue and other colours,","page":263,"meaning_status":"draft"},{"gurmukhi":"ਅਨੀਲ ਆਦਿ ਧਿਆਨੰ। ਜਪਤ ਤਤ ਪ੍ਰਧਾਨੰ। ੩। ੧੧੧।","roman":"Aneel aadi dhiaanan | japat tat pradhaanan | 3 | 111 |","meaning_en":"meditating on the stainless and so on: repeating (the Name) is the chief essence.","page":263,"meaning_status":"draft","note":"ਅਨੀਲ: 'not blue' or 'stainless'; uncertain."}]},{"type":"verse","number":[4,112],"number_text":"੪। ੧੧੨।","page":263,"lines":[{"gurmukhi":"ਅਮਿਤਕਾਦਿ ਭਗਤੰ। ਅਵਿਕਤਾਦਿ ਬ੍ਰਕਤੰ।","roman":"Amitkaadi bhagtan | aviktaadi braktan |","meaning_en":"Boundless devotion and the like, the unmanifest and the manifest,","page":263,"meaning_status":"draft","note":"Line obscure; uncertain."},{"gurmukhi":"ਪ੍ਰਛਸਤੁਵਾ ਪ੍ਰਜਾਪੰ। ਪ੍ਰਭਗਤਾ ਅਥਾਪੰ। ੪। ੧੧੨।","roman":"Prachhastuvaa prajaapan | prabhagtaa athaapan | 4 | 112 |","meaning_en":"His praise is repeated everywhere; He is the true devotion, not established (by any).","page":263,"meaning_status":"draft","note":"ਪ੍ਰਛਸਤੁਵਾ ਪ੍ਰਜਾਪੰ, ਪ੍ਰਭਗਤਾ ਅਥਾਪੰ: very uncertain."}]},{"type":"verse","number":[5,113],"number_text":"੫। ੧੧੩।","page":263,"lines":[{"gurmukhi":"ਸੁ ਭਗਤਾਦਿ ਕਰਣੰ। ਅਜਗਤੁਆ ਪ੍ਰਹਰਣੰ।","roman":"Su bhagtaadi karnan | ajagtuaa praharnan |","meaning_en":"He makes fine devotion; He strikes down the unworthy;","page":263,"meaning_status":"draft","note":"ਅਜਗਤੁਆ: uncertain; perhaps 'the godless/unworthy'."},{"gurmukhi":"ਬਿਰਕਤੁਆ ਪ੍ਰਕਾਸੰ। ਅਵਿਗਤੁਆ ਪ੍ਰਣਾਸੰ। ੫। ੧੧੩।","roman":"Biraktuaa prakaasan | avigtuaa pranaasan | 5 | 113 |","meaning_en":"He reveals detachment; He destroys ignorance.","page":263,"meaning_status":"draft","note":"ਅਵਿਗਤੁਆ ਪ੍ਰਣਾਸੰ: uncertain; 'avigat' usually 'unmanifest'."}]},{"type":"verse","number":[6,114],"number_text":"੬। ੧੧੪।","page":263,"lines":[{"gurmukhi":"ਸਮਸਤੁਆ ਪ੍ਰਧਾਨੰ। ਧੁਜਸਤੁਆ ਧਰਾਨੰ।","roman":"Samastuaa pradhaanan | dhujastuaa dharaanan |","meaning_en":"He is foremost of all; He bears the banner over the earth;","page":263,"meaning_status":"draft","note":"ਧੁਜਸਤੁਆ ਧਰਾਨੰ: uncertain."},{"gurmukhi":"ਅਵਿਕਤੁਆ ਅਭੰਗੰ। ਇਕਸਤੁਆ ਅਨੰਗੰ। ੬। ੧੧੪।","roman":"Aviktuaa abhangan | ikastuaa anangan | 6 | 114 |","meaning_en":"He is unmanifest and unbreakable; He is the One, bodiless.","page":263,"meaning_status":"draft"}]},{"type":"verse","number":[7,115],"number_text":"੭। ੧੧੫।","page":264,"lines":[{"gurmukhi":"ਉਅਸਤੁਆ ਅਕਾਰੰ। ਕ੍ਰਿਪਸਤੁਆ ਕ੍ਰਿਪਾਰੰ।","roman":"Uastuaa akaaran | kripastuaa kripaaran |","meaning_en":"He is Onkar, the formless; He is grace, the gracious;","page":264,"meaning_status":"draft","note":"Alphabetic sequence (ਉ ਕ ਖ ਗ ...) begins here; senses uncertain."},{"gurmukhi":"ਖਿਤਸਤੁਆ ਅਖੰਡੰ। ਗਤਸਤੁਆ ਅਗੰਡੰ। ੭। ੧੧੫।","roman":"Khitastuaa akhandan | gatastuaa agandan | 7 | 115 |","meaning_en":"He is the earth, unbroken; He is the goal, unbound.","page":264,"meaning_status":"draft","note":"ਅਗੰਡੰ: uncertain; perhaps 'without knot'."}]},{"type":"verse","number":[8,116],"number_text":"੮। ੧੧੬।","page":264,"lines":[{"gurmukhi":"ਘਰਸਤੁਆ ਘਰਾਨੰ। ਙ੍ਰਿਅਸਤੁਆ ਙ੍ਰਿਹਾਲੰ।","roman":"Gharastuaa gharaanan | ngriastuaa ngrihaalan |","meaning_en":"He is the home, the home of homes; He is [untranslated] (the alphabet letter ਙ).","page":264,"meaning_status":"draft","note":"Alphabetic acrostic; ਙ੍ਰਿਅਸਤੁਆ ਙ੍ਰਿਹਾਲੰ is built on the letter ਙ and has no clear sense; left untranslated."},{"gurmukhi":"ਚਿਤਸਤੁਆ ਅਤਾਪੰ। ਛਿਤਸਤੁਆ ਅਛਾਪੰ। ੮। ੧੧੬।","roman":"Chitastuaa ataapan | chhitastuaa achhaapan | 8 | 116 |","meaning_en":"He is consciousness, free of affliction; He is the earth, yet unstamped (by any mark).","page":264,"meaning_status":"draft","note":"Alphabetic acrostic (ਚ ਛ); senses uncertain."}]},{"type":"verse","number":[9,117],"number_text":"੯। ੧੧੭।","page":264,"lines":[{"gurmukhi":"ਜਿਤਸਤੁਆ ਅਜਾਪੰ। ਝਿਕਸਤੁਆ ਅਝਾਪੰ।","roman":"Jitastuaa ajaapan | jhikastuaa ajhaapan |","meaning_en":"He is victory, beyond repetition; He is [untranslated], beyond glimpse.","page":264,"meaning_status":"draft","note":"Alphabetic acrostic (ਜ ਝ); ਝਿਕਸਤੁਆ ਅਝਾਪੰ unclear; uncertain."},{"gurmukhi":"ਇਕਸਤੁਆ ਅਨੇਕੰ। ਟੁਟਸਤੁਆ ਅਟੇਟੰ। ੯। ੧੧੭।","roman":"Ikastuaa anekan | tutastuaa atetan | 9 | 117 |","meaning_en":"He is One and many; He is breaking, yet unbreakable.","page":264,"meaning_status":"draft","note":"ਟੁਟਸਤੁਆ ਅਟੇਟੰ: uncertain."}]},{"type":"verse","number":[10,118],"number_text":"੧੦। ੧੧੮।","page":264,"lines":[{"gurmukhi":"ਠਟਸਤੁਆ ਅਠਾਟੰ। ਡਟਸਤੁਆ ਅਡਾਟੰ।","roman":"Thatastuaa athaatan | datastuaa adaatan |","meaning_en":"He is display, yet beyond display; He is firmness, yet unshaken.","page":264,"meaning_status":"draft","note":"Alphabetic acrostic (ਠ ਡ); uncertain."},{"gurmukhi":"ਢਟਸਤੁਆ ਅਢਾਪੰ। ਣਕਸਤੁਆ ਅਣਾਪੰ। ੧੦। ੧੧੮।","roman":"Dhatastuaa adhaapan | nakastuaa anaapan | 10 | 118 |","meaning_en":"He is [untranslated], yet [untranslated]; (letters ਢ and ਣ).","page":264,"meaning_status":"draft","note":"ਢਟਸਤੁਆ ਅਢਾਪੰ, ਣਕਸਤੁਆ ਅਣਾਪੰ: acrostic forms with no clear sense; left untranslated."}]},{"type":"verse","number":[11,119],"number_text":"੧੧। ੧੧੯।","page":264,"lines":[{"gurmukhi":"ਤਪਸਤੁਆ ਅਤਾਪੰ। ਥਪਸਤੁਆ ਅਥਾਪੰ।","roman":"Tapastuaa ataapan | thapastuaa athaapan |","meaning_en":"He is austerity, yet free of heat; He is establishing, yet not established.","page":264,"meaning_status":"draft"},{"gurmukhi":"ਦਲਸਤੁਆਦਿ ਦੋਖੰ। ਨਹਿਸਤੁਆ ਅਨੋਖੰ। ੧੧। ੧੧੯।","roman":"Dalastuaadi dokhan | nahistuaa anokhan | 11 | 119 |","meaning_en":"He crushes faults; He is beyond all, unique.","page":264,"meaning_status":"draft","note":"ਨਹਿਸਤੁਆ ਅਨੋਖੰ: uncertain."}]},{"type":"verse","number":[12,120],"number_text":"੧੨। ੧੨੦।","page":264,"lines":[{"gurmukhi":"ਅਪਕਤੁਆ ਅਪਾਨੰ। ਫਲਕਤੁਆ ਫਲਾਨੰ।","roman":"Apaktuaa apaanan | phalaktuaa phalaanan |","meaning_en":"He is [untranslated], beyond breath; He is the fruit, the giver of fruit.","page":264,"meaning_status":"draft","note":"ਅਪਕਤੁਆ ਅਪਾਨੰ: uncertain."},{"gurmukhi":"ਬਦਕਤੁਆ ਬਿਸੇਖੰ। ਭਜਸਤੁਆ ਅਭੇਖੰ। ੧੨। ੧੨੦।","roman":"Badaktuaa bisekhan | bhajastuaa abhekhan | 12 | 120 |","meaning_en":"He is speech, the distinguished; He is worship, the guise-less.","page":264,"meaning_status":"draft","note":"ਬਦਕਤੁਆ: read as 'speech' or 'evil'; uncertain."}]},{"type":"verse","number":[13,121],"number_text":"੧੩। ੧੨੧।","page":264,"lines":[{"gurmukhi":"ਮਤਸਤੁਆ ਫਲਾਨੰ। ਹਰਿਕਤੁਆ ਹਿਰਦਾਨੰ।","roman":"Matastuaa phalaanan | hariktuaa hirdaanan |","meaning_en":"He is intellect, the giver of fruit; He is Hari, in the heart.","page":264,"meaning_status":"draft","note":"ਹਿਰਦਾਨੰ: read as 'in the heart' or 'giver of gold'; uncertain."},{"gurmukhi":"ਅੜਕਤੁਆ ਅੜੰਗੰ। ਤ੍ਰਿਕਸਤੁਆ ਤ੍ਰਿਭੰਗੰ। ੧੩। ੧੨੧।","roman":"Araktuaa arangan | trikastuaa tribhangan | 13 | 121 |","meaning_en":"He is obstinacy, the obstacle-free; He is the three-fold, the three-curved.","page":264,"meaning_status":"draft","note":"ਤ੍ਰਿਭੰਗੰ: perhaps 'in three postures' or 'breaker of the three (qualities)'; uncertain."}]},{"type":"verse","number":[14,122],"number_text":"੧੪। ੧੨੨।","page":264,"lines":[{"gurmukhi":"ਰੰਗਸਤੁਆ ਅਰੰਗੰ। ਲਵਸਤੁਆ ਅਲੰਗੰ।","roman":"Rangastuaa arangan | lavastuaa alangan |","meaning_en":"He is colour, and colourless; He is [untranslated], and without sign.","page":264,"meaning_status":"draft","note":"ਲਵਸਤੁਆ ਅਲੰਗੰ: uncertain."},{"gurmukhi":"ਯਕਸਤੁਆ ਯਕਾਪੰ। ਇਕਸਤੁਆ ਇਕਾਪੰ। ੧੪। ੧੨੨।","roman":"Yakastuaa yakaapan | ikastuaa ikaapan | 14 | 122 |","meaning_en":"He is One, the Unique; He is One, the Single.","page":264,"meaning_status":"draft","note":"ਯਕ: Persian yak 'one'."}]},{"type":"verse","number":[15,123],"number_text":"੧੫। ੧੨੩।","page":264,"lines":[{"gurmukhi":"ਵਦਿਸਤੁਆ ਵਰਦਾਨੰ। ਯਕਸਤੁਆ ਇਕਾਨੰ।","roman":"Vadistuaa vardaanan | yakastuaa ikaanan |","meaning_en":"He is the giver of boons; He is One, the One.","page":264,"meaning_status":"draft"},{"gurmukhi":"ਲਵਸਤੁਆ ਅਲੇਖੰ। ਰਰਿਸਤੁਆ ਅਰੇਖੰ। ੧੫। ੧੨੩।","roman":"Lavastuaa alekhan | raristuaa arekhan | 15 | 123 |","meaning_en":"He is [untranslated], beyond writing; He is [untranslated], without mark.","page":264,"meaning_status":"draft","note":"ਲਵਸਤੁਆ, ਰਰਿਸਤੁਆ: uncertain."}]},{"type":"verse","number":[16,124],"number_text":"੧੬। ੧੨੪।","page":264,"lines":[{"gurmukhi":"ਤ੍ਰਿਅਸਤੁਆ ਤ੍ਰਿਭੰਗੇ। ਹਰਿਸਤੁਆ ਹਰੰਗੇ।","roman":"Triastuaa tribhange | haristuaa harange |","meaning_en":"He is three-fold, the breaker of the three; He is Hari, beyond colour.","page":264,"meaning_status":"draft","note":"ਹਰੰਗੇ: perhaps 'of every colour' or 'Hari's form'; uncertain."},{"gurmukhi":"ਮਹਿਸਤੁਆ ਮਹੇਸੰ। ਭਜਸਤੁਆ ਅਭੇਸੰ। ੧੬। ੧੨੪।","roman":"Mahistuaa mahesan | bhajastuaa abhesan | 16 | 124 |","meaning_en":"He is great, the great Lord; He is worship, beyond guise.","page":264,"meaning_status":"draft"}]},{"type":"verse","number":[17,125],"number_text":"੧੭। ੧੨੫।","page":264,"lines":[{"gurmukhi":"ਬਰਸਤੁਆ ਬਰਾਨੰ। ਪਲਸਤੁਆ ਫਲਾਨੰ।","roman":"Barastuaa baraanan | palastuaa phalaanan |","meaning_en":"He is the boon, the best of boons; He is the fruit, the giver of fruit.","page":264,"meaning_status":"draft"},{"gurmukhi":"ਨਰਸਤੁਆ ਨਰੇਸੰ। ਦਲਸਤੁਸਾ ਦਲੇਸੰ। ੧੭। ੧੨੫।","roman":"Narastuaa naresan | dalastusaa dalesan | 17 | 125 |","meaning_en":"He is man, the lord of men; He is the host, the lord of hosts.","page":264,"meaning_status":"draft","note":"Printed ਦਲਸਤੁਸਾ; read as ਦਲਸਤੁਆ."}]},{"type":"heading","kind":"chhand","name":"ਪਾਧੜੀ ਛੰਦ","gurmukhi":"ਪਾਧੜੀ ਛੰਦ। ਤ੍ਵਪ੍ਰਸਾਦਿ","roman":"Paadhree chhand | tvaprasaadi","meaning_en":"Padhari metre. By Your grace.","page":264,"invocation":"ਤ੍ਵਪ੍ਰਸਾਦਿ","meaning_status":"draft"},{"type":"verse","number":[1,126],"number_text":"੧। ੧੨੬।","page":264,"lines":[{"gurmukhi":"ਦਿਨ ਅਜਬ ਏਕ ਆਤਮਾ ਰਾਮ। ਅਨਭਉ ਸਰੂਪ ਅਨਹਦ ਅਕਾਮ।","roman":"Din ajab ek aatmaa raam | anbhau saroop anhad akaam |","meaning_en":"One wondrous day the Atma (soul), (spoke to) Ram, of fearless form, unstruck, desireless,","page":264,"meaning_status":"draft","note":"ਦਿਨ ਅਜਬ: 'one wondrous day'; the subject (the soul addressing the Supreme Soul) is continued in the next verse; uncertain."},{"gurmukhi":"ਅਨਛਿਜ ਤੇਜ ਆਜਾਨ ਬਾਹੁ। ਰਾਜਾਨ ਰਾਜ ਸਾਹਾਨ ਸਾਹੁ। ੧। ੧੨੬।","roman":"Anchhij tej aajaan baahu | raajaan raaj saahaan saahu | 1 | 126 |","meaning_en":"of unbreakable radiance, with arms to the knees, King of kings, Emperor of emperors.","page":264,"meaning_status":"draft"}]},{"type":"verse","number":[2,127],"number_text":"੨। ੧੨੭।","page":265,"lines":[{"gurmukhi":"ਉਚਰਿਓ ਆਤਮਾ ਪਰਮਾਤਮਾ ਸੰਗ। ਉਤਭੁਜ ਸਰੂਪ ਅਬਿਗਤ ਅਭੰਗ।","roman":"Uchrio aatmaa parmaatmaa sang | utbhuj saroop abigat abhang |","meaning_en":"The soul spoke to the Supreme Soul: \"O form of the creation, unmanifest, unbreakable,","page":265,"meaning_status":"draft","note":"ਉਤਭੁਜ: 'sprouting/creation'; read as addressed epithets; uncertain."},{"gurmukhi":"ਇਹ ਕਉਨ ਆਹਿ ਆਤਮਾ ਸਰੂਪ। ਜਿਹ ਅਮਿਤ ਤੇਜਿ ਅਤਿਭੁਤਿ ਬਿਭੂਤਿ। ੨। ੧੨੭।","roman":"Ih kaun aahi aatmaa saroop | jih amit teji atibhuti bibhooti | 2 | 127 |","meaning_en":"who is this, of the form of the soul, whose radiance is boundless and glory wondrous?\"","page":265,"meaning_status":"draft"}]},{"type":"heading","kind":"speaker","name":"ਪਰਾਤਮਾ ਬਾਚ","gurmukhi":"ਪਰਾਤਮਾ ਬਾਚ","roman":"Paraatmaa baach","meaning_en":"The Supreme Soul said:","page":265,"meaning_status":"draft"},{"type":"verse","number":[3,128],"number_text":"੩। ੧੨੮।","page":265,"lines":[{"gurmukhi":"ਯਹਿ ਬ੍ਰਹਮ ਆਹਿ ਆਤਮਾ ਰਾਮ। ਜਿਹ ਅਮਿਤ ਤੇਜਿ ਅਬਿਗਤ ਅਕਾਮ।","roman":"Yahi braham aahi aatmaa raam | jih amit teji abigat akaam |","meaning_en":"\"This is Brahm, the all-pervading soul, whose radiance is boundless, unmanifest, desireless,","page":265,"meaning_status":"draft"},{"gurmukhi":"ਜਿਹ ਭੇਦ ਭਰਮ ਨਹੀ ਕਰਮ ਕਾਲ। ਜਿਹ ਸਤ੍ਰ ਮਿਤ੍ਰ ਸਰਬਾ ਦਿਆਲ। ੩। ੧੨੮।","roman":"Jih bhed bharam nahee karam kaal | jih satr mitr sarbaa diaal | 3 | 128 |","meaning_en":"who has no division, illusion, karma or death; who is merciful to enemy and friend alike.","page":265,"meaning_status":"draft"}]},{"type":"verse","number":[4,129],"number_text":"੪। ੧੨੯।","page":265,"lines":[{"gurmukhi":"ਡੋਬਿਯੋ ਨ ਡੁਬੈ ਸੋਖਿਯੋ ਨ ਜਾਇ। ਕਟਿਯੋ ਨ ਕਟੈ ਨ ਬਾਰਿਯੋ ਬਰਾਇ।","roman":"Dobiyo na dubai sokhiyo na jaai | katiyo na katai na baariyo baraai |","meaning_en":"It does not drown when drowned, it cannot be dried up; it is not cut when cut, nor burned when burned;","page":265,"meaning_status":"draft"},{"gurmukhi":"ਛਿਜੈ ਨ ਨੈਕ ਸਤ ਸਸਤ੍ਰ ਪਾਤ। ਜਿਹ ਸਤ੍ਰ ਮਿਤ੍ਰ ਨਹੀ ਜਾਤ ਪਾਤ। ੪। ੧੨੯।","roman":"Chhijai na naik sat sasatr paat | jih satr mitr nahee jaat paat | 4 | 129 |","meaning_en":"it is not hurt at all by the falling of a hundred weapons; it has no enemy or friend, caste or lineage.","page":265,"meaning_status":"draft"}]},{"type":"verse","number":[5,130],"number_text":"੫। ੧੩੦।","page":265,"lines":[{"gurmukhi":"ਸਤ੍ਰ ਸਹੰਸ ਸਤਿ ਸਤਿ ਪ੍ਰਘਾਇ। ਛਿਜੈ ਨ ਨੈਕ ਖੰਡਿਓ ਨ ਜਾਇ।","roman":"Satr sahans sati sati praghaai | chhijai na naik khandio na jaai |","meaning_en":"Though thousands of enemies strike it a hundred hundred times, it is not hurt at all, nor can it be broken;","page":265,"meaning_status":"draft"},{"gurmukhi":"ਨਹੀ ਜਰੈ ਨੈਕ ਪਾਵਕ ਮੰਝਾਰ। ਬੋਰੈ ਨ ਸਿੰਧ ਸੋਖੈ ਨ ਬ੍ਯਾਰ। ੫। ੧੩੦।","roman":"Nahee jarai naik paavak manjhaar | borai na sindh sokhai na byaar | 5 | 130 |","meaning_en":"it is not burned at all in the fire; the ocean does not drown it, the wind does not dry it.\"","page":265,"meaning_status":"draft"}]},{"type":"verse","number":[6,131],"number_text":"੬। ੧੩੧।","page":265,"lines":[{"gurmukhi":"ਇਕ ਕਰ੍ਯੋ ਪ੍ਰਸਨ ਆਤਮਾ ਦੇਵ। ਅਨਭੰਗ ਰੂਪ ਅਨਿਭਉ ਅਭੇਵ।","roman":"Ik karyo prasan aatmaa dev | anbhang roop anibhau abhev |","meaning_en":"The soul asked one question of the divine (Lord), of unbreakable form, fearless, beyond mystery:","page":265,"meaning_status":"draft"},{"gurmukhi":"ਯਹਿ ਚਤੁਰ ਵਰਗ ਸੰਸਾਰ ਦਾਨ। ਕਿਹੁ ਚਤੁਰ ਵਰਗ ਕਿਜੈ ਵਖਿਆਨ। ੬। ੧੩੧।","roman":"Yahi chatur varag sansaar daan | kihu chatur varag kijai vakhiaan | 6 | 131 |","meaning_en":"\"These four aims are the gift of the world; explain to me what these four aims are.\"","page":265,"meaning_status":"draft","note":"ਚਤੁਰ ਵਰਗ: the four aims of life."}]},{"type":"verse","number":[7,132],"number_text":"੭। ੧੩੨।","page":265,"lines":[{"gurmukhi":"ਇਕ ਰਾਜੁ ਧਰਮ ਇਕ ਦਾਨ ਧਰਮ। ਇਕ ਭੋਗ ਧਰਮ ਇਕ ਮੋਛ ਕਰਮ।","roman":"Ik raaju dharam ik daan dharam | ik bhog dharam ik mochh karam |","meaning_en":"One is the dharma of ruling, one the dharma of giving, one the dharma of enjoyment, one the work of liberation;","page":265,"meaning_status":"draft"},{"gurmukhi":"ਇਕ ਚਤੁਰ ਵਰਗ ਸਭ ਜਗ ਭਣੰਤ। ਸੇ ਆਤਮਾਹ ਪਰਾਤਮਾ ਪੁਛੰਤ। ੭। ੧੩੨।","roman":"Ik chatur varag sabh jag bhanant | se aatmaah paraatmaa puchhant | 7 | 132 |","meaning_en":"the whole world speaks of these as the four aims; this the soul asks of the Supreme Soul.","page":265,"meaning_status":"draft"}]},{"type":"verse","number":[8,133],"number_text":"੮। ੧੩੩।","page":265,"lines":[{"gurmukhi":"ਇਕ ਰਾਜ ਧਰਮ ਇਕ ਧਰਮ ਦਾਨ। ਇਕ ਭੋਗ ਧਰਮ ਇਕ ਮੋਛਵਾਨ।","roman":"Ik raaj dharam ik dharam daan | ik bhog dharam ik mochhvaan |","meaning_en":"\"One is the dharma of ruling, one the dharma of giving, one the dharma of enjoyment, one (the path of) liberation:","page":265,"meaning_status":"draft"},{"gurmukhi":"ਤੁਮ ਕਹੋ ਚਤ੍ਰ ਚਤ੍ਰੈ ਬਿਚਾਰ। ਜੇ ਤ੍ਰਿਕਾਲ ਭਏ ਜੁਗ ਅਪਾਰ। ੮। ੧੩੩।","roman":"Tum kaho chatr chatrai bichaar | je trikaal bhae jug apaar | 8 | 133 |","meaning_en":"O wise One, tell me, considering all four, of those who lived in the three times through boundless ages.\"","page":265,"meaning_status":"draft"}]},{"type":"verse","number":[9,134],"number_text":"੯। ੧੩੪।","page":265,"lines":[{"gurmukhi":"ਬਰਨੰਨ ਕਰੋ ਤੁਮ ਪ੍ਰਿਥਮ ਦਾਨ। ਜਿਮ ਦਾਨ ਧਰਮ ਕਿੰਨੇ ਨ੍ਰਿਪਾਨ।","roman":"Barnann karo tum pritham daan | jim daan dharam kinne nripaan |","meaning_en":"\"First I shall describe giving, how the kings practised the dharma of giving.","page":265,"meaning_status":"draft","note":"Speaker here appears to be the Supreme Soul; not marked in the text."},{"gurmukhi":"ਸਤਿਜੁਗ ਕਰਮ ਸੁਰ ਦਾਨ ਦੰਤ। ਭੂਮਾਦਿ ਦਾਨ ਕੀਨੇ ਅਕੰਥ। ੯। ੧੩੪।","roman":"Satijug karam sur daan dant | bhoomaadi daan keene akanth | 9 | 134 |","meaning_en":"In the Satyug the gods' deed was giving; they gave land and other gifts beyond telling.","page":265,"meaning_status":"draft","note":"ਸੁਰ ਦਾਨ ਦੰਤ: read as 'the gods gave gifts'; uncertain."}]},{"type":"verse","number":[10,135],"number_text":"੧੦। ੧੩੫।","page":265,"lines":[{"gurmukhi":"ਤ੍ਰੈ ਜੁਗ ਮਹੀਪ ਬਰਨੇ ਨ ਜਾਤ। ਗਾਥਾ ਅਨੰਤ ਉਪਮਾ ਅਗਾਤ।","roman":"Trai jug maheep barne na jaat | gaathaa anant upmaa agaat |","meaning_en":"The kings of the three ages cannot be described; their stories are endless, their praise beyond reckoning;","page":265,"meaning_status":"draft","note":"ਅਗਾਤ: read as 'beyond telling'."},{"gurmukhi":"ਜੋ ਕੀਏ ਜਗਤ ਮੈ ਜਗ ਧਰਮ। ਬਰਨੇ ਨ ਜਾਹਿ ਤੇ ਅਮਿਤ ਕਰਮ। ੧੦। ੧੩੫।","roman":"Jo kee'e jagat mai jag dharam | barne na jaahi te amit karam | 10 | 135 |","meaning_en":"the sacrifices and righteous deeds they did in the world, those boundless deeds cannot be described.","page":265,"meaning_status":"draft"}]},{"type":"verse","number":[11,136],"number_text":"੧੧। ੧੩੬।","page":265,"lines":[{"gurmukhi":"ਕਲਜੁਗ ਤੇ ਆਦਿ ਜੋ ਭਏ ਮਹੀਪ। ਇਹਿ ਭਰਥ ਖੰਡਿ ਮਹਿ ਜੰਬੂ ਦੀਪ।","roman":"Kaljug te aadi jo bhae maheep | ihi bharath khandi mahi janboo deep |","meaning_en":"Of the kings who have been from the start of the Kaliyug in this land of Bharat in Jambudvip,","page":265,"meaning_status":"draft"},{"gurmukhi":"ਤ੍ਵ ਬਲ ਪ੍ਰਤਾਪ ਬਰਣੌ ਸੁ ਤ੍ਰੈਣ। ਰਾਜਾ ਯੁਧਿਸਟ੍ਰ ਭੂ ਭਰਥ ਏਣ। ੧੧। ੧੩੬।","roman":"Tva bal prataap barnau su train | raajaa yudhisatr bhoo bharath en | 11 | 136 |","meaning_en":"I shall tell of the strength and majesty of three: (first) King Yudhishthir of the land of Bharat.","page":265,"meaning_status":"draft","note":"ਸੁ ਤ੍ਰੈਣ: 'of the three'; ਏਣ uncertain; read as 'this'."}]},{"type":"verse","number":[12,137],"number_text":"੧੨। ੧੩੭।","page":265,"lines":[{"gurmukhi":"ਖੰਡੇ ਅਖੰਡ ਜਿਹ ਚਤੁਰ ਖੰਡ। ਕੈਰੌ ਕੁਰਖੇਤ੍ਰ ਮਾਰੇ ਪ੍ਰਚੰਡ।","roman":"Khande akhand jih chatur khand | kairau kurkhetr maare prachand |","meaning_en":"He broke the unbroken (kings) of the four regions; he slew the mighty Kauravs at Kurukshetra;","page":265,"meaning_status":"draft"},{"gurmukhi":"ਜਿਹ ਚਤੁਰ ਕੁੰਡ ਜਿਤਿਯੋ ਦੁਬਾਰ। ਅਰਜਨ ਭੀਮਾਦਿ ਭ੍ਰਾਤਾ ਜੁਝਾਰ। ੧੨। ੧੩੭।","roman":"Jih chatur kund jitiyo dubaar | arjan bheemaadi bhraataa jujhaar | 12 | 137 |","meaning_en":"he conquered the four quarters twice, with his warrior brothers Arjun, Bhim and the others.","page":266,"meaning_status":"draft"}]},{"type":"verse","number":[13,138],"number_text":"੧੩। ੧੩੮।","page":266,"lines":[{"gurmukhi":"ਅਰਜਨ ਪਠਿਯੋ ਉਤਰ ਦਿਸਾਨ। ਭੀਮਹਿ ਕਰਾਇ ਪੂਰਬ ਪਯਾਨ।","roman":"Arjan pathiyo utar disaan | bheemhi karaai poorab payaan |","meaning_en":"He sent Arjun to the north; he had Bhim march to the east;","page":266,"meaning_status":"draft"},{"gurmukhi":"ਸਹਿਦੇਵ ਪਠਿਯੋ ਦਛਣ ਸੁਦੇਸ। ਨੁਕਲਹਿ ਪਠਾਇ ਪਛਮ ਪ੍ਰਵੇਸ। ੧੩। ੧੩੮।","roman":"Sahidev pathiyo dachhan sudes | nukalhi pathaai pachham praves | 13 | 138 |","meaning_en":"he sent Sahdev to the fine southern lands; he sent Nakul to enter the west.","page":266,"meaning_status":"draft","note":"Printed ਨੁਕਲਹਿ; Nakul."}]},{"type":"verse","number":[14,139],"number_text":"੧੪। ੧੩੯।","page":266,"lines":[{"gurmukhi":"ਮੰਡੇ ਮਹੀਪ ਖੰਡਿਯੋ ਖਤ੍ਰਾਣ। ਜਿਤੇ ਅਜੀਤ ਮੰਡੇ ਮਹਾਨ।","roman":"Mande maheep khandiyo khatraan | jite ajeet mande mahaan |","meaning_en":"They overcame the kings and broke the kshatriyas; they conquered the unconquered and the mighty;","page":266,"meaning_status":"draft","note":"ਮੰਡੇ: read as 'subdued'; uncertain."},{"gurmukhi":"ਖੰਡਿਯੋ ਸੁ ਉਤ੍ਰ ਖੁਰਾਸਾਨ ਦੇਸ। ਦਛਨ ਪੂਰਬ ਜੀਤੇ ਨਰੇਸ। ੧੪। ੧੩੯।","roman":"Khandiyo su utr khuraasaan des | dachhan poorab jeete nares | 14 | 139 |","meaning_en":"in the north they broke the land of Khurasan; in the south and east they conquered the kings.","page":266,"meaning_status":"draft"}]},{"type":"verse","number":[15,140],"number_text":"੧੫। ੧੪੦।","page":266,"lines":[{"gurmukhi":"ਖਗ ਖੰਡ ਖੰਡ ਜੀਤੇ ਮਹੀਪ। ਬਜਿਯੋ ਨਿਸਾਨ ਇਹ ਜੰਬੂਦੀਪ।","roman":"Khag khand khand jeete maheep | bajiyo nisaan ih janboodeep |","meaning_en":"With the sword they conquered the kings region by region; the victory drum sounded through this Jambudvip;","page":266,"meaning_status":"draft"},{"gurmukhi":"ਇਕ ਠਉਰ ਕੀਏ ਸਬ ਦੇਸ ਰਾਉ। ਮਖ ਰਾਜਸੂਅ ਕੋ ਕੀਓ ਚਾਉ। ੧੫। ੧੪੦।","roman":"Ik thaur kee'e sab des raau | makh raajsooa ko keeo chaau | 15 | 140 |","meaning_en":"he gathered all the kings of the lands in one place and longed to perform the Rajsu sacrifice.","page":266,"meaning_status":"draft"}]},{"type":"verse","number":[16,141],"number_text":"੧੬।੧੪੧।","page":266,"lines":[{"gurmukhi":"ਸਬ ਦੇਸ ਦੇਸ ਪਠੇ ਸੁ ਪਤ੍ਰ। ਜਿਤ ਜਿਤ ਗੁਨਾਢ ਕੀਏ ਇਕਤ੍ਰ।","roman":"Sab des des pathe su patr | jit jit gunaadh kee'e ikatr |","meaning_en":"He sent letters to land after land and gathered all the men of merit there were;","page":266,"meaning_status":"draft","note":"ਗੁਨਾਢ: 'rich in virtue/learning'."},{"gurmukhi":"ਮਖ ਰਾਜਸੂਅ ਕੋ ਕੀਯੋ ਅਰੰਭ। ਨ੍ਰਿਪ ਬਹੁਤ ਬੁਲਾਇ ਜਿਤੇ ਅਸੰਭ। ੧੬।੧੪੧।","roman":"Makh raajsooa ko keeyo aranbh | nrip bahut bulaai jite asanbh | 16 | 141 |","meaning_en":"he began the Rajsu sacrifice, inviting many kings, countless as they were.","page":266,"meaning_status":"draft","note":"ਜਿਤੇ ਅਸੰਭ: perhaps 'as many as were beyond counting' or 'the conquered'; uncertain."}]},{"type":"heading","kind":"chhand","name":"ਰੂਆਲ ਛੰਦ","gurmukhi":"ਰੂਆਲ ਛੰਦ","roman":"Rooaal chhand","meaning_en":"Ruaal metre.","page":266,"meaning_status":"draft"},{"type":"verse","number":[1,142],"number_text":"੧। ੧੪੨।","page":266,"lines":[{"gurmukhi":"ਕੋਟਿ ਕੋਟਿ ਬੁਲਾਇ ਰਿਤਜ ਕੋਟਿ ਬ੍ਰਹਮ ਬੁਲਾਇ।","roman":"Koti koti bulaai ritaj koti braham bulaai |","meaning_en":"He invited millions upon millions of officiating priests and millions of Brahmins;","page":266,"meaning_status":"draft","note":"ਰਿਤਜ: ritvij, sacrificial priests."},{"gurmukhi":"ਕੋਟਿ ਕੋਟਿ ਬਨਾਇ ਬਿੰਜਨ ਭੋਗੀਅਹਿ ਬਹੁ ਭਾਇ।","roman":"Koti koti banaai binjan bhogeeahi bahu bhaai |","meaning_en":"millions upon millions of dishes were prepared and enjoyed with much delight;","page":266,"meaning_status":"draft"},{"gurmukhi":"ਜਤ੍ਰ ਤਤ੍ਰ ਸਮਗ੍ਰਕਾ ਕਹੂੰ ਲਾਗ ਹੈ ਨ੍ਰਿਪਰਾਇ।","roman":"Jatr tatr samgrakaa kahoon laag hai nripraai |","meaning_en":"everywhere were provisions, and the great kings were set to serve;","page":266,"meaning_status":"draft","note":"ਕਹੂੰ ਲਾਗ ਹੈ ਨ੍ਰਿਪਰਾਇ: read as 'kings were engaged (in tasks)'; uncertain."},{"gurmukhi":"ਰਾਜਸੂਇ ਕਰਹਿ ਲਗੇ ਸਭ ਧਰਮ ਕੋ ਚਿਤ ਚਾਇ। ੧। ੧੪੨।","roman":"Raajsooi karhi lage sabh dharam ko chit chaai | 1 | 142 |","meaning_en":"they began the Rajsu, all with eager hearts for dharma.","page":266,"meaning_status":"draft"}]},{"type":"verse","number":[2,143],"number_text":"੨। ੧੪੩।","page":266,"lines":[{"gurmukhi":"ਏਕ ਏਕ ਸੁਵਰਨ ਕੋ ਦਿਜ ਏਕ ਦੀਜੈ ਭਾਰ।","roman":"Ek ek suvran ko dij ek deejai bhaar |","meaning_en":"To each Brahmin let a load of gold be given,","page":266,"meaning_status":"draft"},{"gurmukhi":"ਏਕ ਸਉ ਗਜ ਏਕ ਸਉ ਰਥਿ ਦੁਇ ਸਹੰਸ੍ਰ ਤੁਖਾਰ।","roman":"Ek sau gaj ek sau rathi dui sahansr tukhaar |","meaning_en":"a hundred elephants, a hundred chariots, two thousand horses,","page":266,"meaning_status":"draft","note":"ਤੁਖਾਰ: horses (of Tukhara breed)."},{"gurmukhi":"ਸਹੰਸ ਚਤੁਰ ਸੁਵਰਨ ਸਿੰਗੀ ਮਹਿਖ ਦਾਨ ਅਪਾਰ।","roman":"Sahans chatur suvran singee mahikh daan apaar |","meaning_en":"four thousand buffaloes with gilded horns, a boundless gift;","page":266,"meaning_status":"draft"},{"gurmukhi":"ਏਕ ਏਕਹਿ ਦੀਜੀਐ ਸੁਨ ਰਾਜ ਰਾਜ ਅਉਤਾਰ। ੨। ੧੪੩।","roman":"Ek ekhi deejeeai sun raaj raaj autaar | 2 | 143 |","meaning_en":"let this be given to each one; hear, O incarnation of the king of kings.","page":266,"meaning_status":"draft"}]},{"type":"verse","number":[3,144],"number_text":"੩। ੧੪੪।","page":266,"lines":[{"gurmukhi":"ਸੁਵਰਨ ਦਾਨ ਸੁ ਦਾਨ ਰੁਕਮ ਦਾਨ ਸੁ ਤਾਂਬ੍ਰ ਦਾਨ ਅਨੰਤ।","roman":"Suvran daan su daan rukam daan su taanbr daan anant |","meaning_en":"Gifts of gold, gifts of silver, endless gifts of copper,","page":266,"meaning_status":"draft","note":"ਰੁਕਮ: 'silver' or 'gold'; uncertain."},{"gurmukhi":"ਅੰਨ ਦਾਨ ਅਨੰਤ ਦੀਜਤ ਦੇਖ ਦੀਨ ਦੁਰੰਤ।","roman":"Ann daan anant deejat dekh deen durant |","meaning_en":"endless gifts of grain were given on seeing the poor in their hardship;","page":266,"meaning_status":"draft"},{"gurmukhi":"ਬਸਤ੍ਰ ਦਾਨ ਪਟੰਬ੍ਰ ਦਾਨ ਸੁ ਸਸਤ੍ਰ ਦਾਨ ਦਿਜੰਤ।","roman":"Basatr daan patanbr daan su sasatr daan dijant |","meaning_en":"gifts of clothing, gifts of silk, and gifts of weapons were given;","page":266,"meaning_status":"draft"},{"gurmukhi":"ਭੂਪ ਭਿਛਕ ਹੁਇ ਗਏ ਸਬ ਦੇਸ ਦੇਸ ਦੁਰੰਤ। ੩। ੧੪੪।","roman":"Bhoop bhichhak hui gae sab des des durant | 3 | 144 |","meaning_en":"the kings of all the far-off lands became like beggars (before him).","page":266,"meaning_status":"draft","note":"Line could also mean the beggars became like kings; read as written: 'kings became beggars'; uncertain."}]},{"type":"verse","number":[4,145],"number_text":"੪। ੧੪੫।","page":266,"lines":[{"gurmukhi":"ਚਤ੍ਰ ਕੋਸ ਬਨਾਹਿ ਕੁੰਡਕ ਸਹਸ੍ਰ ਲਾਇ ਪਰਨਾਰ।","roman":"Chatr kos banaahi kundak sahasr laai parnaar |","meaning_en":"Fire-pits four kos wide were made, with a thousand channels attached;","page":266,"meaning_status":"draft","note":"ਪਰਨਾਰ: read as 'drains/channels' (parnala); uncertain."},{"gurmukhi":"ਸਹੰਸ੍ਰ ਹੋਮ ਕਰੈ ਲਗੈ ਦਿਜ ਬੇਦ ਬਿਆਸ ਅਉਤਾਰ।","roman":"Sahansr hom karai lagai dij bed biaas autaar |","meaning_en":"Brahmins like incarnations of Ved Vyas began making thousands of offerings into the fire;","page":266,"meaning_status":"draft"},{"gurmukhi":"ਹਸਤ ਸੁੰਡ ਪ੍ਰਮਾਨ ਘ੍ਰਿਤ ਕੀ ਪਰਤ ਧਾਰ ਅਪਾਰ।","roman":"Hasat sund pramaan ghrit kee parat dhaar apaar |","meaning_en":"streams of ghee, as thick as an elephant's trunk, poured endlessly;","page":266,"meaning_status":"draft"},{"gurmukhi":"ਹੋਤ ਭਸਮ ਅਨੇਕ ਬਿੰਜਨ ਲਪਟ ਝਪਟ ਕਰਾਲ। ੪। ੧੪੫।","roman":"Hot bhasam anek binjan lapat jhapat karaal | 4 | 145 |","meaning_en":"countless foods were burned to ash in the dreadful leaping flames.","page":266,"meaning_status":"draft"}]},{"type":"verse","number":[5,146],"number_text":"੫। ੧੪੬।","page":267,"lines":[{"gurmukhi":"ਮ੍ਰਿਤਕਾ ਸਭ ਤੀਰਥ ਕੀ ਸਭ ਤੀਰਥ ਕੋ ਲੈ ਬਾਰ।","roman":"Mritkaa sabh teerath kee sabh teerath ko lai baar |","meaning_en":"Earth from every place of pilgrimage, water from every place of pilgrimage,","page":267,"meaning_status":"draft"},{"gurmukhi":"ਕਾਸਟਕਾ ਸਭ ਦੇਸ ਕੀ ਸਭ ਦੇਸ ਕੀ ਜਿਉਨਾਰ।","roman":"Kaasatkaa sabh des kee sabh des kee jiunaar |","meaning_en":"wood from every land, food from every land,","page":267,"meaning_status":"draft"},{"gurmukhi":"ਭਾਤ ਭਾਤਨ ਕੇ ਮਹਾ ਰਸ ਹੋਮੀਐ ਤਿਹ ਮਾਹਿ।","roman":"Bhaat bhaatan ke mahaa ras homeeai tih maahi |","meaning_en":"great juices of many kinds were offered into it;","page":267,"meaning_status":"draft"},{"gurmukhi":"ਦੇਖ ਚਕ੍ਰਤ ਰਹੈ ਦਿਜੰਬਰ ਰੀਝ ਹੀ ਨਰ ਨਾਹ। ੫। ੧੪੬।","roman":"Dekh chakrat rahai dijanbar reejh hee nar naah | 5 | 146 |","meaning_en":"seeing it, the best of Brahmins were amazed and the kings delighted.","page":267,"meaning_status":"draft"}]},{"type":"verse","number":[6,147],"number_text":"੬। ੧੪੭।","page":267,"lines":[{"gurmukhi":"ਭਾਤ ਭਾਤ ਅਨੇਕ ਬਿਜੰਨ ਹੋਮੀਐ ਤਿਹ ਆਨ।","roman":"Bhaat bhaat anek bijann homeeai tih aan |","meaning_en":"Foods of many kinds were brought and offered into it;","page":267,"meaning_status":"draft"},{"gurmukhi":"ਚਤੁਰ ਬੇਦ ਪੜੈ ਚਤ੍ਰ ਸਭ ਬਿਪ ਬ੍ਯਾਸ ਸਮਾਨ।","roman":"Chatur bed parai chatr sabh bip byaas samaan |","meaning_en":"Brahmins learned like Vyas, all wise, recited the four Vedas;","page":267,"meaning_status":"draft"},{"gurmukhi":"ਭਾਤ ਭਾਤ ਅਨੇਕ ਭੂਪਤ ਦੇਤ ਦਾਨ ਅਨੰਤ।","roman":"Bhaat bhaat anek bhoopat det daan anant |","meaning_en":"kings of many kinds gave endless gifts;","page":267,"meaning_status":"draft"},{"gurmukhi":"ਭੂਮ ਭੂਰ ਉਠੀ ਜਯਤ ਧੁਨ ਜਤ੍ਰ ਤਤ੍ਰ ਦੁਰੰਤ। ੬। ੧੪੭।","roman":"Bhoom bhoor uthee jayat dhun jatr tatr durant | 6 | 147 |","meaning_en":"the sound of victory rose over the whole earth, far and wide.","page":267,"meaning_status":"draft","note":"ਭੂਮ ਭੂਰ: 'all over the earth'; uncertain."}]},{"type":"verse","number":[7,148],"number_text":"੭। ੧੪੮।","page":267,"lines":[{"gurmukhi":"ਜੀਤ ਜੀਤ ਮਵਾਸ ਆਸਨ ਅਰਬ ਖਰਬ ਛਿਨਾਇ।","roman":"Jeet jeet mavaas aasan arab kharab chhinaai |","meaning_en":"Conquering rebel strongholds, seizing countless thrones,","page":267,"meaning_status":"draft","note":"ਮਵਾਸ: rebel strongholds; ਆਸਨ: 'seats/thrones'; uncertain."},{"gurmukhi":"ਆਨਿ ਆਨਿ ਦੀਏ ਦਿਜਾਨਨ ਜਗ ਮੈ ਕੁਰ ਰਾਇ।","roman":"Aani aani dee'e dijaanan jag mai kur raai |","meaning_en":"the Kuru king brought (wealth) and gave it to the Brahmins in the sacrifice;","page":267,"meaning_status":"draft"},{"gurmukhi":"ਭਾਤ ਭਾਤ ਅਨੇਕ ਧੂਪ ਸੁ ਧੂਪੀਐ ਤਿਹ ਆਨ।","roman":"Bhaat bhaat anek dhoop su dhoopeeai tih aan |","meaning_en":"incense of many kinds was brought and burned;","page":267,"meaning_status":"draft"},{"gurmukhi":"ਭਾਤ ਭਾਤ ਉਠੀ ਜਯ ਧੁਨਿ ਜਤ੍ਰ ਤਤ੍ਰ ਦਿਸਾਨ। ੭। ੧੪੮।","roman":"Bhaat bhaat uthee jay dhuni jatr tatr disaan | 7 | 148 |","meaning_en":"cries of victory of every kind rose in all directions.","page":267,"meaning_status":"draft"}]},{"type":"verse","number":[8,149],"number_text":"੮। ੧੪੯।","page":267,"lines":[{"gurmukhi":"ਜਰਾਸੰਧਹ ਮਾਰ ਕੈ ਪੁਨਿ ਕੈਰਵਾ ਹਥਿ ਪਾਇ।","roman":"Jaraasandhah maar kai puni kairvaa hathi paai |","meaning_en":"Having slain Jarasandh, and then bringing the Kauravs under his hand,","page":267,"meaning_status":"draft"},{"gurmukhi":"ਰਾਜਸੂਇ ਕੀਓ ਬਡੋ ਮਖਿ ਕਿਸਨ ਕੇ ਮਤਿ ਭਾਇ।","roman":"Raajsooi keeo bado makhi kisan ke mati bhaai |","meaning_en":"he performed the great Rajsu sacrifice as Krishna's counsel pleased;","page":267,"meaning_status":"draft"},{"gurmukhi":"ਰਾਜਸੂਇ ਸੁ ਕੈ ਕਿਤੇ ਦਿਨ ਜੀਤ ਸਤ੍ਰੁ ਅਨੰਤ।","roman":"Raajsooi su kai kite din jeet satru anant |","meaning_en":"some days after the Rajsu, having conquered endless enemies,","page":267,"meaning_status":"draft"},{"gurmukhi":"ਬਾਜਮੇਧ ਅਰੰਭ ਕੀਨੋ ਬੇਦ ਬ੍ਯਾਸ ਮਤੰਤ। ੮। ੧੪੯।","roman":"Baajmedh aranbh keeno bed byaas matant | 8 | 149 |","meaning_en":"he began the horse sacrifice on the counsel of Ved Vyas.","page":267,"meaning_status":"draft","note":"ਬਾਜਮੇਧ: ashvamedh, horse sacrifice."}]}],"ending":{"lines":[{"gurmukhi":"ਪ੍ਰਿਥਮ ਜਗ ਸਮਾਪਤਿਹ।","roman":"Pritham jag samaaptih |","meaning_en":"The first sacrifice is complete.","page":267,"meaning_status":"draft"}],"page":267}});
